INSERT INTO lp_resources (slug, kind, perspective, audience, urgency, evidence_level, emoji, title, summary, body, sections, reading_minutes, min_day, max_day, countries, sex, tags, is_featured, review_status, sort_order) VALUES
  ('nb-bf-first-hour', 'article', 'scientific', 'shared', 'important', 'guideline', '🌅', '{"en":"Breastfeeding: the first hour and the first days","bn":"বুকের দুধ: প্রথম ঘণ্টা ও প্রথম কয়েক দিন"}'::jsonb, '{"en":"Put your baby skin-to-skin and to the breast within the first hour. The small amount of colostrum in the first days is exactly what your baby needs.","bn":"জন্মের প্রথম ঘণ্টার মধ্যেই শিশুকে খালি বুকে নিয়ে দুধ খাওয়ানো শুরু করুন। প্রথম কয়েক দিনের অল্প শালদুধই শিশুর জন্য যথেষ্ট, আর সবচেয়ে উপকারী।"}'::jsonb, '{"en":"## The first hour\n\nIf mother and baby are well, the baby is dried right after birth and placed naked on the mother''s bare chest, with a cloth over both. This skin-to-skin contact keeps the baby warm and calm. Given time, most babies move towards the breast and begin to suckle on their own. WHO advises starting breastfeeding within this first hour.\n\nAfter a caesarean birth, skin-to-skin and the first feed can still happen as soon as the mother is awake and able. If the start is delayed for any reason, begin as soon as you can. It is never too late.\n\n## Colostrum: the first milk\n\nFor the first two or three days the breasts make colostrum, a thick, yellowish milk that comes in small amounts. It is full of antibodies that protect the baby from infection, which is why it is often called the baby''s first vaccine. A newborn''s stomach is tiny, so a few spoonfuls at a time are enough. Never throw colostrum away.\n\n## The first days\n\n- Keep the baby in the same room as the mother, close to her, day and night.\n- Feed whenever the baby shows hunger. Most newborns feed 8 to 12 times in 24 hours, including at night.\n- Around day 2 to 4 the breasts feel fuller and heavier as the milk increases. Frequent feeding helps.\n- The first stools are dark green-black and sticky (meconium). They turn yellow by about day 4 or 5.\n- Give nothing else: no water, honey, sugar water, ghutti or formula, unless a doctor says there is a medical need.\n\n## How the family can help\n\nBreastfeeding is a skill that mother and baby learn together, and confidence helps a great deal. Bring the mother water and food, help her get comfortable with pillows, and keep visitors few and short. The father, a grandmother or another relative can change nappies, burp and settle the baby between feeds so that the mother can sleep. Kind words matter more than advice.","bn":"## প্রথম ঘণ্টা\n\nমা ও শিশু সুস্থ থাকলে জন্মের পরপরই শিশুকে মুছে শুকিয়ে মায়ের খালি বুকের ওপর রাখা হয়, আর দুজনের ওপর একটা কাপড় দিয়ে ঢেকে দেওয়া হয়। ত্বকের সাথে ত্বকের এই ছোঁয়া শিশুকে উষ্ণ ও শান্ত রাখে। একটু সময় দিলে বেশিরভাগ শিশু নিজেই স্তনের দিকে এগিয়ে গিয়ে চুষতে শুরু করে। বিশ্ব স্বাস্থ্য সংস্থা (WHO) জন্মের প্রথম ঘণ্টার মধ্যেই বুকের দুধ খাওয়ানো শুরু করার পরামর্শ দেয়।\n\nসিজারের পরেও মা জেগে উঠে সক্ষম হলেই শিশুকে বুকে নেওয়া ও প্রথমবার খাওয়ানো যায়। কোনো কারণে দেরি হলে যত তাড়াতাড়ি পারেন শুরু করুন। দেরি হয়ে গেছে বলে কখনোই হাল ছাড়বেন না।\n\n## শালদুধ: প্রথম দুধ\n\nপ্রথম দুই-তিন দিন স্তনে শালদুধ (colostrum) আসে। এটা ঘন, হলদেটে, আর পরিমাণে অল্প। এতে থাকে প্রচুর রোগ-প্রতিরোধী উপাদান, যা শিশুকে সংক্রমণ থেকে বাঁচায়। তাই একে শিশুর প্রথম টিকাও বলা হয়। নবজাতকের পেট খুব ছোট, তাই একবারে কয়েক চামচ শালদুধই যথেষ্ট। শালদুধ কখনো ফেলে দেবেন না।\n\n## প্রথম কয়েক দিন\n\n- দিন-রাত শিশুকে মায়ের সাথে একই ঘরে, মায়ের কাছাকাছি রাখুন।\n- শিশু খিদের লক্ষণ দেখালেই খাওয়ান। বেশিরভাগ নবজাতক ২৪ ঘণ্টায় ৮ থেকে ১২ বার খায়, রাতেও।\n- দ্বিতীয় থেকে চতুর্থ দিনের দিকে দুধ বাড়তে থাকে, তখন স্তন ভারী ও ভরা লাগে। ঘন ঘন খাওয়ালে সুবিধা হয়।\n- প্রথম পায়খানা কালচে-সবুজ ও আঠালো হয় (meconium)। চতুর্থ-পঞ্চম দিনের মধ্যে তা হলুদ হয়ে যায়।\n- আর কিছুই দেবেন না: পানি, মধু, চিনির পানি, ঘুট্টি বা ফর্মুলা দুধ নয়, যদি না ডাক্তার চিকিৎসার প্রয়োজনে বলেন।\n\n## পরিবার যেভাবে পাশে থাকতে পারে\n\nবুকের দুধ খাওয়ানো মা ও শিশু দুজনে মিলে শেখে, আর এতে মায়ের আত্মবিশ্বাস অনেক বড় ভূমিকা রাখে। মাকে পানি ও খাবার এগিয়ে দিন, বালিশ দিয়ে আরাম করে বসতে সাহায্য করুন, আর অতিথি কম ও অল্প সময়ের জন্য রাখুন। দুই খাওয়ানোর মাঝে বাবা, নানি-দাদি বা অন্য কেউ শিশুর ন্যাপি বদলানো, ঢেকুর তোলানো ও ঘুম পাড়ানোর কাজ নিলে মা একটু ঘুমাতে পারেন। উপদেশের চেয়ে ভালো কথা আর সাহস দেওয়াই বেশি কাজে আসে।"}'::jsonb, '{"avoid":{"en":["Throwing away colostrum","Giving water, honey, sugar water, ghutti or formula before or between breastfeeds","Separating mother and baby without a medical reason"],"bn":["শালদুধ ফেলে দেওয়া","বুকের দুধের আগে বা মাঝে পানি, মধু, চিনির পানি, ঘুট্টি বা ফর্মুলা দেওয়া","চিকিৎসার কারণ ছাড়া মা ও শিশুকে আলাদা রাখা"]},"seek_help":{"en":["The baby has not fed well in the first hours or seems too sleepy to feed","No stool at all in the first day","Yellow skin on the first day","The mother has heavy bleeding, fever or severe pain"],"bn":["প্রথম কয়েক ঘণ্টায় শিশু ঠিকমতো খায়নি, বা খাওয়ার মতো জেগেই থাকছে না","প্রথম দিনে একবারও পায়খানা হয়নি","প্রথম দিনেই ত্বক হলুদ","মায়ের অতিরিক্ত রক্তপাত, জ্বর বা তীব্র ব্যথা"]}}'::jsonb, 4, 0, 14, '{}'::text[], 'any', ARRAY['breastfeeding', 'first hour', 'colostrum', 'skin to skin', 'rooming in']::text[], false, 'in_review'::lp_review_status, 3001),
  ('nb-bf-latch', 'article', 'scientific', 'shared', 'important', 'guideline', '🤱', '{"en":"Positioning and a good latch","bn":"সঠিক অবস্থান ও ঠিকভাবে মুখে নেওয়া"}'::jsonb, '{"en":"How the baby is held and how they take the breast decide whether feeding is comfortable and whether the baby gets enough milk.","bn":"শিশুকে কীভাবে ধরছেন আর শিশু কীভাবে স্তন মুখে নিচ্ছে, তার ওপরই নির্ভর করে খাওয়ানো আরামদায়ক হবে কিনা, আর শিশু যথেষ্ট দুধ পাবে কিনা।"}'::jsonb, '{"en":"## Why the latch matters\n\nA baby feeds well when they take a big mouthful of breast, not just the nipple. With a good latch the nipple sits far back in the mouth, where it is not squeezed, so feeding does not hurt and milk flows well. A shallow latch is the most common cause of sore nipples and of a baby who feeds for a long time but stays hungry.\n\n## Four points for holding the baby\n\n- The baby''s head and body are in a straight line, not twisted.\n- The baby is held close, facing the breast, tummy towards you.\n- The whole body is supported, not just the head and shoulders.\n- The baby''s nose is opposite the nipple as they come to the breast.\n\nYou can sit up, lie on your side, or hold the baby under your arm (useful after a caesarean or for twins). Any position works if these four points are met and you are comfortable. Use pillows so you are not leaning over.\n\n## Helping the baby latch\n\nTouch the nipple to the baby''s upper lip and wait for a wide-open mouth, like a yawn. Then bring the baby quickly to the breast, chin first. Bring the baby to the breast, not the breast to the baby.\n\n## Signs of a good latch\n\n- The mouth is wide open.\n- The lower lip is turned outwards.\n- The chin touches the breast.\n- More of the dark skin around the nipple (areola) shows above the top lip than below.\n- The cheeks look round, not sucked in.\n- Sucks become slow and deep, with pauses, and you may hear swallowing.\n\nThe first few sucks may feel strong, but feeding should not keep hurting. If it does, slip a clean finger into the corner of the baby''s mouth to break the suction, and try again.\n\n## After the feed\n\nA well-fed baby lets go on their own and looks relaxed. The nipple should look the same shape as before, not flattened or pinched. Offer the second breast if the baby still seems hungry.","bn":"## ঠিকভাবে মুখে নেওয়া কেন জরুরি\n\nশিশু তখনই ভালো খায় যখন সে শুধু বোঁটা নয়, স্তনের বেশ খানিকটা অংশ মুখে নেয়। ঠিকভাবে মুখে নিলে বোঁটা শিশুর মুখের অনেক ভেতরে থাকে, সেখানে চাপ পড়ে না। তাই ব্যথা লাগে না, দুধও ভালো আসে। অগভীরভাবে শুধু বোঁটা মুখে নেওয়াই বোঁটায় ঘা হওয়ার সবচেয়ে বড় কারণ। এ কারণেই অনেক শিশু অনেকক্ষণ খেয়েও পেট ভরে না।\n\n## শিশুকে ধরার চারটি দিক\n\n- শিশুর মাথা ও শরীর এক সরল রেখায় থাকবে, ঘাড় বাঁকানো নয়।\n- শিশুকে কাছে টেনে ধরুন, মুখ স্তনের দিকে, পেট আপনার পেটের দিকে।\n- শুধু মাথা-কাঁধ নয়, পুরো শরীরে ভর দিয়ে ধরুন।\n- স্তনের কাছে আনার সময় শিশুর নাক থাকবে বোঁটার ঠিক সামনে।\n\nবসে, কাত হয়ে শুয়ে, কিংবা শিশুকে বগলের নিচ দিয়ে ধরে (সিজারের পর বা যমজ শিশুর জন্য সুবিধাজনক) খাওয়াতে পারেন। এই চারটি দিক ঠিক থাকলে আর আপনি আরামে থাকলে যেকোনো অবস্থানই চলে। ঝুঁকে যেন বসতে না হয়, সেজন্য বালিশ ব্যবহার করুন।\n\n## শিশুকে মুখে নিতে সাহায্য করা\n\nবোঁটা দিয়ে শিশুর ওপরের ঠোঁটে আলতো ছুঁয়ে দিন, আর অপেক্ষা করুন কখন সে হাই তোলার মতো বড় করে মুখ খোলে। তখনই থুতনি আগে রেখে শিশুকে দ্রুত স্তনের কাছে আনুন। মনে রাখবেন, স্তন শিশুর দিকে নয়, শিশুকে স্তনের দিকে আনবেন।\n\n## ঠিকভাবে মুখে নেওয়ার লক্ষণ\n\n- মুখ বড় করে খোলা।\n- নিচের ঠোঁট বাইরের দিকে উল্টানো।\n- থুতনি স্তনে লেগে আছে।\n- বোঁটার চারপাশের কালো অংশ (areola) ওপরের ঠোঁটের ওপরে বেশি দেখা যায়, নিচে কম।\n- গাল গোল হয়ে থাকে, ভেতরে ঢুকে যায় না।\n- চোষা ধীর ও গভীর হয়, মাঝে মাঝে থামে, আর গেলার শব্দ শোনা যেতে পারে।\n\nপ্রথম কয়েকটা টানে একটু জোর লাগতে পারে, কিন্তু পুরো সময় ব্যথা থাকা উচিত নয়। ব্যথা থাকলে পরিষ্কার আঙুল শিশুর ঠোঁটের কোণে আলতো ঢুকিয়ে টান ছাড়িয়ে দিন, তারপর আবার চেষ্টা করুন।\n\n## খাওয়ানোর পর\n\nপেট ভরলে শিশু নিজেই স্তন ছেড়ে দেয় আর আরামে থাকে। বোঁটার আকার আগের মতোই থাকা উচিত, চ্যাপ্টা বা চাপা নয়। শিশু তখনো খিদে দেখালে অন্য স্তনটিও দিন।"}'::jsonb, '{"steps":{"en":["Sit or lie comfortably with your back supported","Hold the baby close, tummy to tummy, nose opposite the nipple","Touch the nipple to the top lip and wait for a wide mouth","Bring the baby to the breast chin first","Check the signs of a good latch; if it hurts, break the suction and try again"],"bn":["পিঠে ভর দিয়ে আরাম করে বসুন বা শুয়ে নিন","শিশুকে কাছে ধরুন, পেটে পেট লাগিয়ে, নাক বোঁটার সামনে রেখে","বোঁটা দিয়ে ওপরের ঠোঁট ছুঁয়ে বড় করে মুখ খোলার অপেক্ষা করুন","থুতনি আগে রেখে শিশুকে স্তনের কাছে আনুন","ঠিকভাবে মুখে নেওয়ার লক্ষণ মিলিয়ে দেখুন; ব্যথা লাগলে টান ছাড়িয়ে আবার চেষ্টা করুন"]},"seek_help":{"en":["Feeding keeps hurting even after you have tried to correct the latch","Nipples are cracked or bleeding","The baby cannot latch at all, or seems to have a tight tongue","The baby is not having enough wet nappies"],"bn":["অবস্থান ঠিক করার চেষ্টার পরও খাওয়াতে ব্যথা থাকছে","বোঁটা ফেটে গেছে বা রক্ত পড়ছে","শিশু একদমই মুখে নিতে পারছে না, বা জিভ নিচে আটকানো মনে হচ্ছে","শিশুর ভেজা ন্যাপি যথেষ্ট হচ্ছে না"]}}'::jsonb, 4, 0, 183, '{}'::text[], 'any', ARRAY['latch', 'positioning', 'attachment', 'breastfeeding position', 'sore nipples']::text[], false, 'in_review'::lp_review_status, 3002),
  ('nb-bf-colostrum-supply', 'article', 'scientific', 'shared', 'important', 'guideline', '💧', '{"en":"Colostrum and milk supply: how the body makes enough","bn":"শালদুধ ও দুধের পরিমাণ: শরীর কীভাবে যথেষ্ট দুধ তৈরি করে"}'::jsonb, '{"en":"Milk is made on demand: the more often and the better the baby feeds, the more milk the breasts make. Wet nappies and weight gain tell you the baby is getting enough.","bn":"দুধ তৈরি হয় চাহিদা অনুযায়ী: শিশু যত ঘন ঘন আর যত ভালোভাবে খায়, স্তনে তত বেশি দুধ তৈরি হয়। ভেজা ন্যাপি আর ওজন বাড়া দেখেই বোঝা যায় শিশু যথেষ্ট পাচ্ছে কিনা।"}'::jsonb, '{"en":"## From colostrum to mature milk\n\nThe breasts begin making colostrum during pregnancy. After birth it comes in small amounts that match the size of a newborn''s stomach. Over the next few days the milk becomes more plentiful and lighter in colour, and within about two weeks it settles into mature milk. Each feed starts with thinner milk that quenches thirst and moves to richer, fattier milk as the breast empties, so let the baby finish the first breast before offering the second.\n\n## Supply and demand\n\nMilk is made when milk is removed. Every time the baby suckles well, the body gets a message to make more. This is why:\n\n- Frequent feeding, day and night, builds a good supply.\n- A good latch matters as much as how often the baby feeds.\n- Giving water, formula or a dummy in place of feeds means the breast is asked for less, and makes less.\n\nMost mothers can make enough milk for their baby, and for twins. Small breasts make as much milk as large ones.\n\n## How to tell the baby is getting enough\n\n- After about day 5, six or more wet nappies a day, with pale urine.\n- Yellow, soft stools several times a day in the first weeks.\n- The baby is back to birth weight by about two weeks and keeps growing along the curve on the growth chart.\n- The baby is alert when awake and seems content after most feeds.\n\nThese signs are more reliable than how full the breasts feel or how long a feed lasts.\n\n## Times when babies feed more\n\nSome days babies want to feed much more often, especially in the evening or during growth spurts. This is not a sign that milk has run out. Following the baby''s lead for a day or two usually brings the supply up to meet the need.\n\n## Looking after the mother\n\nA mother does not need special foods to make milk, but she does need enough to eat and drink, rest, and support. Stress and pain can slow the flow of milk for a while, so a calm place to feed and a helping hand from the family make a real difference.","bn":"## শালদুধ থেকে পরিপূর্ণ দুধ\n\nগর্ভাবস্থাতেই স্তনে শালদুধ তৈরি শুরু হয়। জন্মের পর তা আসে অল্প পরিমাণে, ঠিক নবজাতকের ছোট্ট পেটের মাপে। পরের কয়েক দিনে দুধ বাড়ে, রংও হালকা হয়। মোটামুটি দুই সপ্তাহের মধ্যে তা পরিপূর্ণ দুধে পরিণত হয়। প্রতিবার খাওয়ার শুরুতে আসে পাতলা দুধ, যা তেষ্টা মেটায়। স্তন খালি হতে থাকলে আসে ঘন, চর্বিযুক্ত দুধ। তাই অন্য স্তন দেওয়ার আগে প্রথমটা শিশুকে শেষ করতে দিন।\n\n## চাহিদা আর জোগান\n\nস্তন থেকে দুধ বের হলেই নতুন দুধ তৈরি হয়। শিশু প্রতিবার ভালোভাবে চুষলে শরীর আরও দুধ বানানোর সংকেত পায়। এজন্য:\n\n- দিন-রাত ঘন ঘন খাওয়ালে দুধ ভালো আসে।\n- কতবার খাওয়াচ্ছেন তার মতোই জরুরি শিশু ঠিকভাবে মুখে নিচ্ছে কিনা।\n- খাওয়ানোর বদলে পানি, ফর্মুলা বা চুষনি দিলে স্তনের কাছে চাহিদা কমে, দুধও কমে যায়।\n\nবেশিরভাগ মা তাঁর শিশুর জন্য, এমনকি যমজের জন্যও, যথেষ্ট দুধ তৈরি করতে পারেন। ছোট স্তনেও বড় স্তনের মতোই দুধ হয়।\n\n## শিশু যথেষ্ট পাচ্ছে কিনা বুঝবেন কীভাবে\n\n- পঞ্চম দিনের পর থেকে দিনে ৬ বা তার বেশি ভেজা ন্যাপি, প্রস্রাবের রং হালকা।\n- প্রথম সপ্তাহগুলোতে দিনে কয়েকবার হলুদ, নরম পায়খানা।\n- মোটামুটি দুই সপ্তাহের মধ্যে শিশু জন্মের ওজনে ফিরে আসে, আর গ্রোথ চার্টের রেখা ধরে বাড়তে থাকে।\n- জেগে থাকলে শিশু সজাগ থাকে, আর বেশিরভাগ খাওয়ার পর তৃপ্ত দেখায়।\n\nস্তন কতটা ভরা লাগছে বা কতক্ষণ খাচ্ছে, তার চেয়ে এই লক্ষণগুলোই বেশি নির্ভরযোগ্য।\n\n## যখন শিশু বেশি বেশি খেতে চায়\n\nকোনো কোনো দিন, বিশেষ করে সন্ধ্যায় বা হঠাৎ বেড়ে ওঠার সময়ে, শিশু অনেক ঘন ঘন খেতে চায়। এর মানে এই নয় যে দুধ শেষ হয়ে গেছে। এক-দুই দিন শিশুর চাহিদামতো খাওয়ালে সাধারণত দুধও সেই চাহিদা অনুযায়ী বেড়ে যায়।\n\n## মায়ের যত্ন\n\nদুধ বাড়ানোর জন্য মায়ের বিশেষ কোনো খাবার লাগে না। তবে পেট ভরে খাওয়া, যথেষ্ট পানি, বিশ্রাম আর পাশে কেউ থাকা দরকার। দুশ্চিন্তা ও ব্যথা কিছু সময়ের জন্য দুধের প্রবাহ ধীর করে দিতে পারে। তাই শান্ত পরিবেশে খাওয়ানো আর পরিবারের সাহায্য সত্যিই অনেক কাজে দেয়।"}'::jsonb, '{"seek_help":{"en":["Fewer than six wet nappies a day after day 5, or dark urine","The baby has not regained birth weight by about two weeks","The baby is very sleepy and hard to wake for feeds","You are thinking of starting formula; talk to a health worker first"],"bn":["পঞ্চম দিনের পর দিনে ৬টির কম ভেজা ন্যাপি, বা প্রস্রাব গাঢ় রঙের","প্রায় দুই সপ্তাহেও শিশু জন্মের ওজনে ফেরেনি","শিশু খুব ঘুমকাতুরে, খাওয়ানোর জন্য জাগানো কঠিন","ফর্মুলা শুরুর কথা ভাবছেন; আগে একজন স্বাস্থ্যকর্মীর সাথে কথা বলুন"]}}'::jsonb, 4, 0, 183, '{}'::text[], 'any', ARRAY['milk supply', 'colostrum', 'enough milk', 'wet nappies', 'growth spurt']::text[], false, 'in_review'::lp_review_status, 3003),
  ('nb-bf-hunger-cues', 'article', 'scientific', 'shared', 'routine', 'guideline', '👀', '{"en":"Reading your baby''s hunger cues","bn":"শিশুর খিদের লক্ষণ বোঝা"}'::jsonb, '{"en":"Crying is a late sign of hunger. Feeding at the early cues makes latching easier and keeps both of you calmer.","bn":"কান্না খিদের শেষ দিকের লক্ষণ। শুরুর লক্ষণ দেখেই খাওয়ালে শিশু সহজে মুখে নেয়, আর মা-শিশু দুজনেই শান্ত থাকে।"}'::jsonb, '{"en":"## Feeding by the baby, not by the clock\n\nWHO advises responsive feeding: offer the breast whenever the baby shows signs of hunger, for as long as the baby wants, day and night. Newborns do not feed on a neat schedule. Some feeds are short, some are long, and sometimes feeds come close together. Most young babies feed 8 to 12 times in 24 hours.\n\n## Early cues: “I''m getting hungry”\n\n- Stirring, moving the head, opening the eyes\n- Opening the mouth, licking the lips\n- Turning the head to the side with an open mouth (rooting)\n- Sucking on hands, fingers or clothes\n\n## Middle cues: “I''m really hungry”\n\n- Stretching and wriggling more\n- Bringing the hands to the mouth again and again\n- Fussing, small sounds, breathing faster\n\n## Late cues: “Calm me, then feed me”\n\n- Crying, a red face, turning the head from side to side\n\nA baby who is already crying hard may find it hard to latch. Calm them first: hold them skin-to-skin, talk softly, rock gently, then offer the breast.\n\n## Signs the baby has had enough\n\nThe baby lets go of the breast, the hands and body relax, and they may fall asleep. You do not need to watch the clock or force more.\n\n## Not every cry is hunger\n\nBabies also cry when they are tired, too hot or cold, need a nappy change, want to be held, or have wind. Feeding is often a comfort too, and that is fine with breastfeeding. Over the weeks you will learn your own baby''s signals. Fathers and grandparents can learn them as well and bring the baby to the mother early, before crying starts.\n\n## Sleepy newborns\n\nIn the first weeks some babies sleep through their cues. If your newborn is not feeding at least 8 times a day, or is not waking for feeds, gently wake them by unwrapping, changing the nappy or holding them skin-to-skin, and tell a health worker.","bn":"## ঘড়ি দেখে নয়, শিশুকে দেখে খাওয়ানো\n\nবিশ্ব স্বাস্থ্য সংস্থা চাহিদামতো খাওয়ানোর পরামর্শ দেয়: শিশু যখনই খিদের লক্ষণ দেখাবে, দিনে হোক বা রাতে, তখনই স্তন দিন, আর যতক্ষণ খেতে চায় খেতে দিন। নবজাতক বাঁধা নিয়মে খায় না। কখনো অল্প খায়, কখনো অনেকক্ষণ, কখনো আবার একটু পরপরই খেতে চায়। বেশিরভাগ ছোট শিশু ২৪ ঘণ্টায় ৮ থেকে ১২ বার খায়।\n\n## শুরুর লক্ষণ: “খিদে পাচ্ছে”\n\n- নড়াচড়া করা, মাথা নাড়া, চোখ খোলা\n- মুখ খোলা, ঠোঁট চাটা\n- মুখ খুলে একপাশে মাথা ঘোরানো, যেন স্তন খুঁজছে\n- হাত, আঙুল বা কাপড় চোষা\n\n## মাঝের লক্ষণ: “খুব খিদে পেয়েছে”\n\n- হাত-পা টানটান করা, বেশি মোচড়ানো\n- বারবার হাত মুখে আনা\n- উসখুস করা, ছোট ছোট শব্দ, শ্বাস দ্রুত হওয়া\n\n## শেষের লক্ষণ: “আগে শান্ত করো, তারপর খাওয়াও”\n\n- কান্না, মুখ লাল হয়ে যাওয়া, এদিক-ওদিক মাথা ঝাঁকানো\n\nজোরে কাঁদতে থাকা শিশুর পক্ষে স্তন মুখে নেওয়া কঠিন। আগে শান্ত করুন: খালি বুকে জড়িয়ে ধরুন, নরম স্বরে কথা বলুন, আলতো দোলান, তারপর স্তন দিন।\n\n## পেট ভরার লক্ষণ\n\nশিশু নিজেই স্তন ছেড়ে দেয়, হাতের মুঠি আর শরীর ঢিলে হয়ে আসে, অনেক সময় ঘুমিয়ে পড়ে। ঘড়ি দেখার বা জোর করে আরও খাওয়ানোর দরকার নেই।\n\n## সব কান্নাই খিদের নয়\n\nক্লান্তি, বেশি গরম বা ঠান্ডা, ভেজা ন্যাপি, কোলে ওঠার ইচ্ছা বা পেটে বাতাস থাকলেও শিশু কাঁদে। অনেক সময় বুকের দুধ খাওয়া শিশুর কাছে সান্ত্বনাও, আর তাতে কোনো ক্ষতি নেই। কয়েক সপ্তাহেই আপনি নিজের শিশুর সংকেত চিনে ফেলবেন। বাবা ও নানি-দাদিরাও এগুলো শিখে নিতে পারেন, আর কান্না শুরুর আগেই শিশুকে মায়ের কাছে এনে দিতে পারেন।\n\n## ঘুমকাতুরে নবজাতক\n\nপ্রথম সপ্তাহগুলোতে কিছু শিশু খিদের সময়েও ঘুমিয়ে থাকে। শিশু দিনে অন্তত ৮ বার না খেলে, বা খাওয়ার জন্য না জাগলে, কাপড় একটু খুলে, ন্যাপি বদলে বা খালি বুকে নিয়ে আলতো করে জাগান, আর স্বাস্থ্যকর্মীকে জানান।"}'::jsonb, '{}'::jsonb, 3, 0, 183, '{}'::text[], 'any', ARRAY['hunger cues', 'responsive feeding', 'feeding on demand', 'night feeds', 'crying']::text[], false, 'in_review'::lp_review_status, 3004),
  ('nb-bf-pain-engorgement', 'article', 'scientific', 'mother', 'important', 'guideline', '🩹', '{"en":"Sore nipples, full breasts and other difficulties","bn":"বোঁটায় ব্যথা, ফুলে ওঠা স্তন ও অন্যান্য সমস্যা"}'::jsonb, '{"en":"Most breastfeeding pain has a cause that can be fixed, usually the latch or milk staying too long in the breast. Keep feeding while you sort it out.","bn":"বুকের দুধ খাওয়ানোর বেশিরভাগ ব্যথার কারণ ঠিক করা যায়, সাধারণত মুখে নেওয়ার ভুল বা স্তনে দুধ জমে থাকা। সমস্যা সারানোর সময়ও খাওয়ানো চালিয়ে যান।"}'::jsonb, '{"en":"## Sore or cracked nipples\n\nTenderness in the first days is common, but pain that lasts through the feed, or cracks and bleeding, usually means the baby is not latching deeply enough.\n\n- Check the latch at every feed: wide mouth, lower lip turned out, chin on the breast.\n- Start on the less sore side, and change positions.\n- After feeds, rub a few drops of your own milk on the nipple and let it dry in the air.\n- Wear loose, clean cotton. Wash with plain water; avoid soap on the nipples.\n\n## Engorgement: hard, heavy, painful breasts\n\nWhen the milk increases in the first days, or when feeds are missed, the breasts can become swollen, hard and painful. The baby may struggle to latch on a very full breast.\n\n- Feed often, day and night.\n- If the breast is too hard to latch, hand-express a little milk first to soften the area around the nipple.\n- A warm cloth before a feed may help the milk flow; a cool cloth after a feed can ease swelling.\n- Gently massage towards the nipple while the baby feeds.\n\n## Blocked duct\n\nA tender lump in one part of the breast, without fever, is often a blocked duct. Keep feeding from that side first, massage the lump gently towards the nipple during the feed, and try different positions. It usually eases in a day or two.\n\n## Mastitis\n\nIf part of the breast becomes red, hot and painful and you feel feverish or unwell, this may be mastitis. Keep breastfeeding or expressing from that breast; the milk is safe for the baby, and emptying the breast helps healing. Rest, drink plenty, and see a health worker the same day, as you may need treatment. A lump that stays painful and swollen can be an abscess and needs a doctor.\n\n## Other causes of pain\n\nWhite patches in the baby''s mouth with burning nipple pain can be thrush. A baby who cannot lift the tongue well may have a tongue-tie. Both are worth showing to a health worker.\n\nPain is a reason to get help, not a reason to stop. With the right support most mothers can keep breastfeeding comfortably.","bn":"## বোঁটায় ব্যথা বা ফাটা\n\nপ্রথম কয়েক দিন বোঁটায় একটু ব্যথা হওয়া স্বাভাবিক। কিন্তু খাওয়ানোর পুরো সময় ব্যথা থাকলে, কিংবা বোঁটা ফেটে রক্ত পড়লে, সাধারণত বুঝতে হবে শিশু যথেষ্ট গভীরভাবে মুখে নিচ্ছে না।\n\n- প্রতিবার খাওয়ানোর সময় খেয়াল করুন: মুখ বড় করে খোলা, নিচের ঠোঁট উল্টানো, থুতনি স্তনে।\n- যে পাশে ব্যথা কম, সেদিক থেকে শুরু করুন, আর অবস্থান বদলে বদলে খাওয়ান।\n- খাওয়ানোর পর নিজের কয়েক ফোঁটা দুধ বোঁটায় লাগিয়ে বাতাসে শুকাতে দিন।\n- ঢিলেঢালা, পরিষ্কার সুতির কাপড় পরুন। বোঁটা শুধু পানি দিয়ে ধুয়ে নিন, সাবান লাগাবেন না।\n\n## স্তন ফুলে শক্ত ও ব্যথা হওয়া\n\nপ্রথম কয়েক দিনে দুধ বাড়লে, কিংবা খাওয়ানো বাদ পড়লে, স্তন ফুলে শক্ত হয়ে ব্যথা করতে পারে। খুব ভরা স্তনে শিশু মুখে নিতেও কষ্ট পায়।\n\n- দিন-রাত ঘন ঘন খাওয়ান।\n- স্তন বেশি শক্ত হলে আগে হাত দিয়ে একটু দুধ বের করে বোঁটার চারপাশ নরম করে নিন।\n- খাওয়ানোর আগে কুসুম গরম কাপড়ের সেঁক দুধ নামাতে সাহায্য করতে পারে; খাওয়ানোর পর ঠান্ডা কাপড় ফোলা কমায়।\n- শিশু খাওয়ার সময় বোঁটার দিকে আলতো করে মালিশ করুন।\n\n## দুধের নালি বন্ধ হওয়া\n\nস্তনের এক জায়গায় ব্যথাযুক্ত দলা, কিন্তু জ্বর নেই, এমন হলে প্রায়ই তা দুধের নালি বন্ধ হওয়া। ওই পাশ থেকে আগে খাওয়ান, খাওয়ানোর সময় দলাটা বোঁটার দিকে আলতো করে মালিশ করুন, আর ভিন্ন ভিন্ন অবস্থানে খাওয়ান। সাধারণত এক-দুই দিনে কমে যায়।\n\n## স্তনপ্রদাহ (mastitis)\n\nস্তনের কোনো অংশ লাল, গরম ও ব্যথাযুক্ত হলে, সাথে জ্বর জ্বর বা অসুস্থ লাগলে, এটা স্তনপ্রদাহ হতে পারে। ওই স্তন থেকে খাওয়ানো বা দুধ বের করা চালিয়ে যান; দুধ শিশুর জন্য নিরাপদ, আর স্তন খালি হলে তাড়াতাড়ি সারে। বিশ্রাম নিন, বেশি করে পানি খান, আর সেদিনই স্বাস্থ্যকর্মী দেখান, কারণ চিকিৎসা লাগতে পারে। ব্যথাযুক্ত ফোলা দলা না কমলে তা ফোড়া হতে পারে, তখন অবশ্যই ডাক্তার দেখাতে হবে।\n\n## ব্যথার অন্য কারণ\n\nশিশুর মুখে সাদা দাগ আর বোঁটায় জ্বালাপোড়া ব্যথা হলে তা ছত্রাকের সংক্রমণ হতে পারে। শিশু জিভ ঠিকমতো তুলতে না পারলে জিভের নিচে বাঁধন (tongue-tie) থাকতে পারে। দুটোই স্বাস্থ্যকর্মীকে দেখানো ভালো।\n\nব্যথা মানে সাহায্য নেওয়ার সময়, থেমে যাওয়ার নয়। সঠিক সহায়তা পেলে বেশিরভাগ মা আরামেই বুকের দুধ খাওয়ানো চালিয়ে যেতে পারেন।"}'::jsonb, '{"seek_help":{"en":["Fever, or a red, hot, painful area on the breast","A painful lump that does not ease in two days","Cracks or bleeding that do not heal","White patches in the baby''s mouth with nipple pain"],"bn":["জ্বর, বা স্তনের কোনো অংশ লাল, গরম ও ব্যথাযুক্ত","ব্যথাযুক্ত দলা দুই দিনেও না কমা","ফাটা বা রক্তপাত না সারা","শিশুর মুখে সাদা দাগ, সাথে বোঁটায় ব্যথা"]}}'::jsonb, 4, 0, 183, '{}'::text[], 'any', ARRAY['engorgement', 'mastitis', 'blocked duct', 'sore nipples', 'breast pain']::text[], false, 'in_review'::lp_review_status, 3005),
  ('nb-bf-expressing-storing', 'article', 'scientific', 'shared', 'routine', 'consensus', '🧊', '{"en":"Expressing and storing breast milk","bn":"বুকের দুধ বের করা ও সংরক্ষণ"}'::jsonb, '{"en":"Hand-expressing lets your baby have your milk when you cannot feed directly: for a small or sick baby, when breasts are too full, or when you go back to work.","bn":"সরাসরি খাওয়াতে না পারলেও হাতে দুধ বের করে শিশুকে নিজের দুধ খাওয়ানো যায়: ছোট বা অসুস্থ শিশুর জন্য, স্তন বেশি ভরে গেলে, বা কাজে ফেরার পর।"}'::jsonb, '{"en":"## When expressing helps\n\n- The baby is small, preterm or ill and cannot suckle well yet.\n- The breasts are too full for the baby to latch.\n- Mother and baby are apart for a while, for example when the mother returns to work.\n- To keep the supply going if the baby cannot feed for a time.\n\n## Hand expression, step by step\n\n1. Wash your hands with soap and water. Use a clean cup or bowl with a wide mouth.\n2. Sit comfortably and lean slightly forward. A warm cloth on the breast, gentle massage, or holding or looking at your baby helps the milk flow.\n3. Place your thumb above and your fingers below the dark area around the nipple, about two to three fingers'' width from the nipple tip.\n4. Press back towards your chest, then gently squeeze thumb and fingers together. Release and repeat in a rhythm.\n5. Move your fingers around the breast to empty all parts. Change breasts when the flow slows.\n\nIt can take a few minutes before drops come. It should not hurt. In the first days you will get only drops of colostrum, which are precious; collect them in a spoon or small cup.\n\nTo build or keep a supply when the baby cannot feed, express often, about as often as a baby would feed, including at night.\n\n## Storing expressed milk\n\nUse a clean, covered container and write the time on it. Commonly used guidance is:\n\n- At room temperature: use within about 4 hours, sooner in hot weather.\n- In a refrigerator: use within about 4 days, kept at the back, not in the door.\n- In a freezer: can be kept for months; thaw in the refrigerator or in a bowl of warm water.\n\nDo not boil breast milk or heat it in a microwave. Swirl gently before feeding. Throw away milk left over after a feed.\n\n## Feeding expressed milk\n\nWHO advises giving expressed milk by a small open cup or spoon rather than a bottle. Cups are easier to keep clean, and bottles can make it harder for some babies to go back to the breast. Hold the baby upright and let them lap or sip at their own pace; do not pour milk into the mouth.","bn":"## কখন দুধ বের করা কাজে দেয়\n\n- শিশু ছোট, অপরিণত বা অসুস্থ, এখনো ভালোভাবে চুষতে পারে না।\n- স্তন এত ভরা যে শিশু মুখে নিতে পারছে না।\n- কিছু সময়ের জন্য মা ও শিশু আলাদা, যেমন মা কাজে ফিরেছেন।\n- কোনো কারণে শিশু কিছুদিন সরাসরি খেতে না পারলে দুধ চালু রাখতে।\n\n## হাতে দুধ বের করার ধাপ\n\n1. সাবান-পানি দিয়ে হাত ধুয়ে নিন। চওড়া মুখের একটা পরিষ্কার কাপ বা বাটি নিন।\n2. আরাম করে বসে একটু সামনে ঝুঁকুন। স্তনে কুসুম গরম কাপড়, আলতো মালিশ, কিংবা শিশুকে কোলে নেওয়া বা তার দিকে তাকিয়ে থাকা দুধ নামাতে সাহায্য করে।\n3. বোঁটার আগা থেকে দুই-তিন আঙুল দূরে, কালো অংশের ওপরে বুড়ো আঙুল আর নিচে বাকি আঙুলগুলো রাখুন।\n4. প্রথমে বুকের দিকে পেছনে চাপ দিন, তারপর বুড়ো আঙুল ও অন্য আঙুল আলতো করে কাছাকাছি আনুন। ছেড়ে দিন, আবার করুন, একটা ছন্দে।\n5. আঙুলের জায়গা ঘুরিয়ে ঘুরিয়ে স্তনের সব অংশ থেকে দুধ বের করুন। প্রবাহ কমে এলে অন্য স্তনে যান।\n\nফোঁটা আসতে কয়েক মিনিট লাগতে পারে। ব্যথা হওয়া উচিত নয়। প্রথম কয়েক দিন শুধু কয়েক ফোঁটা শালদুধ আসবে, যা অত্যন্ত মূল্যবান; চামচ বা ছোট কাপে জমিয়ে নিন।\n\nশিশু সরাসরি খেতে না পারলে দুধ তৈরি চালু রাখতে ঘন ঘন দুধ বের করুন, শিশু যত ঘন ঘন খেত প্রায় ততবার, রাতেও।\n\n## বের করা দুধ সংরক্ষণ\n\nঢাকনাওয়ালা পরিষ্কার পাত্র ব্যবহার করুন, গায়ে সময় লিখে রাখুন। সাধারণত যে নির্দেশনা মানা হয়:\n\n- ঘরের তাপমাত্রায়: মোটামুটি ৪ ঘণ্টার মধ্যে খাওয়ান, গরমের দিনে আরও আগে।\n- ফ্রিজে: মোটামুটি ৪ দিনের মধ্যে; দরজার তাকে নয়, ভেতরের দিকে রাখুন।\n- ডিপ ফ্রিজে: কয়েক মাস রাখা যায়; ফ্রিজের নিচের অংশে রেখে বা কুসুম গরম পানির বাটিতে বসিয়ে গলান।\n\nবুকের দুধ ফোটাবেন না, মাইক্রোওয়েভে গরম করবেন না। খাওয়ানোর আগে আলতো করে ঘুরিয়ে মিশিয়ে নিন। খাওয়ানোর পর বেঁচে যাওয়া দুধ ফেলে দিন।\n\n## বের করা দুধ খাওয়ানো\n\nবিশ্ব স্বাস্থ্য সংস্থা ফিডারের বদলে ছোট খোলা কাপ বা চামচে বের করা দুধ খাওয়াতে বলে। কাপ পরিষ্কার রাখা সহজ, আর ফিডারে খেলে কিছু শিশু পরে স্তনে ফিরতে চায় না। শিশুকে সোজা করে ধরুন, আর নিজের গতিতে চুমুক দিতে দিন; মুখে দুধ ঢেলে দেবেন না।"}'::jsonb, '{"avoid":{"en":["Boiling breast milk or heating it in a microwave","Keeping leftover milk from a feed for later","Feeding by bottle when a cup or spoon will do"],"bn":["বুকের দুধ ফোটানো বা মাইক্রোওয়েভে গরম করা","খাওয়ানোর পর বেঁচে যাওয়া দুধ পরে খাওয়ানোর জন্য রেখে দেওয়া","কাপ বা চামচে চললেও ফিডারে খাওয়ানো"]}}'::jsonb, 4, 0, 183, '{}'::text[], 'any', ARRAY['expressing milk', 'hand expression', 'storing breast milk', 'cup feeding', 'working mother']::text[], false, 'in_review'::lp_review_status, 3006),
  ('nb-bf-small-sick-babies', 'article', 'scientific', 'shared', 'important', 'guideline', '🏥', '{"en":"Breastfeeding premature, small or sick babies, and other special situations","bn":"অপরিণত, ছোট বা অসুস্থ শিশু ও অন্যান্য বিশেষ পরিস্থিতিতে বুকের দুধ"}'::jsonb, '{"en":"Babies who are born early, small or sick need their mother''s milk more, not less. With support, most can be fed breast milk from the start.","bn":"সময়ের আগে জন্মানো, ছোট বা অসুস্থ শিশুর জন্য মায়ের দুধ আরও বেশি দরকার। সঠিক সহায়তা পেলে বেশিরভাগ শিশুকে শুরু থেকেই বুকের দুধ খাওয়ানো যায়।"}'::jsonb, '{"en":"## Premature and low birth weight babies\n\nA baby born before 37 weeks, or weighing less than 2.5 kg at birth, has extra needs. Mother''s own milk protects these babies from serious infections and helps them grow. WHO advises giving them their mother''s milk, and keeping them skin-to-skin (kangaroo mother care) as much as possible.\n\nSmall babies may tire quickly or not yet have a strong suck. Depending on how small and how well they are, they may be fed:\n\n- at the breast, with short, frequent feeds;\n- with expressed milk by cup or spoon, followed by time at the breast;\n- with expressed milk by tube in hospital, until they can suck.\n\nStart expressing within the first hours if the baby cannot feed, and express often, day and night. Even small amounts of colostrum matter. Hospital staff will tell you how much the baby needs and whether any extra is medically needed.\n\n## Twins\n\nMost mothers can make enough milk for two. You can feed one at a time or both together, for example with each baby held under an arm. Ask for help to find positions that work.\n\n## After a caesarean\n\nYou can breastfeed after a caesarean. Lying on your side, or holding the baby under your arm, keeps pressure off the wound. Ask for help lifting the baby in the first days.\n\n## When the baby is ill\n\nA sick baby still needs breast milk, often more often and in smaller amounts. If the baby has diarrhoea, keep breastfeeding. If the baby is too weak to suck, express and feed by cup, and get medical help.\n\n## When the mother is ill or needs medicine\n\nMost common illnesses, such as a cold or fever, are not a reason to stop. Most medicines are safe while breastfeeding, but always tell the doctor or pharmacist that you are breastfeeding. Mothers living with HIV, hepatitis or other long-term conditions should follow their health worker''s advice; in many cases breastfeeding can continue with treatment.\n\n## Babies with special needs\n\nBabies with a cleft lip or palate, Down syndrome or other conditions can often have breast milk, at the breast or by cup. They may need more time, patience and skilled support.","bn":"## অপরিণত ও কম ওজনের শিশু\n\n৩৭ সপ্তাহের আগে জন্মানো, বা জন্মের সময় ২.৫ কেজির কম ওজনের শিশুর বাড়তি যত্ন লাগে। মায়ের নিজের দুধ এই শিশুদের মারাত্মক সংক্রমণ থেকে বাঁচায় আর বাড়তে সাহায্য করে। বিশ্ব স্বাস্থ্য সংস্থা এদের মায়ের দুধ খাওয়াতে, আর যতটা সম্ভব মায়ের বুকে ত্বকের সাথে ত্বক লাগিয়ে (ক্যাঙ্গারু মাদার কেয়ার) রাখতে বলে।\n\nছোট শিশু তাড়াতাড়ি ক্লান্ত হয়ে যেতে পারে, চোষার জোরও কম থাকতে পারে। শিশু কত ছোট আর কতটা সুস্থ, সেই অনুযায়ী খাওয়ানো হয়:\n\n- সরাসরি স্তনে, অল্প সময় ধরে কিন্তু ঘন ঘন;\n- কাপ বা চামচে বের করা দুধ, তারপর কিছুক্ষণ স্তনে;\n- হাসপাতালে নলের মাধ্যমে বের করা দুধ, যতদিন না চুষতে পারে।\n\nশিশু খেতে না পারলে প্রথম কয়েক ঘণ্টার মধ্যেই দুধ বের করা শুরু করুন, আর দিন-রাত ঘন ঘন বের করুন। কয়েক ফোঁটা শালদুধও অনেক মূল্যবান। শিশুর কতটা লাগবে, আর চিকিৎসার প্রয়োজনে বাড়তি কিছু লাগবে কিনা, তা হাসপাতালের কর্মীরা বলে দেবেন।\n\n## যমজ শিশু\n\nবেশিরভাগ মা দুই শিশুর জন্যও যথেষ্ট দুধ তৈরি করতে পারেন। একজন একজন করে, বা দুজনকে একসাথে খাওয়াতে পারেন, যেমন দুই বগলের নিচে দুজনকে ধরে। কোন অবস্থান সুবিধার, তা খুঁজে পেতে সাহায্য নিন।\n\n## সিজারের পর\n\nসিজারের পরেও বুকের দুধ খাওয়ানো যায়। কাত হয়ে শুয়ে, বা শিশুকে বগলের নিচ দিয়ে ধরে খাওয়ালে সেলাইয়ের জায়গায় চাপ পড়ে না। প্রথম কয়েক দিন শিশুকে তুলে দেওয়ার জন্য কারও সাহায্য নিন।\n\n## শিশু অসুস্থ হলে\n\nঅসুস্থ শিশুরও বুকের দুধ দরকার, অনেক সময় অল্প অল্প করে আরও ঘন ঘন। ডায়রিয়া হলেও বুকের দুধ চালিয়ে যান। শিশু চুষতে না পারার মতো দুর্বল হলে দুধ বের করে কাপে খাওয়ান, আর চিকিৎসা নিন।\n\n## মা অসুস্থ হলে বা ওষুধ খেলে\n\nসর্দি-জ্বরের মতো সাধারণ অসুখে বুকের দুধ বন্ধ করার দরকার নেই। বেশিরভাগ ওষুধই বুকের দুধ খাওয়ানোর সময় নিরাপদ, তবে ডাক্তার বা ফার্মেসিতে সবসময় জানিয়ে দিন যে আপনি বুকের দুধ খাওয়াচ্ছেন। এইচআইভি, হেপাটাইটিস বা অন্য দীর্ঘমেয়াদি অসুখ থাকলে স্বাস্থ্যকর্মীর পরামর্শ মেনে চলুন; অনেক ক্ষেত্রেই চিকিৎসার সাথে বুকের দুধ চালিয়ে যাওয়া যায়।\n\n## বিশেষ চাহিদার শিশু\n\nঠোঁটকাটা বা তালুকাটা, ডাউন সিনড্রোম বা অন্য কোনো অবস্থার শিশুও প্রায়ই স্তনে বা কাপে বুকের দুধ খেতে পারে। তাদের জন্য একটু বেশি সময়, ধৈর্য আর দক্ষ কারও সাহায্য লাগতে পারে।"}'::jsonb, '{"seek_help":{"en":["A small baby who is too sleepy or weak to feed","A small baby who feels cold even when wrapped","Any newborn danger sign"],"bn":["ছোট শিশু খাওয়ার মতো জেগে থাকছে না বা খুব দুর্বল","ঢেকে রাখার পরও ছোট শিশুর গা ঠান্ডা","নবজাতকের যেকোনো বিপদচিহ্ন"]}}'::jsonb, 4, 0, 183, '{}'::text[], 'any', ARRAY['preterm', 'low birth weight', 'twins', 'caesarean', 'kangaroo care', 'sick baby']::text[], false, 'in_review'::lp_review_status, 3007),
  ('nb-bf-when-to-get-help', 'article', 'scientific', 'shared', 'important', 'guideline', '🤝', '{"en":"When and where to get breastfeeding help","bn":"বুকের দুধ খাওয়ানোয় কখন ও কোথায় সাহায্য নেবেন"}'::jsonb, '{"en":"Asking for help early is a sign of good care, not of failure. Many feeding problems are easy to fix in the first days and harder later.","bn":"শুরুতেই সাহায্য চাওয়া ভালো যত্নের লক্ষণ, ব্যর্থতার নয়। খাওয়ানোর অনেক সমস্যা প্রথম দিকে সহজেই ঠিক হয়, পরে কঠিন হয়ে যায়।"}'::jsonb, '{"en":"## Get help soon if\n\n- Feeding hurts all the way through, or your nipples are cracked or bleeding.\n- The baby cannot latch, or slips off again and again.\n- After day 5 the baby has fewer than six wet nappies a day, or the urine is dark.\n- The baby has not regained birth weight by about two weeks, or is not gaining well at check-ups.\n- The baby seems hungry after almost every feed, or feeds for very long times without settling.\n- A part of your breast is red, hot and painful, or you have a fever.\n- You feel low, anxious or ready to give up.\n- Someone is advising you to give formula and you are not sure it is needed.\n\n## Go to a hospital today if\n\n- The baby is not feeding, or is too sleepy or weak to feed.\n- The baby shows any newborn danger sign, such as fast breathing, fits, a fever or feeling cold, or yellow palms and soles.\n\n## Where to find help in Bangladesh\n\n- The health worker or doctor who sees you at your postnatal check-ups.\n- Your community clinic, Union health and family welfare centre, or Upazila Health Complex.\n- Hospitals and maternity units, many of which have staff trained in breastfeeding counselling.\n- Your own doctor or paediatrician.\n\nWhen you go, it helps to bring the baby and to feed in front of the health worker, so they can watch the latch. Tell them how many feeds and wet nappies there have been, and what the baby has been given apart from breast milk.\n\n## How the family can help\n\nSupport from the people around a mother makes breastfeeding more likely to succeed. A father or grandmother can go with her to the clinic, take over household work, and protect her from pressure to give other milk. If relatives worry the baby is hungry, the best answer is a check by a health worker, not a bottle.\n\nIf, after support, a mother cannot breastfeed or chooses not to, the health worker can explain safe alternatives. Every mother deserves respect and help, whatever her situation.","bn":"## তাড়াতাড়ি সাহায্য নিন যদি\n\n- খাওয়ানোর পুরো সময় ব্যথা হয়, বা বোঁটা ফেটে রক্ত পড়ে।\n- শিশু মুখে নিতে পারছে না, বা বারবার ছুটে যাচ্ছে।\n- পঞ্চম দিনের পর দিনে ৬টির কম ভেজা ন্যাপি হচ্ছে, বা প্রস্রাব গাঢ়।\n- প্রায় দুই সপ্তাহেও শিশু জন্মের ওজনে ফেরেনি, বা চেকআপে ওজন ঠিকমতো বাড়ছে না।\n- প্রায় প্রতিবার খাওয়ার পরও শিশু ক্ষুধার্ত মনে হয়, বা অনেকক্ষণ খেয়েও শান্ত হয় না।\n- স্তনের কোনো অংশ লাল, গরম ও ব্যথাযুক্ত, বা আপনার জ্বর।\n- মন খুব খারাপ, দুশ্চিন্তা হচ্ছে, বা হাল ছেড়ে দিতে ইচ্ছা করছে।\n- কেউ ফর্মুলা দিতে বলছেন, কিন্তু আপনি নিশ্চিত নন যে সত্যিই দরকার।\n\n## আজই হাসপাতালে যান যদি\n\n- শিশু খাচ্ছে না, বা খাওয়ার মতো জেগে থাকছে না, খুব দুর্বল।\n- নবজাতকের কোনো বিপদচিহ্ন দেখা যায়, যেমন দ্রুত শ্বাস, খিঁচুনি, জ্বর বা গা ঠান্ডা, কিংবা হাতের তালু ও পায়ের তলা হলুদ।\n\n## বাংলাদেশে কোথায় সাহায্য পাবেন\n\n- প্রসব-পরবর্তী চেকআপে যে স্বাস্থ্যকর্মী বা ডাক্তার আপনাকে দেখেন।\n- কমিউনিটি ক্লিনিক, ইউনিয়ন স্বাস্থ্য ও পরিবার কল্যাণ কেন্দ্র, বা উপজেলা স্বাস্থ্য কমপ্লেক্স।\n- হাসপাতাল ও প্রসূতি বিভাগ; অনেক জায়গায় বুকের দুধ বিষয়ে প্রশিক্ষিত কর্মী আছেন।\n- আপনার নিজের ডাক্তার বা শিশু বিশেষজ্ঞ।\n\nযাওয়ার সময় শিশুকে সাথে নিন, আর স্বাস্থ্যকর্মীর সামনে খাওয়ান, যাতে তিনি দেখতে পারেন শিশু কীভাবে মুখে নিচ্ছে। দিনে কতবার খাচ্ছে, কয়টা ভেজা ন্যাপি হচ্ছে, আর বুকের দুধ ছাড়া কিছু দেওয়া হয়েছে কিনা, তা জানান।\n\n## পরিবার যেভাবে সাহায্য করতে পারে\n\nআশপাশের মানুষের সমর্থন পেলে বুকের দুধ খাওয়ানো সফল হওয়ার সম্ভাবনা বাড়ে। বাবা বা নানি-দাদি মায়ের সাথে ক্লিনিকে যেতে পারেন, সংসারের কাজ সামলাতে পারেন, আর অন্য দুধ দেওয়ার চাপ থেকে মাকে আড়াল করতে পারেন। আত্মীয়রা যদি ভাবেন শিশুর পেট ভরছে না, তার সেরা উত্তর হলো স্বাস্থ্যকর্মীকে দেখানো, ফিডার নয়।\n\nসহায়তার পরও কোনো মা বুকের দুধ খাওয়াতে না পারলে, বা না খাওয়ানোর সিদ্ধান্ত নিলে, স্বাস্থ্যকর্মী নিরাপদ বিকল্প বুঝিয়ে দেবেন। পরিস্থিতি যা-ই হোক, প্রত্যেক মা সম্মান ও সাহায্য পাওয়ার যোগ্য।"}'::jsonb, '{}'::jsonb, 3, 0, 183, '{}'::text[], 'any', ARRAY['breastfeeding help', 'lactation support', 'community clinic', 'feeding problems']::text[], false, 'in_review'::lp_review_status, 3008),
  ('nb-exclusive-breastfeeding', 'article', 'scientific', 'family', 'important', 'guideline', '🍼', '{"en":"Only breast milk for six months: no water, honey, ghutti or formula","bn":"ছয় মাস শুধু বুকের দুধ: পানি, মধু, ঘুট্টি বা ফর্মুলা নয়"}'::jsonb, '{"en":"For the first six months, breast milk gives a baby all the food and water they need, even in hot weather. Anything else adds risk without adding benefit.","bn":"প্রথম ছয় মাস বুকের দুধেই শিশুর সব খাবার ও পানির চাহিদা মেটে, গরমের দিনেও। অন্য কিছু দিলে উপকার তো বাড়েই না, বরং ঝুঁকি বাড়ে।"}'::jsonb, '{"en":"## What exclusive breastfeeding means\n\nWHO and Bangladesh''s national guidance advise giving only breast milk from birth until six months. That means no other food or drink, not even water. Medicines, vitamin drops and oral rehydration solution (ORS) are allowed when a health worker advises them. After six months, the baby starts other foods while breastfeeding continues up to two years or beyond.\n\n## Why not water?\n\nMost of breast milk is water. A baby who is breastfed whenever they want gets enough to drink, even on the hottest days. Giving water fills the small stomach, so the baby takes less milk and gets fewer nutrients. Water, bottles and cups can also carry germs that cause diarrhoea. In hot weather, simply breastfeed more often.\n\n## Why not honey, sugar water or ghutti?\n\n- Honey can carry spores that cause infant botulism, a serious illness. No honey before the first birthday, not even a lick.\n- Sugar water, misri water and glucose water give no nutrients, fill the stomach and can carry germs.\n- Ghutti, gripe water and herbal mixtures have no proven benefit for babies, and some contain alcohol, sugar or other ingredients that are not safe.\n\n## Why not formula, cow''s or goat''s milk?\n\nFormula lacks the protection found in breast milk, and every feed of it means less demand on the breast. Making it safely needs clean water, correct measuring and sterile equipment, which is hard in many homes. Cow''s and goat''s milk are not suitable for young babies. Formula has a place when there is a true medical need, and then a health worker should guide you.\n\n## When the family says the baby needs more\n\nIt is common to hear that a baby is crying because breast milk is not enough. Crying has many causes. Look at the reliable signs instead: six or more wet nappies a day after the first week, regular stools and steady weight gain at check-ups. If you are worried, see a health worker before adding anything.\n\n## Working mothers\n\nIf you go back to work before six months, you can express milk and leave it to be fed by cup. Breastfeeding when you are home, including at night, keeps the supply going.","bn":"## শুধু বুকের দুধ মানে কী\n\nবিশ্ব স্বাস্থ্য সংস্থা ও বাংলাদেশের জাতীয় নির্দেশনা অনুযায়ী জন্ম থেকে ছয় মাস পর্যন্ত শিশুকে শুধু বুকের দুধ খাওয়াতে হবে। অর্থাৎ অন্য কোনো খাবার বা পানীয়, এমনকি পানিও নয়। স্বাস্থ্যকর্মী বললে ওষুধ, ভিটামিন ড্রপ ও খাবার স্যালাইন (ORS) দেওয়া যাবে। ছয় মাস পূর্ণ হলে বুকের দুধের পাশাপাশি অন্য খাবার শুরু হয়, আর বুকের দুধ চলে দুই বছর বা তার বেশি।\n\n## পানি কেন নয়?\n\nবুকের দুধের বেশিরভাগটাই পানি। চাহিদামতো বুকের দুধ পেলে প্রচণ্ড গরমের দিনেও শিশুর পানির অভাব হয় না। পানি দিলে ছোট্ট পেট ভরে যায়, শিশু কম দুধ খায়, পুষ্টিও কম পায়। পানি, ফিডার বা কাপ থেকে জীবাণু ঢুকে ডায়রিয়াও হতে পারে। গরমে শুধু আরও ঘন ঘন বুকের দুধ দিন।\n\n## মধু, চিনির পানি বা ঘুট্টি কেন নয়?\n\n- মধুতে এমন জীবাণুর বীজ থাকতে পারে যা শিশুর বটুলিজম (botulism) নামে মারাত্মক অসুখ ঘটায়। এক বছরের আগে মধু একদম নয়, এক ফোঁটাও নয়।\n- চিনির পানি, মিছরির পানি বা গ্লুকোজের পানিতে কোনো পুষ্টি নেই; এগুলো পেট ভরিয়ে দেয় আর জীবাণু বয়ে আনতে পারে।\n- ঘুট্টি, গ্রাইপ ওয়াটার বা ভেষজ মিশ্রণের শিশুর জন্য কোনো প্রমাণিত উপকার নেই, আর কোনোটাতে অ্যালকোহল, চিনি বা অনিরাপদ উপাদান থাকে।\n\n## ফর্মুলা, গরুর বা ছাগলের দুধ কেন নয়?\n\nফর্মুলায় বুকের দুধের রোগ-প্রতিরোধী গুণ নেই, আর প্রতিবার ফর্মুলা দেওয়া মানে স্তনের কাছে চাহিদা কমে যাওয়া। নিরাপদে বানাতে পরিষ্কার পানি, সঠিক মাপ আর জীবাণুমুক্ত সরঞ্জাম লাগে, যা অনেক বাড়িতেই কঠিন। গরু বা ছাগলের দুধ ছোট শিশুর উপযোগী নয়। সত্যিকারের চিকিৎসার প্রয়োজন হলে ফর্মুলার জায়গা আছে, তখন স্বাস্থ্যকর্মীর পরামর্শে দিতে হবে।\n\n## পরিবার যখন বলে শিশুর পেট ভরছে না\n\n“বুকের দুধে হচ্ছে না, তাই কাঁদছে”, এমন কথা প্রায়ই শোনা যায়। কিন্তু কান্নার অনেক কারণ থাকে। বরং নির্ভরযোগ্য লক্ষণগুলো দেখুন: প্রথম সপ্তাহের পর দিনে ৬ বা তার বেশি ভেজা ন্যাপি, নিয়মিত পায়খানা, আর চেকআপে ঠিকমতো ওজন বাড়া। চিন্তা হলে কিছু যোগ করার আগে স্বাস্থ্যকর্মী দেখান।\n\n## কর্মজীবী মা\n\nছয় মাসের আগে কাজে ফিরতে হলে দুধ বের করে রেখে যেতে পারেন, যা কাপে খাওয়ানো হবে। বাড়িতে থাকার সময়, রাতেও, সরাসরি খাওয়ালে দুধ তৈরি চালু থাকে।"}'::jsonb, '{"avoid":{"en":["Water, even in hot weather","Honey before one year","Sugar water, misri water or glucose water","Ghutti, gripe water or herbal mixtures","Formula, cow''s or goat''s milk without a medical reason","Feeding bottles and dummies in the early weeks"],"bn":["পানি, গরমের দিনেও","এক বছরের আগে মধু","চিনির পানি, মিছরির পানি বা গ্লুকোজের পানি","ঘুট্টি, গ্রাইপ ওয়াটার বা ভেষজ মিশ্রণ","চিকিৎসার কারণ ছাড়া ফর্মুলা, গরু বা ছাগলের দুধ","প্রথম সপ্তাহগুলোতে ফিডার ও চুষনি"]}}'::jsonb, 4, 0, 183, '{}'::text[], 'any', ARRAY['exclusive breastfeeding', 'six months', 'no water', 'honey', 'ghutti', 'formula']::text[], false, 'in_review'::lp_review_status, 3009),
  ('nb-first-24-hours', 'article', 'scientific', 'shared', 'important', 'guideline', '🐣', '{"en":"Your baby''s first 24 hours","bn":"শিশুর প্রথম ২৪ ঘণ্টা"}'::jsonb, '{"en":"Warmth, breast milk, a clean cord and a careful check: these simple things in the first day protect your baby the most.","bn":"উষ্ণতা, বুকের দুধ, পরিষ্কার নাভি আর যত্ন করে একবার দেখে নেওয়া: প্রথম দিনের এই সহজ কাজগুলোই শিশুকে সবচেয়ে বেশি সুরক্ষা দেয়।"}'::jsonb, '{"en":"## Right after birth\n\nThe baby is dried at once with a clean, warm cloth, which also helps them start breathing. Then, if all is well, the baby goes skin-to-skin on the mother''s chest, covered with a cloth and a cap. The first breastfeed usually happens within the first hour.\n\n## Care the health worker gives\n\nIn a facility, or with a skilled birth attendant at home, the baby is usually:\n\n- weighed and examined from head to toe;\n- given a vitamin K injection, which prevents dangerous bleeding;\n- given chlorhexidine on the cord stump where this is the practice, as it is in Bangladesh;\n- given BCG and checked for any problems before going home.\n\nAsk which of these your baby has had, and keep any card or paper you are given.\n\n## Delay the first bath\n\nWHO advises waiting at least 24 hours before the first bath. The white, creamy coating on the skin (vernix) protects it, and a newborn loses heat quickly when wet. Wipe away blood or meconium gently, and leave the rest.\n\n## Stay a day, or have an early visit\n\nAfter a normal birth in a facility, WHO advises that mother and baby stay at least 24 hours. After a home birth, a health worker should see you both within the first 24 hours. This first check finds problems with breathing, feeding, warmth, bleeding or infection early.\n\n## What is normal on the first day\n\n- The baby is sleepy for long stretches after the first alert hour.\n- Small, frequent feeds of colostrum.\n- At least one wet nappy and a dark, sticky stool (meconium).\n- Hands and feet may look a little blue for a while; the body and lips should be pink.\n- A slightly odd head shape or puffy eyelids from the birth, which settle within days.\n\n## Know the danger signs\n\nBefore going home, make sure you and your family know the newborn danger signs: not feeding, fits, fast or difficult breathing, fever or feeling cold, very little movement, and yellow skin on the first day. Any of these means going to hospital at once, day or night.","bn":"## জন্মের পরপরই\n\nজন্মের সাথে সাথে পরিষ্কার, গরম কাপড় দিয়ে শিশুকে মুছে শুকানো হয়, যা তাকে শ্বাস নিতেও সাহায্য করে। তারপর সব ঠিক থাকলে শিশুকে মায়ের খালি বুকে রাখা হয়, ওপরে কাপড় আর মাথায় টুপি দিয়ে। সাধারণত প্রথম ঘণ্টার মধ্যেই প্রথমবার বুকের দুধ খাওয়ানো হয়।\n\n## স্বাস্থ্যকর্মী যে যত্নগুলো দেন\n\nহাসপাতাল-ক্লিনিকে, বা বাড়িতে দক্ষ ধাত্রীর হাতে প্রসব হলে, সাধারণত শিশুকে:\n\n- ওজন নেওয়া হয় আর মাথা থেকে পা পর্যন্ত পরীক্ষা করা হয়;\n- ভিটামিন কে ইনজেকশন দেওয়া হয়, যা বিপজ্জনক রক্তক্ষরণ ঠেকায়;\n- যেখানে নিয়ম আছে, যেমন বাংলাদেশে, নাভিতে ক্লোরহেক্সিডিন লাগানো হয়;\n- বিসিজি টিকা দেওয়া হয়, আর বাড়ি যাওয়ার আগে কোনো সমস্যা আছে কিনা দেখা হয়।\n\nএর কোনগুলো আপনার শিশু পেয়েছে জিজ্ঞেস করে নিন, আর যে কার্ড বা কাগজ দেয় তা যত্ন করে রাখুন।\n\n## প্রথম গোসল দেরিতে\n\nবিশ্ব স্বাস্থ্য সংস্থা অন্তত ২৪ ঘণ্টা পর প্রথম গোসল করাতে বলে। ত্বকের ওপরের সাদা, ক্রিমের মতো আবরণ (vernix) ত্বককে সুরক্ষা দেয়, আর ভেজা অবস্থায় নবজাতকের শরীর দ্রুত ঠান্ডা হয়ে যায়। রক্ত বা কালো পায়খানা আলতো করে মুছে দিন, বাকিটা থাকতে দিন।\n\n## অন্তত এক দিন থাকুন, বা তাড়াতাড়ি দেখিয়ে নিন\n\nহাসপাতাল-ক্লিনিকে স্বাভাবিক প্রসবের পর মা ও শিশুর অন্তত ২৪ ঘণ্টা থাকার পরামর্শ দেয় বিশ্ব স্বাস্থ্য সংস্থা। বাড়িতে প্রসব হলে প্রথম ২৪ ঘণ্টার মধ্যেই একজন স্বাস্থ্যকর্মী যেন দুজনকে দেখেন। এই প্রথম দেখাতেই শ্বাস, খাওয়া, উষ্ণতা, রক্তপাত বা সংক্রমণের সমস্যা আগেভাগে ধরা পড়ে।\n\n## প্রথম দিনে যা স্বাভাবিক\n\n- প্রথম সজাগ ঘণ্টার পর শিশু অনেকক্ষণ ধরে ঘুমায়।\n- অল্প অল্প করে ঘন ঘন শালদুধ খায়।\n- অন্তত একবার প্রস্রাব, আর কালচে আঠালো পায়খানা (meconium)।\n- হাত-পা কিছুক্ষণ একটু নীলচে দেখাতে পারে; তবে শরীর ও ঠোঁট গোলাপি থাকবে।\n- প্রসবের চাপে মাথার আকার একটু অন্যরকম বা চোখের পাতা ফোলা লাগতে পারে, কয়েক দিনে ঠিক হয়ে যায়।\n\n## বিপদচিহ্নগুলো জেনে রাখুন\n\nবাড়ি যাওয়ার আগে আপনি ও পরিবারের সবাই নবজাতকের বিপদচিহ্নগুলো জেনে নিন: খেতে না পারা, খিঁচুনি, দ্রুত বা কষ্ট করে শ্বাস, জ্বর বা গা ঠান্ডা, খুব কম নড়াচড়া, আর প্রথম দিনেই ত্বক হলুদ। এর যেকোনোটি দেখলে দিন-রাত যখনই হোক, সাথে সাথে হাসপাতালে যান।"}'::jsonb, '{"steps":{"en":["Keep the baby skin-to-skin and start breastfeeding in the first hour","Ask whether the baby has had vitamin K, cord care and BCG","Wait at least 24 hours before the first bath","Keep the baby warm, with a cap, close to the mother","Learn the newborn danger signs before going home"],"bn":["শিশুকে খালি বুকে রাখুন, প্রথম ঘণ্টাতেই বুকের দুধ শুরু করুন","শিশু ভিটামিন কে, নাভির যত্ন ও বিসিজি পেয়েছে কিনা জিজ্ঞেস করুন","প্রথম গোসলের আগে অন্তত ২৪ ঘণ্টা অপেক্ষা করুন","শিশুকে টুপি পরিয়ে উষ্ণ রাখুন, মায়ের কাছে রাখুন","বাড়ি যাওয়ার আগে নবজাতকের বিপদচিহ্নগুলো জেনে নিন"]},"avoid":{"en":["Bathing the baby in the first 24 hours","Putting anything on the cord or in the baby''s mouth, eyes, nose or ears","Giving anything other than breast milk"],"bn":["প্রথম ২৪ ঘণ্টায় গোসল করানো","নাভিতে, বা শিশুর মুখ, চোখ, নাক ও কানে কিছু দেওয়া","বুকের দুধ ছাড়া অন্য কিছু খাওয়ানো"]}}'::jsonb, 4, 0, 3, '{}'::text[], 'any', ARRAY['first day', 'newborn', 'vitamin k', 'first bath', 'danger signs', 'skin to skin']::text[], false, 'in_review'::lp_review_status, 3010),
  ('nb-keeping-warm-kangaroo', 'article', 'scientific', 'shared', 'important', 'guideline', '🦘', '{"en":"Keeping your baby warm, and kangaroo care for small babies","bn":"শিশুকে উষ্ণ রাখা, আর ছোট শিশুর জন্য ক্যাঙ্গারু পদ্ধতি"}'::jsonb, '{"en":"Newborns lose heat fast, and small babies even faster. Skin-to-skin contact is the simplest way to keep a baby warm, and for small babies it can save lives.","bn":"নবজাতকের শরীর দ্রুত ঠান্ডা হয়ে যায়, আর ছোট শিশুর আরও দ্রুত। ত্বকের সাথে ত্বক লাগিয়ে রাখাই শিশুকে উষ্ণ রাখার সবচেয়ে সহজ উপায়, আর ছোট শিশুর জন্য তা জীবন বাঁচাতে পারে।"}'::jsonb, '{"en":"## Why warmth matters\n\nA newborn cannot keep warm on their own as well as an older child. A baby who gets cold uses up energy, feeds poorly and is more likely to become ill. Being too hot is also harmful. The aim is a baby who is comfortably warm.\n\n## Everyday warmth\n\n- Keep the room warm and free of draughts, especially in winter.\n- Dress the baby in one more layer than an adult would need, with a cap in the first days and in cool weather.\n- Keep the baby close to the mother, and bathe quickly in a warm room.\n- Change wet clothes and nappies promptly.\n\n## How to check\n\nFeel the baby''s tummy or back, not the hands and feet, which are often cool. A warm tummy is good. A cold tummy or back means the baby needs warming now: skin-to-skin is the quickest way. A hot, sweaty baby with a flushed face needs a layer removed. If you have a thermometer, normal is about 36.5 to 37.5 °C.\n\n## Kangaroo mother care\n\nKangaroo mother care means holding the baby, in just a nappy and cap, upright on the bare chest between the breasts, skin to skin, with a cloth or wrap tied over both to hold the baby secure. The baby''s head is turned to one side, slightly tilted up so the airway stays open.\n\nWHO advises kangaroo mother care for babies born weighing less than 2 kg, starting as soon as possible after birth, in hospital and at home, for as many hours of the day and night as possible. It helps small babies stay warm, breathe more steadily, breastfeed better, grow, and survive. Any baby benefits from skin-to-skin time.\n\n## The whole family can do it\n\nThe mother usually does most of the hours, but the father, a grandmother or another trusted adult can take turns so she can rest, wash and eat. The person should be clean, not smoking, and awake or reclined safely so the baby cannot slip.\n\n## How long\n\nSmall babies usually continue until they reach about 2.5 kg, or start to wriggle and show they want to come out. Follow your health worker''s advice.","bn":"## উষ্ণতা কেন জরুরি\n\nবড় শিশুর মতো নবজাতক নিজের শরীর গরম রাখতে পারে না। ঠান্ডা লাগলে শিশুর শক্তি খরচ হয়, ঠিকমতো খেতে পারে না, আর অসুস্থ হওয়ার ঝুঁকি বাড়ে। আবার বেশি গরমও ক্ষতিকর। লক্ষ্য হলো শিশু যেন আরামদায়কভাবে উষ্ণ থাকে।\n\n## প্রতিদিনের উষ্ণতা\n\n- ঘর গরম রাখুন, বাতাস ঢোকা বন্ধ করুন, বিশেষ করে শীতে।\n- একজন বড় মানুষ যতটা কাপড় পরেন, শিশুকে তার চেয়ে এক পরত বেশি পরান। প্রথম কয়েক দিন আর ঠান্ডার দিনে মাথায় টুপি দিন।\n- শিশুকে মায়ের কাছাকাছি রাখুন, আর গরম ঘরে তাড়াতাড়ি গোসল সারুন।\n- ভেজা কাপড় ও ন্যাপি সাথে সাথে বদলে দিন।\n\n## কীভাবে বুঝবেন\n\nহাত-পা নয়, শিশুর পেট বা পিঠে হাত দিয়ে দেখুন; হাত-পা প্রায়ই একটু ঠান্ডা থাকে। পেট উষ্ণ থাকলে ঠিক আছে। পেট বা পিঠ ঠান্ডা হলে এখনই গরম করা দরকার, আর তার সবচেয়ে দ্রুত উপায় খালি বুকে জড়িয়ে রাখা। শিশু গরম হয়ে ঘামলে, মুখ লাল হলে এক পরত কাপড় খুলে দিন। থার্মোমিটার থাকলে স্বাভাবিক তাপমাত্রা মোটামুটি ৩৬.৫ থেকে ৩৭.৫ °সে।\n\n## ক্যাঙ্গারু মাদার কেয়ার\n\nক্যাঙ্গারু মাদার কেয়ার মানে শিশুকে শুধু ন্যাপি আর টুপি পরিয়ে মায়ের খালি বুকে, দুই স্তনের মাঝখানে খাড়া করে, ত্বকের সাথে ত্বক লাগিয়ে রাখা। ওপর দিয়ে একটা কাপড় বা ওড়না বেঁধে দুজনকে জড়িয়ে নিতে হয়, যাতে শিশু নিরাপদে থাকে। শিশুর মাথা একপাশে ঘোরানো আর সামান্য ওপরের দিকে থাকবে, যাতে শ্বাসনালি খোলা থাকে।\n\nবিশ্ব স্বাস্থ্য সংস্থা জন্মের সময় ২ কেজির কম ওজনের শিশুদের জন্য এই পদ্ধতির পরামর্শ দেয়: জন্মের পর যত তাড়াতাড়ি সম্ভব শুরু করে, হাসপাতালে ও বাড়িতে, দিন-রাত যত বেশি ঘণ্টা সম্ভব। এতে ছোট শিশু উষ্ণ থাকে, শ্বাস স্থির হয়, বুকের দুধ ভালো খায়, বাড়ে, আর বেঁচে থাকার সম্ভাবনা বাড়ে। যেকোনো শিশুই ত্বকের ছোঁয়া থেকে উপকার পায়।\n\n## পুরো পরিবার করতে পারে\n\nবেশিরভাগ সময় মা-ই রাখেন, কিন্তু বাবা, নানি-দাদি বা অন্য বিশ্বস্ত বড় কেউ পালা করে রাখলে মা বিশ্রাম নিতে, গোসল করতে ও খেতে পারেন। যিনি রাখবেন তিনি পরিষ্কার থাকবেন, ধূমপান করবেন না, আর জেগে থাকবেন বা এমনভাবে হেলান দিয়ে থাকবেন যাতে শিশু পিছলে না পড়ে।\n\n## কতদিন\n\nছোট শিশুদের সাধারণত ওজন প্রায় ২.৫ কেজি হওয়া পর্যন্ত, বা যতদিন না শিশু মোচড়ামুচড়ি করে বেরিয়ে আসতে চায়, ততদিন চালিয়ে যাওয়া হয়। স্বাস্থ্যকর্মীর পরামর্শ মেনে চলুন।"}'::jsonb, '{"steps":{"en":["Undress the baby to a nappy and cap","Place the baby upright on your bare chest, between the breasts, head turned to one side","Tie a cloth or wrap over both of you, firm but not tight","Cover both of you with a shawl or blanket if the room is cool","Breastfeed in this position whenever the baby shows hunger"],"bn":["শিশুকে শুধু ন্যাপি আর টুপি পরিয়ে রাখুন","আপনার খালি বুকে, দুই স্তনের মাঝে খাড়া করে রাখুন, মাথা একপাশে ঘোরানো","দুজনের ওপর একটা কাপড় বা ওড়না বাঁধুন, শক্ত করে কিন্তু টাইট নয়","ঘর ঠান্ডা হলে ওপরে চাদর বা কম্বল দিন","শিশু খিদে দেখালে এই অবস্থাতেই বুকের দুধ খাওয়ান"]},"seek_help":{"en":["The baby''s tummy or back stays cold even with skin-to-skin","Temperature below 35.5 °C or 37.5 °C or above","A small baby who is not feeding well or is very sleepy"],"bn":["খালি বুকে রাখার পরও শিশুর পেট বা পিঠ ঠান্ডা","তাপমাত্রা ৩৫.৫ °সে-এর কম, বা ৩৭.৫ °সে বা তার বেশি","ছোট শিশু ঠিকমতো খাচ্ছে না বা খুব ঘুমকাতুরে"]}}'::jsonb, 4, 0, 91, '{}'::text[], 'any', ARRAY['warmth', 'hypothermia', 'kangaroo mother care', 'skin to skin', 'low birth weight', 'preterm']::text[], false, 'in_review'::lp_review_status, 3011),
  ('nb-cord-care', 'article', 'scientific', 'shared', 'important', 'guideline', '🩹', '{"en":"Cord care: keep it clean, dry and uncovered","bn":"নাভির যত্ন: পরিষ্কার, শুকনো আর খোলা রাখুন"}'::jsonb, '{"en":"The cord stump dries and falls off on its own, usually within one to two weeks. Put nothing on it except what your health worker gives.","bn":"নাভির বাকি অংশ নিজে নিজেই শুকিয়ে পড়ে যায়, সাধারণত এক থেকে দুই সপ্তাহে। স্বাস্থ্যকর্মী যা দেন তা ছাড়া নাভিতে আর কিছুই লাগাবেন না।"}'::jsonb, '{"en":"## What to expect\n\nAfter birth the cord is clamped and cut, leaving a short stump. Over the next days it dries, shrinks, turns dark brown or black and falls off, usually within one to two weeks. A few drops of blood or a little stickiness when it separates are normal.\n\n## Simple, safe care\n\n- Wash your hands with soap and water before touching the cord area.\n- Keep the stump clean and dry, open to the air.\n- Fold the nappy or cloth below the stump so it is not covered or rubbed.\n- If urine or stool gets on it, wash gently with clean water and pat dry with a clean cloth.\n- Let it fall off by itself. Do not pull it, even if it is hanging by a thread.\n\n## Chlorhexidine\n\nIn Bangladesh and some other countries where cord infections have been common, health workers apply chlorhexidine to the cord after birth, and may give it to use at home for a few days. Use it exactly as the health worker explains. Apart from this, nothing needs to go on the cord.\n\n## What not to put on the cord\n\nMustard oil, ghee, ash, turmeric, cow dung, powder, toothpaste, herbal pastes and similar things have been used on cords for generations. They do not help it heal and some carry germs, including the germs that cause tetanus. Tight belly bands or bandages keep the stump damp and slow healing.\n\n## After the cord falls off\n\nThe navel may look a little moist for a few days and then heal. A small, soft, moist pink lump that does not dry up (a granuloma) should be shown to a health worker; it is easy to treat. A navel that bulges out when the baby cries is usually an umbilical hernia, which is common and often closes by itself; show it at the next check-up.\n\n## Signs of infection\n\nRedness spreading onto the skin around the navel, swelling, pus, a bad smell, or bleeding that does not stop are signs of infection. If the baby also has a fever, feels cold, is not feeding or is very sleepy, go to hospital today.","bn":"## কী আশা করবেন\n\nজন্মের পর নাড়ি বেঁধে কাটা হয়, আর ছোট একটা অংশ থেকে যায়। পরের দিনগুলোতে সেটা শুকিয়ে কুঁচকে কালচে-বাদামি বা কালো হয়ে যায় এবং পড়ে যায়, সাধারণত এক থেকে দুই সপ্তাহের মধ্যে। খসে পড়ার সময় কয়েক ফোঁটা রক্ত বা একটু আঠালো ভাব স্বাভাবিক।\n\n## সহজ ও নিরাপদ যত্ন\n\n- নাভির কাছে হাত দেওয়ার আগে সাবান-পানি দিয়ে হাত ধুয়ে নিন।\n- নাভি পরিষ্কার ও শুকনো রাখুন, বাতাসে খোলা রাখুন।\n- ন্যাপি বা কাঁথা নাভির নিচে ভাঁজ করে পরান, যাতে ঢেকে না যায় বা ঘষা না লাগে।\n- প্রস্রাব-পায়খানা লেগে গেলে পরিষ্কার পানি দিয়ে আলতো করে ধুয়ে পরিষ্কার কাপড়ে চেপে শুকিয়ে নিন।\n- নিজে থেকে পড়ে যেতে দিন। সুতোর মতো ঝুলে থাকলেও টেনে ছেঁড়াবেন না।\n\n## ক্লোরহেক্সিডিন\n\nবাংলাদেশসহ যেসব দেশে নাভির সংক্রমণ বেশি দেখা যেত, সেখানে জন্মের পর স্বাস্থ্যকর্মীরা নাভিতে ক্লোরহেক্সিডিন লাগান, আর কয়েক দিন বাড়িতে লাগানোর জন্যও দিতে পারেন। স্বাস্থ্যকর্মী যেভাবে বুঝিয়ে দেন, ঠিক সেভাবেই ব্যবহার করুন। এটা ছাড়া নাভিতে আর কিছু লাগানোর দরকার নেই।\n\n## নাভিতে যা লাগাবেন না\n\nসরিষার তেল, ঘি, ছাই, হলুদ, গোবর, পাউডার, টুথপেস্ট, লতাপাতার বাটা, এমন অনেক কিছু প্রজন্ম ধরে নাভিতে লাগানো হয়ে আসছে। এগুলো নাভি সারাতে সাহায্য করে না, বরং কোনোটায় জীবাণু থাকে, ধনুষ্টংকারের জীবাণুও। পেটে শক্ত করে কাপড় বা ব্যান্ডেজ বাঁধলে নাভি ভেজা থাকে, সারতে দেরি হয়।\n\n## নাভি পড়ে যাওয়ার পর\n\nকয়েক দিন নাভি একটু ভেজা ভেজা লাগতে পারে, তারপর শুকিয়ে যায়। ছোট, নরম, ভেজা গোলাপি একটা মাংসপিণ্ড যদি না শুকায় (granuloma), স্বাস্থ্যকর্মীকে দেখান; এর চিকিৎসা সহজ। কাঁদলে নাভি ফুলে বেরিয়ে আসা সাধারণত নাভির হার্নিয়া, যা খুবই সাধারণ আর প্রায়ই নিজে নিজে বন্ধ হয়ে যায়; পরের চেকআপে দেখিয়ে নিন।\n\n## সংক্রমণের লক্ষণ\n\nনাভির চারপাশের ত্বকে লালচে ভাব ছড়িয়ে পড়া, ফোলা, পুঁজ, দুর্গন্ধ, বা রক্তপাত না থামা সংক্রমণের লক্ষণ। সাথে শিশুর জ্বর থাকলে, গা ঠান্ডা হলে, না খেলে বা খুব ঘুমকাতুরে হলে আজই হাসপাতালে যান।"}'::jsonb, '{"avoid":{"en":["Oil, ghee, ash, turmeric, cow dung, powder or pastes on the cord","Covering the cord with a nappy, bandage or tight belly band","Pulling the stump off"],"bn":["নাভিতে তেল, ঘি, ছাই, হলুদ, গোবর, পাউডার বা কোনো বাটা লাগানো","ন্যাপি, ব্যান্ডেজ বা শক্ত কাপড় দিয়ে নাভি ঢেকে রাখা","নাভি টেনে ছিঁড়ে ফেলা"]},"seek_help":{"en":["Redness spreading onto the skin around the navel","Pus, a bad smell or swelling","Bleeding that does not stop with gentle pressure","Fever, a cold body, poor feeding or unusual sleepiness with any cord change"],"bn":["নাভির চারপাশের ত্বকে লালচে ভাব ছড়ানো","পুঁজ, দুর্গন্ধ বা ফোলা","আলতো চাপ দিলেও রক্তপাত না থামা","নাভির পরিবর্তনের সাথে জ্বর, গা ঠান্ডা, ঠিকমতো না খাওয়া বা অস্বাভাবিক ঘুমঘুম ভাব"]}}'::jsonb, 3, 0, 21, '{}'::text[], 'any', ARRAY['umbilical cord', 'cord stump', 'chlorhexidine', 'navel', 'infection']::text[], false, 'in_review'::lp_review_status, 3012),
  ('nb-bathing-skin', 'article', 'scientific', 'shared', 'routine', 'guideline', '🛁', '{"en":"Bathing your baby and caring for newborn skin","bn":"শিশুর গোসল ও নবজাতকের ত্বকের যত্ন"}'::jsonb, '{"en":"Newborn skin is thin and easily dried. Short, warm baths with plain water, and knowing which spots and rashes are normal, are all most babies need.","bn":"নবজাতকের ত্বক পাতলা, সহজেই শুকিয়ে যায়। অল্প সময়ের কুসুম গরম পানির গোসল, আর কোন দাগ বা র‍্যাশ স্বাভাবিক তা জানা, বেশিরভাগ শিশুর জন্য এটুকুই যথেষ্ট।"}'::jsonb, '{"en":"## When and how often\n\nWait at least 24 hours after birth for the first bath. After that, a full bath two or three times a week is enough for a young baby; on other days, wipe the face, neck folds, hands and nappy area with a soft cloth and warm water. In hot weather you may bathe more often if the baby is sweaty. Many families sponge-bathe until the cord falls off, which keeps it dry.\n\n## A safe bath\n\n1. Choose a warm room with no draughts, and get everything ready first: a towel, clean clothes, a nappy.\n2. Use warm, not hot, water. Test it with your elbow; it should feel comfortably warm.\n3. Support the head and neck at all times. Keep the bath short, about five minutes.\n4. Use plain water, or a little mild, unscented baby soap on the body.\n5. Wash the face first with clean water, then the body, then the nappy area last.\n6. Dry quickly and well, especially in the neck, armpit and groin folds, then dress the baby and put on a cap if it is cool.\n\nNever leave a baby alone in water, even for a moment. A baby can drown in a few centimetres of water.\n\n## Common skin changes that are usually harmless\n\n- Peeling or dry skin in the first weeks.\n- Tiny white spots on the nose (milia).\n- A blotchy red rash with small pale bumps in the first days.\n- Baby acne on the cheeks around a few weeks of age.\n- Heat rash (ghamachi): tiny red bumps where the baby is too warm; dress lighter.\n- Blue-grey patches on the back or bottom, common in South Asian babies; they fade over the years.\n- Yellowish, scaly patches on the scalp (cradle cap); wash gently, and a little oil can soften the scales.\n\n## Keep it simple\n\nAvoid perfumed soaps, lotions and talcum powder, which can irritate the skin or be breathed in. Do not put kajal or anything else in the eyes. Trim nails with baby clippers or file them when the baby is asleep.\n\n## When to show a health worker\n\nBlisters, many pus-filled spots, skin that looks red and swollen or very yellow, a rash with fever, or a baby who is unwell with a rash.","bn":"## কখন ও কতবার\n\nজন্মের পর প্রথম গোসলের আগে অন্তত ২৪ ঘণ্টা অপেক্ষা করুন। তারপর ছোট শিশুর জন্য সপ্তাহে দুই-তিনবার পুরো গোসলই যথেষ্ট; অন্য দিনগুলোতে নরম কাপড় কুসুম গরম পানিতে ভিজিয়ে মুখ, গলার ভাঁজ, হাত আর ন্যাপির জায়গা মুছে দিন। গরমে শিশু ঘামলে বেশি বার গোসল করাতে পারেন। অনেক পরিবার নাভি পড়া পর্যন্ত শুধু গা মুছিয়ে দেয়, এতে নাভি শুকনো থাকে।\n\n## নিরাপদ গোসল\n\n1. বাতাস ঢোকে না এমন গরম ঘর বেছে নিন, আর আগেই সব গুছিয়ে রাখুন: তোয়ালে, পরিষ্কার জামা, ন্যাপি।\n2. পানি কুসুম গরম হবে, গরম নয়। কনুই ডুবিয়ে দেখুন; আরামদায়ক উষ্ণ লাগা উচিত।\n3. সবসময় মাথা ও ঘাড়ে হাত রেখে ধরে রাখুন। গোসল অল্প সময়ে, মোটামুটি পাঁচ মিনিটে সারুন।\n4. শুধু পানি, বা শরীরে সামান্য হালকা, সুগন্ধিহীন বেবি সাবান ব্যবহার করুন।\n5. প্রথমে পরিষ্কার পানিতে মুখ, তারপর শরীর, সবশেষে ন্যাপির জায়গা ধোবেন।\n6. তাড়াতাড়ি ভালো করে মুছে নিন, বিশেষ করে গলা, বগল ও কুঁচকির ভাঁজ; তারপর জামা পরান, ঠান্ডা হলে টুপিও।\n\nএক মুহূর্তের জন্যও শিশুকে পানিতে একা রাখবেন না। কয়েক সেন্টিমিটার পানিতেও শিশু ডুবে যেতে পারে।\n\n## ত্বকের সাধারণ কিছু পরিবর্তন, যা সাধারণত ক্ষতিকর নয়\n\n- প্রথম সপ্তাহগুলোতে চামড়া ওঠা বা শুকনো ত্বক।\n- নাকের ওপর ছোট ছোট সাদা দানা (milia)।\n- প্রথম কয়েক দিনে ছোপ ছোপ লাল র‍্যাশ, মাঝে ছোট ফ্যাকাশে দানা।\n- কয়েক সপ্তাহ বয়সে গালে ব্রণের মতো দানা।\n- ঘামাচি: বেশি গরম লাগলে ছোট ছোট লাল দানা; হালকা কাপড় পরান।\n- পিঠ বা নিতম্বে নীলচে-ধূসর ছোপ, দক্ষিণ এশিয়ার শিশুদের মধ্যে খুব সাধারণ; বছর গড়ালে মিলিয়ে যায়।\n- মাথার তালুতে হলদেটে খুশকির মতো আঁশ (cradle cap); আলতো করে ধুয়ে দিন, সামান্য তেল দিলে আঁশ নরম হয়।\n\n## সহজ রাখুন\n\nসুগন্ধি সাবান, লোশন আর ট্যালকম পাউডার এড়িয়ে চলুন; এগুলো ত্বকে জ্বালা করতে পারে বা নিঃশ্বাসের সাথে ভেতরে যেতে পারে। চোখে কাজল বা অন্য কিছু দেবেন না। শিশু ঘুমালে বেবি নেইল কাটার দিয়ে নখ কাটুন বা ঘষে ছোট করুন।\n\n## কখন স্বাস্থ্যকর্মীকে দেখাবেন\n\nফোসকা, অনেকগুলো পুঁজভরা দানা, ত্বক লাল হয়ে ফুলে যাওয়া বা খুব হলুদ, জ্বরের সাথে র‍্যাশ, বা র‍্যাশসহ শিশু অসুস্থ মনে হলে।"}'::jsonb, '{"avoid":{"en":["Leaving the baby alone in or near water","Hot water, long baths or bathing in a cold room","Talcum powder, perfumed soap or lotions","Kajal or anything in the eyes"],"bn":["পানিতে বা পানির কাছে শিশুকে একা রাখা","গরম পানি, দীর্ঘ গোসল বা ঠান্ডা ঘরে গোসল","ট্যালকম পাউডার, সুগন্ধি সাবান বা লোশন","চোখে কাজল বা অন্য কিছু"]}}'::jsonb, 4, 0, 183, '{}'::text[], 'any', ARRAY['bathing', 'skin', 'rash', 'baby acne', 'heat rash', 'mongolian spot', 'cradle cap']::text[], false, 'in_review'::lp_review_status, 3013),
  ('nb-safe-sleep', 'article', 'scientific', 'shared', 'important', 'guideline', '😴', '{"en":"Newborn sleep and safe sleep","bn":"নবজাতকের ঘুম ও নিরাপদ ঘুম"}'::jsonb, '{"en":"Newborns sleep a lot, in short stretches. Back to sleep, on a firm flat surface, with nothing soft near the face, in the parents'' room: these protect your baby.","bn":"নবজাতক অনেক ঘুমায়, তবে অল্প অল্প সময় ধরে। চিত করে শোয়ানো, শক্ত সমান বিছানা, মুখের কাছে নরম কিছু নয়, আর মা-বাবার ঘরেই ঘুম: এগুলোই শিশুকে নিরাপদ রাখে।"}'::jsonb, '{"en":"## How newborns sleep\n\nIn the first months most babies sleep for much of the day and night, but only for an hour or a few hours at a time. They wake to feed, including at night, and that is healthy. Babies do not know day from night at first; this settles over the first two or three months. Every baby is different, so there is no one right amount.\n\n## The safe sleep basics\n\nSudden unexplained death of a baby during sleep is rare, but these steps lower the risk:\n\n- **On the back** for every sleep, day and night. Once a baby can roll both ways on their own, you do not need to turn them back.\n- **Firm, flat surface** such as a cot, or a firm mattress or mat. Not a soft mattress, sofa, armchair, or a sloping surface.\n- **Nothing soft near the face**: no pillows, bolsters, soft quilts, toys or bumpers. This includes the mustard-seed pillow used in many homes to shape the head; it is not needed and is not safe for sleep.\n- **Same room, own sleep space**: keep the baby''s sleep place in the parents'' room, close to the bed, for at least the first six months.\n- **Smoke-free**: no smoking in the home or near the baby, by anyone.\n- **Not too hot**: light clothing, the head and face uncovered during sleep, and no heavy wrapping.\n- **Breastfeeding** also lowers the risk.\n\n## If the baby sleeps in your bed\n\nIn many Bangladeshi homes babies sleep in the parents'' bed. Safety experts advise a separate sleep surface beside the bed instead. If your baby does end up in your bed, make it as safe as you can: a firm surface, the baby on their back away from pillows and quilts, never between two adults or next to other children, and never with an adult who smokes, has taken medicine or anything that causes drowsiness, or is extremely exhausted. Never sleep with a baby on a sofa or chair.\n\n## Mosquito nets\n\nIn Bangladesh a mosquito net protects against dengue and other illnesses. Hang it so it is tucked in well and does not lie on the baby''s face.\n\n## Swaddling\n\nIf you wrap your baby, keep it loose around the hips and not over the face or head, always place them on the back, and stop wrapping once they start trying to roll.","bn":"## নবজাতক কীভাবে ঘুমায়\n\nপ্রথম কয়েক মাস বেশিরভাগ শিশু দিন-রাতের বড় অংশ ঘুমিয়ে কাটায়, তবে একবারে এক বা কয়েক ঘণ্টা। খাওয়ার জন্য জাগে, রাতেও, আর এটাই স্বাস্থ্যকর। শুরুতে শিশু দিন-রাতের পার্থক্য বোঝে না; প্রথম দুই-তিন মাসে ধীরে ধীরে তা ঠিক হয়। প্রত্যেক শিশু আলাদা, তাই ঘুমের কোনো একটাই সঠিক পরিমাণ নেই।\n\n## নিরাপদ ঘুমের মূল নিয়ম\n\nঘুমের মধ্যে শিশুর হঠাৎ অব্যাখ্যাত মৃত্যু বিরল, তবে এই কাজগুলো ঝুঁকি আরও কমায়:\n\n- **চিত করে শোয়ান**, প্রতিবার, দিনে-রাতে। শিশু নিজে থেকে দুই দিকে গড়াতে শিখলে তাকে আবার চিত করে দেওয়ার দরকার নেই।\n- **শক্ত, সমান বিছানা**, যেমন দোলনা বা খাট, কিংবা শক্ত তোশক বা মাদুর। নরম গদি, সোফা, চেয়ার বা ঢালু জায়গা নয়।\n- **মুখের কাছে নরম কিছু নয়**: বালিশ, কোলবালিশ, নরম লেপ-কাঁথার স্তূপ, খেলনা কিছুই নয়। মাথা গোল করার জন্য অনেক বাড়িতে যে সরিষার বালিশ দেওয়া হয়, সেটাও দরকার নেই, আর ঘুমের জন্য নিরাপদও নয়।\n- **একই ঘরে, আলাদা জায়গায়**: অন্তত প্রথম ছয় মাস শিশুর ঘুমের জায়গা মা-বাবার ঘরে, বিছানার কাছাকাছি রাখুন।\n- **ধোঁয়ামুক্ত**: বাড়িতে বা শিশুর কাছে কেউ ধূমপান করবেন না।\n- **বেশি গরম নয়**: হালকা কাপড়, ঘুমের সময় মাথা ও মুখ খোলা, ভারী করে মোড়ানো নয়।\n- **বুকের দুধ খাওয়ানোও** ঝুঁকি কমায়।\n\n## শিশু যদি আপনার বিছানায় ঘুমায়\n\nবাংলাদেশের অনেক বাড়িতে শিশু মা-বাবার বিছানাতেই ঘুমায়। নিরাপত্তা বিশেষজ্ঞরা এর বদলে বিছানার পাশে আলাদা একটা জায়গার পরামর্শ দেন। তবু শিশু যদি আপনার বিছানায় ঘুমায়, যতটা সম্ভব নিরাপদ করুন: বিছানা শক্ত হবে, শিশু চিত হয়ে বালিশ ও লেপ থেকে দূরে থাকবে, কখনো দুজন বড় মানুষের মাঝখানে বা অন্য শিশুর পাশে নয়, আর যিনি ধূমপান করেন, ঘুম আনে এমন ওষুধ বা কিছু খেয়েছেন, বা খুবই ক্লান্ত, তাঁর পাশে কখনো নয়। সোফা বা চেয়ারে শিশুকে নিয়ে কখনো ঘুমাবেন না।\n\n## মশারি\n\nবাংলাদেশে মশারি ডেঙ্গুসহ নানা অসুখ থেকে বাঁচায়। ভালো করে গুঁজে টানাবেন, যাতে মশারি শিশুর মুখের ওপর না পড়ে।\n\n## কাপড়ে মুড়িয়ে রাখা\n\nশিশুকে কাপড়ে মুড়িয়ে রাখলে কোমরের দিকে ঢিলা রাখুন, মুখ বা মাথা ঢাকবেন না, সবসময় চিত করে শোয়ান, আর শিশু গড়ানোর চেষ্টা শুরু করলে মোড়ানো বন্ধ করুন।"}'::jsonb, '{"avoid":{"en":["Putting the baby to sleep on the tummy or side","Pillows, bolsters, mustard-seed pillows, soft quilts or toys in the sleep space","Sleeping with the baby on a sofa or chair","Smoking anywhere near the baby","Covering the baby''s head or face during sleep"],"bn":["উপুড় বা কাত করে ঘুম পাড়ানো","ঘুমের জায়গায় বালিশ, কোলবালিশ, সরিষার বালিশ, নরম লেপ বা খেলনা","সোফা বা চেয়ারে শিশুকে নিয়ে ঘুমানো","শিশুর কাছাকাছি কোথাও ধূমপান","ঘুমের সময় শিশুর মাথা বা মুখ ঢেকে দেওয়া"]},"seek_help":{"en":["The baby is very hard to wake or too sleepy to feed","Pauses in breathing, blue lips or noisy, difficult breathing during sleep"],"bn":["শিশুকে জাগানো খুব কঠিন, বা খাওয়ার মতো জাগছে না","ঘুমের মধ্যে শ্বাস থেমে থেমে যাওয়া, ঠোঁট নীল, বা শব্দ করে কষ্ট করে শ্বাস"]}}'::jsonb, 4, 0, 183, '{}'::text[], 'any', ARRAY['safe sleep', 'sids', 'back to sleep', 'bed sharing', 'pillow', 'mosquito net', 'newborn sleep']::text[], false, 'in_review'::lp_review_status, 3014),
  ('nb-jaundice-explained', 'article', 'scientific', 'shared', 'important', 'guideline', '🟡', '{"en":"Newborn jaundice explained","bn":"নবজাতকের জন্ডিস: সহজ কথায়"}'::jsonb, '{"en":"Many newborns look a little yellow in the first week, and most need no treatment. A few signs mean the baby needs a check the same day.","bn":"প্রথম সপ্তাহে অনেক নবজাতককেই একটু হলুদ দেখায়, আর বেশিরভাগের কোনো চিকিৎসা লাগে না। তবে কিছু লক্ষণ দেখলে সেদিনই দেখাতে হবে।"}'::jsonb, '{"en":"## What jaundice is\n\nJaundice is a yellow colour of the skin and the whites of the eyes. It happens when a yellow substance called bilirubin builds up in the blood. A newborn''s liver is still getting going, so bilirubin often rises a little in the first days. This is very common, especially in babies born early.\n\n## The usual pattern\n\nIn most babies the yellow appears on day two or three, starts on the face and moves down the body, then fades within about two weeks. A baby with this kind of jaundice feeds well, wakes for feeds and has wet nappies.\n\n## How to check\n\nLook in good daylight, not under a bulb. Gently press a finger on the baby''s nose, forehead or chest for a second, then lift it. If the skin looks yellow where you pressed, there is jaundice. Note how far down the body it goes. On darker skin, also look at the whites of the eyes, the gums and the palms.\n\n## When jaundice needs a check the same day\n\n- Yellow skin in the first 24 hours of life.\n- Yellow palms and soles, or yellow spreading to the legs and feet.\n- The baby is very sleepy, hard to wake or not feeding well.\n- Jaundice that lasts longer than two weeks in a baby born at term, or three weeks in a premature baby.\n- Pale, whitish or clay-coloured stools, or dark yellow urine that stains the nappy.\n\nVery high bilirubin can harm the brain, so these signs should never be left to wait. Pale stools with jaundice can mean a liver problem that needs early treatment.\n\n## Treatment\n\nIf the level is high, the baby is treated in hospital with a special blue light (phototherapy), which is safe and effective. A blood test shows how high the level is and whether treatment is needed. Very rarely, a blood exchange is needed.\n\n## What helps, and what does not\n\nFrequent breastfeeding helps the baby pass bilirubin in their stools, so keep feeding often, at least 8 times a day. Do not give water, glucose water or herbal remedies. Putting the baby in the sun is not a safe treatment: it is not reliable, and the baby can burn or overheat. If you are worried, get the baby checked.","bn":"## জন্ডিস কী\n\nজন্ডিস (jaundice) হলো ত্বক আর চোখের সাদা অংশ হলুদ হয়ে যাওয়া। রক্তে বিলিরুবিন নামে একটা হলুদ পদার্থ জমে গেলে এমন হয়। নবজাতকের যকৃৎ সবে কাজ শুরু করছে, তাই প্রথম কয়েক দিনে বিলিরুবিন একটু বাড়া খুব সাধারণ, বিশেষ করে সময়ের আগে জন্মানো শিশুদের।\n\n## সাধারণত যেমন হয়\n\nবেশিরভাগ শিশুর হলুদ ভাব দেখা দেয় দ্বিতীয় বা তৃতীয় দিনে; প্রথমে মুখে, তারপর নিচে শরীরের দিকে নামে, আর মোটামুটি দুই সপ্তাহের মধ্যে মিলিয়ে যায়। এমন জন্ডিসে শিশু ভালো খায়, খাওয়ার জন্য জাগে, ন্যাপিও ভেজে।\n\n## কীভাবে দেখবেন\n\nবাল্বের আলোয় নয়, দিনের ভালো আলোয় দেখুন। শিশুর নাক, কপাল বা বুকে এক সেকেন্ড আঙুল দিয়ে আলতো চেপে ছেড়ে দিন। চাপ দেওয়া জায়গা হলুদ দেখালে জন্ডিস আছে। শরীরের কতটা নিচ পর্যন্ত হলুদ, খেয়াল রাখুন। গায়ের রং চাপা হলে চোখের সাদা অংশ, মাড়ি ও হাতের তালুও দেখুন।\n\n## কখন সেদিনই দেখাতে হবে\n\n- জন্মের প্রথম ২৪ ঘণ্টার মধ্যেই ত্বক হলুদ।\n- হাতের তালু ও পায়ের তলা হলুদ, বা হলুদ ভাব পা পর্যন্ত নেমে গেছে।\n- শিশু খুব ঘুমকাতুরে, জাগানো কঠিন, বা ঠিকমতো খাচ্ছে না।\n- সময়মতো জন্মানো শিশুর দুই সপ্তাহ, বা অপরিণত শিশুর তিন সপ্তাহের বেশি জন্ডিস থাকছে।\n- পায়খানা ফ্যাকাশে, সাদাটে বা মাটির রঙের, অথবা প্রস্রাব গাঢ় হলুদ, ন্যাপিতে দাগ লাগছে।\n\nবিলিরুবিন খুব বেশি হলে মস্তিষ্কের ক্ষতি হতে পারে, তাই এই লক্ষণগুলোতে কখনো অপেক্ষা করবেন না। জন্ডিসের সাথে ফ্যাকাশে পায়খানা যকৃতের এমন সমস্যার লক্ষণ হতে পারে, যার দ্রুত চিকিৎসা দরকার।\n\n## চিকিৎসা\n\nমাত্রা বেশি হলে হাসপাতালে বিশেষ নীল আলো দিয়ে চিকিৎসা করা হয় (phototherapy), যা নিরাপদ ও কার্যকর। রক্ত পরীক্ষায় বোঝা যায় মাত্রা কত, আর চিকিৎসা লাগবে কিনা। খুব কম ক্ষেত্রে রক্ত বদলানোর দরকার পড়ে।\n\n## কী কাজে দেয়, কী দেয় না\n\nঘন ঘন বুকের দুধ খেলে শিশু পায়খানার সাথে বিলিরুবিন বের করে দিতে পারে, তাই দিনে অন্তত ৮ বার খাওয়াতে থাকুন। পানি, গ্লুকোজের পানি বা ভেষজ কিছু দেবেন না। রোদে শুইয়ে রাখা নিরাপদ চিকিৎসা নয়: এতে ভরসা করা যায় না, আর শিশুর ত্বক পুড়ে যেতে বা শরীর বেশি গরম হয়ে যেতে পারে। চিন্তা হলে শিশুকে দেখিয়ে নিন।"}'::jsonb, '{"avoid":{"en":["Treating jaundice by putting the baby in the sun","Giving water, glucose water or herbal remedies","Stopping or reducing breastfeeding","Waiting at home when the danger signs are present"],"bn":["রোদে রেখে জন্ডিসের চিকিৎসা করা","পানি, গ্লুকোজের পানি বা ভেষজ কিছু খাওয়ানো","বুকের দুধ বন্ধ করা বা কমিয়ে দেওয়া","বিপদচিহ্ন থাকলেও বাড়িতে অপেক্ষা করা"]}}'::jsonb, 4, 0, 28, '{}'::text[], 'any', ARRAY['jaundice', 'yellow skin', 'bilirubin', 'phototherapy', 'newborn']::text[], false, 'in_review'::lp_review_status, 3015),
  ('nb-vaccines-first-months', 'article', 'scientific', 'shared', 'important', 'guideline', '💉', '{"en":"Vaccines in the first months (Bangladesh EPI)","bn":"প্রথম কয়েক মাসের টিকা (বাংলাদেশ ইপিআই)"}'::jsonb, '{"en":"Bangladesh''s EPI gives free vaccines at birth and at 6, 10 and 14 weeks. Going on time protects your baby when they are most at risk.","bn":"বাংলাদেশের ইপিআই কর্মসূচিতে জন্মের পর এবং ৬, ১০ ও ১৪ সপ্তাহে বিনামূল্যে টিকা দেওয়া হয়। সময়মতো দিলে শিশু সবচেয়ে ঝুঁকির সময়েই সুরক্ষা পায়।"}'::jsonb, '{"en":"## Why the first months matter\n\nYoung babies catch some infections easily and get very ill from them. Vaccines teach the body to fight these diseases before the baby meets them. Bangladesh''s Expanded Programme on Immunization (EPI) gives the routine vaccines free of charge at EPI centres, community clinics, outreach sessions and government hospitals.\n\n## The schedule in the first six months\n\n**At birth, or as soon as possible:**\n- BCG, against severe forms of tuberculosis.\n\n**At 6 weeks:**\n- Pentavalent (Penta 1): diphtheria, whooping cough, tetanus, hepatitis B and Hib.\n- OPV 1: polio drops by mouth.\n- PCV 1: pneumococcal pneumonia and meningitis.\n- fIPV 1: a small polio injection.\n\n**At 10 weeks:**\n- Penta 2, OPV 2 and PCV 2.\n\n**At 14 weeks:**\n- Penta 3, OPV 3, PCV 3 and fIPV 2.\n\nThe next vaccines, measles-rubella and others, come at 9 months. Schedules are updated from time to time, so always follow the dates written on your baby''s vaccine card and what your EPI worker tells you.\n\n## The BCG mark\n\nA few weeks after BCG, a small bump appears on the arm. It may become a little blister or sore that oozes, then heals over weeks, leaving a small scar. This is expected. Keep it clean and dry; do not squeeze it, cover it tightly or put ointments on it.\n\n## On vaccine day\n\n- Bring the vaccine card every time.\n- Breastfeeding during or right after the injection can comfort the baby.\n- A mild cold or slight fever is usually not a reason to delay; ask the vaccinator.\n- If a dose was missed, go as soon as you can. There is no need to start again.\n\n## After vaccines\n\nSome babies are fussy, have a sore leg or a low fever for a day or two. Breastfeed more often and keep the baby lightly dressed. Do not put anything on the injection site. Give fever medicine only if a health worker advises it.\n\n## Get help if\n\nA baby under three months who has a fever of 38 °C or more should be seen the same day, even after a vaccine. Also seek help for fits, crying that cannot be calmed for hours, a very sleepy or floppy baby, or swelling of the face or trouble breathing soon after a vaccine.","bn":"## প্রথম কয়েক মাস কেন গুরুত্বপূর্ণ\n\nছোট শিশুরা কিছু সংক্রমণে সহজেই আক্রান্ত হয় আর খুব অসুস্থ হয়ে পড়ে। রোগের সাথে দেখা হওয়ার আগেই টিকা শরীরকে লড়তে শেখায়। বাংলাদেশের সম্প্রসারিত টিকাদান কর্মসূচি (ইপিআই) ইপিআই কেন্দ্র, কমিউনিটি ক্লিনিক, আউটরিচ টিকাকেন্দ্র ও সরকারি হাসপাতালে নিয়মিত টিকাগুলো বিনামূল্যে দেয়।\n\n## প্রথম ছয় মাসের সূচি\n\n**জন্মের পর, যত তাড়াতাড়ি সম্ভব:**\n- বিসিজি, মারাত্মক যক্ষ্মা থেকে সুরক্ষার জন্য।\n\n**৬ সপ্তাহে:**\n- পেন্টাভ্যালেন্ট (পেন্টা-১): ডিফথেরিয়া, হুপিংকাশি, ধনুষ্টংকার, হেপাটাইটিস-বি ও হিব।\n- ওপিভি-১: মুখে খাওয়ানোর পোলিও ফোঁটা।\n- পিসিভি-১: নিউমোকক্কাল নিউমোনিয়া ও মেনিনজাইটিস।\n- এফআইপিভি-১: পোলিওর ছোট একটা ইনজেকশন।\n\n**১০ সপ্তাহে:**\n- পেন্টা-২, ওপিভি-২ ও পিসিভি-২।\n\n**১৪ সপ্তাহে:**\n- পেন্টা-৩, ওপিভি-৩, পিসিভি-৩ ও এফআইপিভি-২।\n\nপরের টিকা, যেমন হাম-রুবেলা ও অন্যান্য, ৯ মাসে। সূচি মাঝে মাঝে হালনাগাদ হয়, তাই সবসময় শিশুর টিকা কার্ডে লেখা তারিখ আর টিকাকর্মীর কথা মেনে চলুন।\n\n## বিসিজির দাগ\n\nবিসিজি দেওয়ার কয়েক সপ্তাহ পর হাতে ছোট একটা ফোলা ওঠে। সেটা ছোট ফোসকা বা ঘায়ের মতো হয়ে একটু রস বেরোতে পারে, তারপর কয়েক সপ্তাহে শুকিয়ে ছোট একটা দাগ রেখে যায়। এটাই স্বাভাবিক। জায়গাটা পরিষ্কার ও শুকনো রাখুন; চাপ দেবেন না, শক্ত করে ঢাকবেন না, মলম লাগাবেন না।\n\n## টিকার দিনে\n\n- প্রতিবার টিকা কার্ড সাথে নিন।\n- ইনজেকশনের সময় বা ঠিক পরে বুকের দুধ খাওয়ালে শিশু সান্ত্বনা পায়।\n- হালকা সর্দি বা সামান্য জ্বর সাধারণত টিকা পেছানোর কারণ নয়; টিকাদানকারীকে জিজ্ঞেস করুন।\n- কোনো ডোজ বাদ পড়লে যত তাড়াতাড়ি পারেন যান। আবার শুরু থেকে দেওয়ার দরকার নেই।\n\n## টিকার পর\n\nকিছু শিশু এক-দুই দিন খিটখিটে থাকে, পায়ে ব্যথা বা হালকা জ্বর হয়। ঘন ঘন বুকের দুধ দিন, হালকা কাপড় পরান। ইনজেকশনের জায়গায় কিছু লাগাবেন না। স্বাস্থ্যকর্মী বললে তবেই জ্বরের ওষুধ দিন।\n\n## সাহায্য নিন যদি\n\nতিন মাসের কম বয়সী শিশুর ৩৮ °সে বা তার বেশি জ্বর হলে, টিকার পরে হলেও, সেদিনই দেখাতে হবে। এছাড়া খিঁচুনি, কয়েক ঘণ্টা ধরে থামানো যায় না এমন কান্না, শিশু খুব ঘুমকাতুরে বা নেতিয়ে পড়া, কিংবা টিকার পরপরই মুখ ফুলে যাওয়া বা শ্বাসকষ্ট হলে সাহায্য নিন।"}'::jsonb, '{}'::jsonb, 4, 0, 183, '{}'::text[], 'any', ARRAY['vaccines', 'epi', 'bcg', 'pentavalent', 'opv', 'pcv', 'fipv', 'immunisation']::text[], false, 'in_review'::lp_review_status, 3016),
  ('nb-growth-weight', 'article', 'scientific', 'shared', 'routine', 'guideline', '📈', '{"en":"Growth in the first months: weight checks and the growth chart","bn":"প্রথম কয়েক মাসের বৃদ্ধি: ওজন মাপা ও গ্রোথ চার্ট"}'::jsonb, '{"en":"Babies lose a little weight after birth and regain it by about two weeks. After that, the line on the growth chart tells you more than any single number.","bn":"জন্মের পর শিশুর ওজন একটু কমে, আর মোটামুটি দুই সপ্তাহে আবার ফিরে আসে। তারপর থেকে কোনো একটা সংখ্যার চেয়ে গ্রোথ চার্টের রেখাই বেশি কিছু বলে।"}'::jsonb, '{"en":"## The first two weeks\n\nAlmost all newborns lose some weight in the first few days while feeding gets established. Most are back to their birth weight by about two weeks. A baby who loses a lot of weight, or has not regained birth weight by two weeks, needs a feeding check, not just more time.\n\n## After that\n\nIn the first months babies grow fast. Growth is not perfectly smooth: some weeks the baby gains more, some weeks less. What matters is that the baby keeps growing steadily over time.\n\n## The growth chart\n\nYour baby''s health card has a growth chart based on the WHO Child Growth Standards, which describe how healthy breastfed babies grow. Each time your baby is weighed, the health worker marks a dot, and the dots join into a line.\n\n- A line that runs roughly alongside the printed curves is a good sign.\n- A line that goes flat, or drops down across the curves, means the baby needs a closer look at feeding and health.\n- A line that climbs very steeply is also worth discussing.\n\nSmall and premature babies are checked more often and may grow along their own path at first.\n\n## Where to get the baby weighed\n\nAsk for a weight check at each postnatal visit and on vaccine days at your EPI centre, community clinic or doctor. Bring the card each time, and ask the health worker to show you the line. Home scales are often not accurate enough for small changes in babies.\n\n## Length and head size\n\nLength and head circumference are also measured at some visits. Together with weight, they give a fuller picture of growth.\n\n## Signs of good growth between visits\n\n- Six or more wet nappies a day.\n- Regular stools, especially in the first six weeks.\n- Alert, active periods when awake.\n- Clothes that are getting smaller.\n\nTry not to compare your baby with others. Babies come in many healthy sizes; the line on your own baby''s chart is what counts.","bn":"## প্রথম দুই সপ্তাহ\n\nপ্রায় সব নবজাতকেরই প্রথম কয়েক দিনে খাওয়া গুছিয়ে ওঠার মধ্যে কিছুটা ওজন কমে। বেশিরভাগ শিশু মোটামুটি দুই সপ্তাহে জন্মের ওজনে ফিরে আসে। যে শিশুর ওজন অনেক কমে গেছে, বা দুই সপ্তাহেও জন্মের ওজনে ফেরেনি, তার আরও সময় নয়, খাওয়ানো ঠিক হচ্ছে কিনা দেখা দরকার।\n\n## তারপর\n\nপ্রথম কয়েক মাসে শিশু দ্রুত বাড়ে। তবে বৃদ্ধি একদম সমান তালে হয় না: কোনো সপ্তাহে বেশি বাড়ে, কোনো সপ্তাহে কম। গুরুত্বপূর্ণ হলো সময়ের সাথে শিশু নিয়মিত বাড়ছে কিনা।\n\n## গ্রোথ চার্ট\n\nশিশুর স্বাস্থ্য কার্ডে বিশ্ব স্বাস্থ্য সংস্থার শিশু বৃদ্ধির মানদণ্ড অনুযায়ী একটা গ্রোথ চার্ট থাকে, যা দেখায় সুস্থ, বুকের দুধ খাওয়া শিশুরা কীভাবে বাড়ে। প্রতিবার ওজন নেওয়ার পর স্বাস্থ্যকর্মী একটা বিন্দু দেন, আর বিন্দুগুলো জুড়ে একটা রেখা তৈরি হয়।\n\n- রেখাটা ছাপানো বাঁকা দাগগুলোর পাশাপাশি চললে তা ভালো লক্ষণ।\n- রেখা সমান হয়ে গেলে, বা দাগগুলো পেরিয়ে নিচে নামলে, খাওয়ানো ও স্বাস্থ্য ভালো করে দেখা দরকার।\n- রেখা খুব খাড়াভাবে উঠে গেলেও তা নিয়ে কথা বলা ভালো।\n\nছোট ও অপরিণত শিশুদের বেশি ঘন ঘন মাপা হয়, আর শুরুতে তারা নিজেদের মতো পথে বাড়তে পারে।\n\n## কোথায় ওজন মাপাবেন\n\nপ্রতিটি প্রসব-পরবর্তী চেকআপে, আর টিকার দিনে ইপিআই কেন্দ্র, কমিউনিটি ক্লিনিক বা ডাক্তারের কাছে ওজন মাপতে বলুন। প্রতিবার কার্ড সাথে নিন, আর স্বাস্থ্যকর্মীকে রেখাটা দেখিয়ে দিতে বলুন। বাড়ির ওজন মাপার যন্ত্র শিশুর ছোট পরিবর্তন ধরার মতো নির্ভুল হয় না।\n\n## দৈর্ঘ্য ও মাথার মাপ\n\nকিছু চেকআপে শিশুর দৈর্ঘ্য আর মাথার বেড়ও মাপা হয়। ওজনের সাথে মিলিয়ে এগুলো বৃদ্ধির পুরো ছবি দেয়।\n\n## দুই চেকআপের মাঝে ভালো বৃদ্ধির লক্ষণ\n\n- দিনে ৬ বা তার বেশি ভেজা ন্যাপি।\n- নিয়মিত পায়খানা, বিশেষ করে প্রথম ছয় সপ্তাহে।\n- জেগে থাকলে সজাগ ও চঞ্চল।\n- জামাগুলো ছোট হয়ে আসছে।\n\nঅন্য শিশুর সাথে তুলনা না করার চেষ্টা করুন। সুস্থ শিশু নানা আকারের হয়; আপনার নিজের শিশুর চার্টের রেখাটাই আসল।"}'::jsonb, '{"seek_help":{"en":["The baby has not regained birth weight by about two weeks","The growth line goes flat or drops across the curves","Fewer wet nappies, or the baby seems weak or uninterested in feeding"],"bn":["প্রায় দুই সপ্তাহেও শিশু জন্মের ওজনে ফেরেনি","বৃদ্ধির রেখা সমান হয়ে গেছে বা দাগ পেরিয়ে নিচে নামছে","ভেজা ন্যাপি কম, বা শিশু দুর্বল, খাওয়ায় আগ্রহ নেই"]}}'::jsonb, 3, 0, 183, '{}'::text[], 'any', ARRAY['growth', 'weight', 'growth chart', 'birth weight', 'weight gain']::text[], false, 'in_review'::lp_review_status, 3017),
  ('nb-development-talk-sing', 'article', 'scientific', 'shared', 'educational', 'guideline', '🌱', '{"en":"Development from birth to six months, and why talking and singing matter","bn":"জন্ম থেকে ছয় মাসের বিকাশ, আর কথা বলা ও গান গাওয়া কেন জরুরি"}'::jsonb, '{"en":"In six months your baby goes from a newborn to a laughing, reaching, rolling little person. Your face, voice and touch are what drive this growth.","bn":"ছয় মাসে আপনার শিশু নবজাতক থেকে হাসিখুশি, হাত বাড়ানো, গড়াগড়ি দেওয়া এক ছোট্ট মানুষ হয়ে ওঠে। আপনার মুখ, কণ্ঠ আর ছোঁয়াই এই বেড়ে ওঠার মূল চালিকা।"}'::jsonb, '{"en":"## The brain grows through care\n\nA baby''s brain grows faster in the first years than at any other time. It grows through everyday back-and-forth moments: the baby makes a sound or a face, and you answer. Feeding, changing, bathing and cuddling are all chances to talk, look and touch.\n\n## What many babies do\n\nBabies develop at their own pace. These are things most babies do by the ages shown.\n\n**By about 2 months**\n- Calms when spoken to or picked up, and looks at your face.\n- Smiles when you talk or smile at them.\n- Makes sounds other than crying, and reacts to loud sounds.\n- Holds the head up for a moment when on the tummy.\n\n**By about 4 months**\n- Smiles to get your attention and chuckles.\n- Coos back when you talk, and turns towards your voice.\n- Holds the head steady when held, and brings hands to the mouth.\n\n**By about 6 months**\n- Knows familiar people, and laughs.\n- Takes turns making sounds with you.\n- Reaches for and grabs a toy, and rolls from tummy to back.\n\nFor a baby born early, count from the due date, not the birth date, when checking these.\n\n## Talking and singing\n\n- Talk to your baby during everyday care: tell them what you are doing, name things, describe the world.\n- Hold your face close, about 20 to 30 cm away, where a newborn sees best.\n- When your baby coos, pause and answer, as in a conversation.\n- Sing lullabies, rhymes and songs in your own language. Grandparents often know many.\n- Look at simple picture books together, even very early.\n\nScreens are not recommended for babies under one year. Your voice and face teach far more.\n\n## Talk to a health worker if your baby\n\n- Does not react to loud sounds, or does not look at faces or follow moving things with the eyes.\n- Has not started to smile at people by about 3 months.\n- Is very floppy or very stiff, or still cannot hold the head up at 4 months.\n- Loses a skill they used to have.\n\nIf you are worried, do not wait. Early help works best, and it is always fine to ask.","bn":"## যত্নের মধ্য দিয়েই মস্তিষ্ক বাড়ে\n\nজীবনের প্রথম কয়েক বছরে শিশুর মস্তিষ্ক যত দ্রুত বাড়ে, আর কখনো তত দ্রুত বাড়ে না। আর তা বাড়ে প্রতিদিনের ছোট ছোট আদান-প্রদানে: শিশু একটা শব্দ করে বা মুখভঙ্গি করে, আপনি সাড়া দেন। খাওয়ানো, ন্যাপি বদলানো, গোসল, কোলে নেওয়া, সবই কথা বলা, তাকানো আর ছোঁয়ার সুযোগ।\n\n## বেশিরভাগ শিশু যা করে\n\nপ্রত্যেক শিশু নিজের গতিতে বাড়ে। নিচের কাজগুলো বেশিরভাগ শিশু মোটামুটি এই বয়সের মধ্যে করে।\n\n**প্রায় ২ মাসে**\n- কথা বললে বা কোলে নিলে শান্ত হয়, আপনার মুখের দিকে তাকায়।\n- আপনি কথা বললে বা হাসলে হাসে।\n- কান্না ছাড়াও নানা শব্দ করে, জোরে আওয়াজে চমকে ওঠে।\n- উপুড় করলে এক মুহূর্ত মাথা তুলে রাখে।\n\n**প্রায় ৪ মাসে**\n- আপনার মনোযোগ পেতে হাসে, খিলখিল করে।\n- আপনি কথা বললে আ-উ শব্দে উত্তর দেয়, আপনার গলার দিকে মাথা ঘোরায়।\n- কোলে নিলে মাথা স্থির রাখে, হাত মুখে নেয়।\n\n**প্রায় ৬ মাসে**\n- চেনা মানুষ চেনে, শব্দ করে হাসে।\n- আপনার সাথে পালা করে শব্দ করে।\n- খেলনার দিকে হাত বাড়িয়ে ধরে, উপুড় থেকে চিত হয়ে গড়ায়।\n\nসময়ের আগে জন্মানো শিশুর ক্ষেত্রে জন্মের তারিখ নয়, প্রসবের সম্ভাব্য তারিখ থেকে হিসাব করুন।\n\n## কথা বলা ও গান গাওয়া\n\n- প্রতিদিনের যত্নের সময় শিশুর সাথে কথা বলুন: কী করছেন বলুন, জিনিসের নাম বলুন, চারপাশের গল্প করুন।\n- মুখ কাছে রাখুন, মোটামুটি ২০ থেকে ৩০ সেন্টিমিটার দূরে; নবজাতক এই দূরত্বেই সবচেয়ে ভালো দেখে।\n- শিশু আ-উ করলে একটু থামুন, তারপর উত্তর দিন, ঠিক কথোপকথনের মতো।\n- নিজের ভাষায় ঘুমপাড়ানি গান, ছড়া আর গান শোনান। নানি-দাদিরা প্রায়ই অনেক জানেন।\n- একদম ছোট থেকেই সহজ ছবির বই একসাথে দেখুন।\n\nএক বছরের কম বয়সী শিশুর জন্য স্ক্রিন একদমই সুপারিশ করা হয় না। আপনার কণ্ঠ আর মুখ তার চেয়ে অনেক বেশি শেখায়।\n\n## স্বাস্থ্যকর্মীর সাথে কথা বলুন যদি শিশু\n\n- জোরে আওয়াজে সাড়া না দেয়, মুখের দিকে না তাকায়, বা চলন্ত জিনিস চোখ দিয়ে না অনুসরণ করে।\n- প্রায় ৩ মাসেও মানুষের দিকে তাকিয়ে হাসতে শুরু না করে।\n- খুব নেতানো বা খুব শক্ত থাকে, বা ৪ মাসেও মাথা তুলে রাখতে না পারে।\n- আগে পারত এমন কোনো কাজ আর না পারে।\n\nচিন্তা হলে অপেক্ষা করবেন না। শুরুতে সাহায্য নিলেই সবচেয়ে ভালো ফল পাওয়া যায়, আর জিজ্ঞেস করায় কোনো দোষ নেই।"}'::jsonb, '{}'::jsonb, 4, 0, 183, '{}'::text[], 'any', ARRAY['development', 'milestones', 'talking', 'singing', 'smile', 'cooing', 'brain development']::text[], false, 'in_review'::lp_review_status, 3018),
  ('nb-tummy-time', 'article', 'scientific', 'shared', 'routine', 'guideline', '🐢', '{"en":"Tummy time: why and how","bn":"উপুড় হয়ে খেলা (টামি টাইম): কেন ও কীভাবে"}'::jsonb, '{"en":"Babies sleep on their backs, so they need time on their tummies while awake. A few short sessions a day build strong necks, shoulders and backs.","bn":"শিশু ঘুমায় চিত হয়ে, তাই জেগে থাকার সময় তাকে উপুড় হয়ে থাকারও সুযোগ দিতে হয়। দিনে কয়েকবার অল্প সময় করে উপুড় হয়ে খেললে ঘাড়, কাঁধ ও পিঠ শক্ত হয়।"}'::jsonb, '{"en":"## Why tummy time\n\nLying on the tummy while awake helps a baby:\n\n- strengthen the neck, shoulders, arms and back;\n- get ready to roll, sit and crawl;\n- avoid a flat patch on the back of the head from always lying on the back;\n- see the world from a new angle.\n\nWHO advises that babies who are not yet crawling have at least 30 minutes of tummy time a day, spread out in short sessions, while they are awake. Babies should also not be kept in a chair, sling or carrier for more than an hour at a time.\n\n## Start early and small\n\nYou can begin in the first days at home. The easiest start is to lie back and place your baby tummy-down on your chest, face to face. Begin with a minute or two, a few times a day, and add a little more as your baby gets stronger.\n\n## Ways to make it easier\n\n- Choose a time when the baby is awake and content, not straight after a feed and not when very tired.\n- Get down on the floor at eye level so the baby can see your face.\n- Place the baby across your lap, or with a rolled towel under the chest and armpits.\n- Show a colourful object or an unbreakable mirror, or let a brother or sister lie in front and chat.\n- Make it part of the routine, for example after each nappy change.\n\nMany babies fuss at first. That is normal. Stop when the baby is upset and try again later; short, happy sessions are better than long, unhappy ones.\n\n## Safety\n\n- Always stay with the baby and watch them during tummy time.\n- Use a clean, firm surface on the floor, such as a mat, not a high bed the baby could roll off.\n- If the baby falls asleep, turn them onto their back.\n- Tummy time is for awake play only. Sleep is always on the back.\n\n## Talk to a health worker if\n\nYour baby cannot lift the head at all by about 3 months, always turns the head to the same side, or seems very stiff or floppy.","bn":"## কেন উপুড় হয়ে খেলা\n\nজেগে থাকার সময় উপুড় হয়ে থাকলে শিশু:\n\n- ঘাড়, কাঁধ, হাত ও পিঠে জোর পায়;\n- গড়ানো, বসা ও হামাগুড়ির জন্য তৈরি হয়;\n- সবসময় চিত হয়ে থাকার কারণে মাথার পেছনে চ্যাপ্টা ভাব হওয়া এড়াতে পারে;\n- নতুন দিক থেকে চারপাশ দেখে।\n\nবিশ্ব স্বাস্থ্য সংস্থা বলে, যে শিশু এখনো হামাগুড়ি দেয় না, সে জেগে থাকা অবস্থায় দিনে অন্তত ৩০ মিনিট উপুড় হয়ে খেলবে, অল্প অল্প করে ভাগ করে। আর শিশুকে একটানা এক ঘণ্টার বেশি চেয়ার, দোলনা বা ক্যারিয়ারে আটকে রাখা উচিত নয়।\n\n## অল্প করে, তাড়াতাড়ি শুরু\n\nবাড়ি ফেরার প্রথম দিনগুলো থেকেই শুরু করা যায়। সবচেয়ে সহজ শুরু হলো আপনি হেলান দিয়ে শুয়ে শিশুকে আপনার বুকের ওপর উপুড় করে রাখা, মুখোমুখি। দিনে কয়েকবার এক-দুই মিনিট দিয়ে শুরু করুন, শিশু যত শক্ত হবে সময় তত একটু একটু বাড়ান।\n\n## সহজ করার কিছু উপায়\n\n- শিশু যখন জেগে আছে আর খুশি আছে, তখন করুন; খাওয়ার ঠিক পরে বা খুব ক্লান্ত অবস্থায় নয়।\n- মেঝেতে শুয়ে শিশুর চোখের সমান হোন, যাতে সে আপনার মুখ দেখতে পায়।\n- শিশুকে আপনার কোলের ওপর আড়াআড়ি রাখুন, বা বুক ও বগলের নিচে গোল করে পাকানো তোয়ালে দিন।\n- রঙিন কিছু বা না-ভাঙা আয়না দেখান, কিংবা ভাই-বোনকে সামনে শুয়ে গল্প করতে দিন।\n- রুটিনের অংশ করে নিন, যেমন প্রতিবার ন্যাপি বদলানোর পর।\n\nঅনেক শিশু শুরুতে কান্নাকাটি করে, এটা স্বাভাবিক। শিশু বিরক্ত হলে থামুন, পরে আবার চেষ্টা করুন; লম্বা কান্নার সময়ের চেয়ে অল্প সময়ের আনন্দের খেলা ভালো।\n\n## নিরাপত্তা\n\n- উপুড় হয়ে থাকার পুরো সময় শিশুর সাথে থাকুন, চোখ রাখুন।\n- মেঝেতে পরিষ্কার, শক্ত জায়গা যেমন মাদুর ব্যবহার করুন; উঁচু খাট নয়, যেখান থেকে গড়িয়ে পড়তে পারে।\n- শিশু ঘুমিয়ে পড়লে চিত করে দিন।\n- উপুড় হয়ে থাকা শুধু জেগে খেলার জন্য। ঘুম সবসময় চিত হয়ে।\n\n## স্বাস্থ্যকর্মীর সাথে কথা বলুন যদি\n\nপ্রায় ৩ মাসেও শিশু একদম মাথা তুলতে না পারে, সবসময় একই দিকে মাথা ঘুরিয়ে রাখে, বা খুব শক্ত বা খুব নেতানো মনে হয়।"}'::jsonb, '{}'::jsonb, 3, 0, 183, '{}'::text[], 'any', ARRAY['tummy time', 'neck strength', 'flat head', 'motor development', 'play']::text[], false, 'in_review'::lp_review_status, 3019),
  ('nb-father-newborn-months', 'article', 'general', 'father', 'routine', 'consensus', '👨‍🍼', '{"en":"Fathers and newborns: your role in the first months","bn":"বাবা ও নবজাতক: প্রথম কয়েক মাসে আপনার ভূমিকা"}'::jsonb, '{"en":"A father who holds, bathes, settles and protects his baby builds a bond that lasts, and gives the mother the support she needs to recover and breastfeed.","bn":"যে বাবা শিশুকে কোলে নেন, গোসল করান, ঘুম পাড়ান আর আগলে রাখেন, তিনি শিশুর সাথে আজীবনের বন্ধন গড়েন, আর মাকেও সেরে উঠতে ও বুকের দুধ খাওয়াতে প্রয়োজনীয় সমর্থন দেন।"}'::jsonb, '{"en":"## Your baby needs you too\n\nBabies form close bonds with the people who care for them, not only the person who feeds them. Holding, talking, bathing and comforting your baby every day builds that bond from the start. Fathers who are involved early tend to stay involved, and their children benefit.\n\n## Things you can do from day one\n\n- **Skin-to-skin**: hold your baby on your bare chest. It calms the baby and helps you feel close. For a small baby, you can take turns with kangaroo care.\n- **Nappies and burping**: change, clean and burp the baby after feeds.\n- **Bath time**: make the bath your job, once the first days are over.\n- **Settling**: walk, rock and sing to a fussy baby, so the mother can sleep.\n- **Talk and play**: tell your baby about your day; your voice is different from the mother''s, and babies love that.\n\n## Supporting the mother\n\nBreastfeeding works best when the mother is rested, fed and not under pressure.\n\n- Bring her water and food during feeds.\n- Take over cooking, shopping, washing and household work, or arrange help.\n- Protect her rest: limit visitors and keep the room quiet.\n- If relatives push for formula, honey or other feeds, stand with her and the health worker''s advice.\n- Ask her how she is feeling, and listen.\n\n## The practical side\n\n- Take mother and baby to postnatal check-ups and vaccine visits, and keep the cards safe.\n- Learn the danger signs for both of them, and know how you would get to hospital quickly, day or night.\n- Start the baby''s birth registration.\n- Keep the home smoke-free.\n\n## Your own wellbeing\n\nNew fathers can feel tired, worried or low too. Money pressure, work and broken sleep add up. Talk to your partner, a friend or a health worker if you feel overwhelmed for more than a couple of weeks.\n\n## If you work away from home\n\nMany Bangladeshi fathers work far away or abroad. Call often, ask about the baby, sing or talk to them on video, and support the mother from a distance. When you are home, be hands-on. It all counts.","bn":"## শিশুর আপনাকেও দরকার\n\nশিশু শুধু যিনি খাওয়ান তাঁর সাথে নয়, যাঁরা তার যত্ন নেন তাঁদের সবার সাথে গভীর বন্ধন গড়ে। প্রতিদিন কোলে নেওয়া, কথা বলা, গোসল করানো আর সান্ত্বনা দেওয়া শুরু থেকেই সেই বন্ধন গড়ে তোলে। যে বাবারা শুরু থেকে যুক্ত থাকেন, তাঁরা সাধারণত পরেও যুক্ত থাকেন, আর এতে সন্তান উপকৃত হয়।\n\n## প্রথম দিন থেকেই যা করতে পারেন\n\n- **ত্বকের ছোঁয়া**: শিশুকে আপনার খালি বুকে জড়িয়ে রাখুন। এতে শিশু শান্ত হয়, আপনিও কাছের অনুভব করেন। ছোট শিশু হলে মায়ের সাথে পালা করে ক্যাঙ্গারু পদ্ধতিতে রাখতে পারেন।\n- **ন্যাপি ও ঢেকুর**: খাওয়ানোর পর ন্যাপি বদলানো, পরিষ্কার করা ও ঢেকুর তোলানোর কাজ নিন।\n- **গোসলের সময়**: প্রথম কয়েক দিন পেরোলে শিশুর গোসল আপনার দায়িত্ব করে নিন।\n- **ঘুম পাড়ানো**: কাঁদতে থাকা শিশুকে কোলে নিয়ে হাঁটুন, দোলান, গান শোনান, যাতে মা ঘুমাতে পারেন।\n- **কথা ও খেলা**: শিশুকে আপনার দিনের গল্প বলুন; আপনার কণ্ঠ মায়ের চেয়ে আলাদা, আর শিশুরা সেটা পছন্দ করে।\n\n## মায়ের পাশে থাকা\n\nমা বিশ্রাম পেলে, পেট ভরে খেলে আর চাপমুক্ত থাকলে বুকের দুধ খাওয়ানো সবচেয়ে ভালো হয়।\n\n- খাওয়ানোর সময় তাঁকে পানি ও খাবার এগিয়ে দিন।\n- রান্না, বাজার, কাপড় ধোয়া ও ঘরের কাজ নিজে করুন, বা কারও সাহায্যের ব্যবস্থা করুন।\n- তাঁর বিশ্রাম আগলে রাখুন: অতিথি সীমিত রাখুন, ঘর শান্ত রাখুন।\n- আত্মীয়রা ফর্মুলা, মধু বা অন্য কিছু খাওয়ানোর চাপ দিলে মায়ের আর স্বাস্থ্যকর্মীর পরামর্শের পাশে দাঁড়ান।\n- তিনি কেমন বোধ করছেন জিজ্ঞেস করুন, আর মন দিয়ে শুনুন।\n\n## ব্যবহারিক দিক\n\n- মা ও শিশুকে প্রসব-পরবর্তী চেকআপ ও টিকার দিনে নিয়ে যান, কার্ডগুলো যত্ন করে রাখুন।\n- দুজনেরই বিপদচিহ্নগুলো জেনে রাখুন, আর দিন-রাত যেকোনো সময় দ্রুত হাসপাতালে কীভাবে যাবেন তা ঠিক করে রাখুন।\n- শিশুর জন্ম নিবন্ধনের কাজ শুরু করুন।\n- বাড়ি ধোঁয়ামুক্ত রাখুন।\n\n## আপনার নিজের সুস্থতা\n\nনতুন বাবারাও ক্লান্ত, চিন্তিত বা মনমরা বোধ করতে পারেন। টাকার চাপ, কাজ আর ভাঙা ঘুম মিলে ভারী হয়ে ওঠে। দুই সপ্তাহের বেশি এমন অসহায় লাগলে স্ত্রী, বন্ধু বা একজন স্বাস্থ্যকর্মীর সাথে কথা বলুন।\n\n## যদি বাড়ি থেকে দূরে কাজ করেন\n\nবাংলাদেশের অনেক বাবা দূরে বা বিদেশে কাজ করেন। ঘন ঘন ফোন করুন, শিশুর খোঁজ নিন, ভিডিও কলে তার সাথে কথা বলুন বা গান শোনান, আর দূর থেকেই মায়ের পাশে থাকুন। বাড়িতে থাকলে নিজের হাতে যত্ন নিন। সবটুকুই গুরুত্বপূর্ণ।"}'::jsonb, '{}'::jsonb, 4, 0, 183, '{}'::text[], 'any', ARRAY['father', 'bonding', 'skin to skin', 'support mother', 'newborn care', 'dad']::text[], false, 'in_review'::lp_review_status, 3020),
  ('nb-mother-body-recovery', 'article', 'scientific', 'mother', 'important', 'guideline', '🌷', '{"en":"Your body after birth: bleeding, stitches and caesarean recovery","bn":"প্রসবের পর শরীর: রক্তস্রাব, সেলাই ও সিজারের পর সেরে ওঠা"}'::jsonb, '{"en":"Bleeding, soreness and tiredness are normal for some weeks after birth. Knowing what is normal, and which signs need help at once, keeps you safe.","bn":"প্রসবের পর কয়েক সপ্তাহ রক্তস্রাব, ব্যথা আর ক্লান্তি স্বাভাবিক। কোনটা স্বাভাবিক আর কোন লক্ষণে সাথে সাথে সাহায্য লাগবে, তা জানলে আপনি নিরাপদ থাকবেন।"}'::jsonb, '{"en":"## Bleeding after birth (lochia)\n\nAfter any birth, vaginal or caesarean, the womb sheds its lining as it heals. The bleeding is heavy and bright red for the first few days, then becomes lighter and pinkish-brown, and later yellowish or white. It often lasts four to six weeks. It may increase a little when you breastfeed or get up after resting.\n\n- Use clean pads or cloths and change them often.\n- If you use cloth, wash it with soap, rinse well and dry it in the sun.\n- Wash your hands before and after changing.\n\n## Afterpains\n\nThe womb shrinks back over the weeks after birth. You may feel cramps, especially while breastfeeding in the first days. This is normal and a sign the womb is contracting well.\n\n## Stitches and soreness below\n\nAfter a vaginal birth the area between the vagina and anus (perineum) is often sore, swollen or stitched.\n\n- Wash the area with clean water after using the toilet, and pat dry from front to back.\n- Sit on a soft cushion, or lie on your side to feed.\n- A cool, clean cloth can ease swelling in the first day or two.\n- Most stitches dissolve on their own.\n- Drink plenty and eat fibre to keep stools soft; do not strain.\n\n## After a caesarean\n\nA caesarean is major surgery, and healing takes time.\n\n- Get up and walk gently as soon as you are advised; it helps prevent clots.\n- Keep the wound clean and dry, and follow the advice about dressings and stitch removal.\n- Hold a pillow over the wound when you cough, laugh or stand up.\n- Avoid lifting anything heavier than your baby for about six weeks, and ask for help.\n- Breastfeed lying on your side or with the baby under your arm.\n\n## Pain relief and passing urine\n\nAsk your health worker which pain medicine is safe while breastfeeding. Pass urine within a few hours of birth. Some leaking of urine is common at first; pelvic floor exercises help.\n\n## Danger signs: go to hospital now\n\n- Heavy bleeding that soaks a pad in an hour or less, or large clots\n- Fever or shivering, or a bad-smelling discharge\n- Severe pain in the belly, or a wound that is red, swollen, leaking pus or opening\n- A severe headache, blurred vision, fits or swelling of the face and hands\n- Difficulty breathing or chest pain\n- Pain, redness or swelling in one leg\n- Thoughts of harming yourself or your baby","bn":"## প্রসবের পর রক্তস্রাব\n\nস্বাভাবিক বা সিজার, যেভাবেই প্রসব হোক, জরায়ু সেরে ওঠার সময় তার ভেতরের আস্তরণ বের হয়ে আসে। প্রথম কয়েক দিন রক্তস্রাব বেশি ও উজ্জ্বল লাল হয়, তারপর কমে গিয়ে গোলাপি-বাদামি, আর পরে হলদেটে বা সাদাটে হয়। সাধারণত চার থেকে ছয় সপ্তাহ থাকে। বুকের দুধ খাওয়ানোর সময় বা বিশ্রামের পর উঠে দাঁড়ালে একটু বাড়তে পারে।\n\n- পরিষ্কার প্যাড বা কাপড় ব্যবহার করুন, ঘন ঘন বদলান।\n- কাপড় ব্যবহার করলে সাবান দিয়ে ধুয়ে ভালো করে পানি ঝরিয়ে রোদে শুকান।\n- বদলানোর আগে ও পরে হাত ধুয়ে নিন।\n\n## পেটে মোচড়ানো ব্যথা\n\nপ্রসবের পর কয়েক সপ্তাহ ধরে জরায়ু আবার ছোট হতে থাকে। প্রথম কয়েক দিন, বিশেষ করে বুকের দুধ খাওয়ানোর সময়, পেটে মোচড়ানো ব্যথা হতে পারে। এটা স্বাভাবিক, আর বোঝায় জরায়ু ঠিকমতো সংকুচিত হচ্ছে।\n\n## নিচের দিকে সেলাই ও ব্যথা\n\nস্বাভাবিক প্রসবের পর যোনিপথ ও মলদ্বারের মাঝের অংশে প্রায়ই ব্যথা, ফোলা বা সেলাই থাকে।\n\n- টয়লেটের পর পরিষ্কার পানি দিয়ে জায়গাটা ধুয়ে সামনে থেকে পেছনের দিকে চেপে শুকিয়ে নিন।\n- নরম গদির ওপর বসুন, বা কাত হয়ে শুয়ে খাওয়ান।\n- প্রথম এক-দুই দিন পরিষ্কার ঠান্ডা কাপড় দিলে ফোলা কমে।\n- বেশিরভাগ সেলাই নিজে নিজেই মিশে যায়।\n- পায়খানা নরম রাখতে বেশি করে পানি আর আঁশযুক্ত খাবার খান; জোরে চাপ দেবেন না।\n\n## সিজারের পর\n\nসিজার একটা বড় অপারেশন, সেরে উঠতে সময় লাগে।\n\n- যখন বলা হবে, তখনই আস্তে আস্তে উঠে হাঁটুন; এতে রক্ত জমাট বাঁধার ঝুঁকি কমে।\n- সেলাইয়ের জায়গা পরিষ্কার ও শুকনো রাখুন, ড্রেসিং ও সেলাই কাটার পরামর্শ মেনে চলুন।\n- কাশি, হাসি বা উঠে দাঁড়ানোর সময় সেলাইয়ের ওপর একটা বালিশ চেপে ধরুন।\n- মোটামুটি ছয় সপ্তাহ শিশুর চেয়ে ভারী কিছু তুলবেন না, সাহায্য চেয়ে নিন।\n- কাত হয়ে শুয়ে বা শিশুকে বগলের নিচে ধরে বুকের দুধ খাওয়ান।\n\n## ব্যথার ওষুধ ও প্রস্রাব\n\nবুকের দুধ খাওয়ানোর সময় কোন ব্যথার ওষুধ নিরাপদ, স্বাস্থ্যকর্মীকে জিজ্ঞেস করুন। প্রসবের কয়েক ঘণ্টার মধ্যে প্রস্রাব করুন। শুরুতে একটু প্রস্রাব চুইয়ে পড়া সাধারণ ব্যাপার; তলপেটের মাংসপেশির ব্যায়ামে উপকার হয়।\n\n## বিপদচিহ্ন: এখনই হাসপাতালে যান\n\n- এত বেশি রক্তপাত যে এক ঘণ্টা বা তার কম সময়ে প্যাড ভিজে যায়, বা বড় বড় রক্তের দলা\n- জ্বর বা কাঁপুনি, বা দুর্গন্ধযুক্ত স্রাব\n- পেটে তীব্র ব্যথা, বা সেলাইয়ের জায়গা লাল, ফোলা, পুঁজ বেরোচ্ছে বা খুলে যাচ্ছে\n- তীব্র মাথাব্যথা, চোখে ঝাপসা দেখা, খিঁচুনি, বা মুখ ও হাত ফুলে যাওয়া\n- শ্বাসকষ্ট বা বুকে ব্যথা\n- এক পায়ে ব্যথা, লাল হওয়া বা ফোলা\n- নিজের বা শিশুর ক্ষতি করার চিন্তা"}'::jsonb, '{"seek_help":{"en":["Bleeding that gets heavier instead of lighter after the first week","Pain or burning when passing urine, or not being able to pass urine","Stitches that are very painful or seem to be coming apart","Leaking of urine or stool that is not improving"],"bn":["প্রথম সপ্তাহের পর রক্তস্রাব না কমে বরং বাড়ছে","প্রস্রাবে ব্যথা বা জ্বালা, বা প্রস্রাব না হওয়া","সেলাইয়ে খুব ব্যথা, বা খুলে যাচ্ছে মনে হচ্ছে","প্রস্রাব বা পায়খানা চুইয়ে পড়া কমছে না"]}}'::jsonb, 5, 0, 42, '{}'::text[], 'any', ARRAY['postpartum', 'lochia', 'bleeding', 'stitches', 'perineum', 'caesarean', 'recovery', 'danger signs']::text[], false, 'in_review'::lp_review_status, 3021),
  ('nb-mother-food-rest-check', 'article', 'scientific', 'mother', 'important', 'guideline', '🍲', '{"en":"Food, rest and check-ups after birth, including the 6-week check","bn":"প্রসবের পর খাবার, বিশ্রাম ও চেকআপ, ছয় সপ্তাহের চেকআপসহ"}'::jsonb, '{"en":"A mother who is healing and breastfeeding needs good food, rest and her own check-ups. The 6-week visit is a chance to make sure she is fully well.","bn":"যে মা সেরে উঠছেন আর বুকের দুধ খাওয়াচ্ছেন, তাঁর দরকার ভালো খাবার, বিশ্রাম আর নিজের চেকআপ। ছয় সপ্তাহের চেকআপে নিশ্চিত হওয়া যায় তিনি পুরোপুরি সুস্থ কিনা।"}'::jsonb, '{"en":"## Eating well\n\nAfter birth your body is healing and, if you breastfeed, making milk. You need a little more food than usual, not special or restricted food.\n\n- Eat a mix every day: rice or roti, lentils, fish, eggs, meat or beans, green leafy vegetables, other vegetables and fruit.\n- Add an extra small meal or snack, such as a handful of nuts, an egg, or milk.\n- Drink to your thirst; a glass of water at each feed is a simple habit.\n- Use iodised salt.\n- Keep taking iron-folic acid tablets for as long as your health worker advises.\n\nThere is no need to avoid ordinary healthy foods such as fish, eggs or vegetables after birth. A varied diet helps you recover and keeps you strong.\n\n## Resting\n\nBroken nights are part of life with a newborn. Rest is part of healing.\n\n- Sleep or lie down when the baby sleeps, at least once during the day.\n- Let others do the cooking, cleaning and caring for visitors.\n- Ask the father or another adult to take the baby between feeds so you can have a longer stretch of sleep.\n- Gentle walking from the first days is good; heavier work and exercise can wait until you feel ready and your health worker agrees.\n\n## Your postnatal check-ups\n\nWHO advises at least four postnatal contacts for mother and baby: within the first 24 hours, around day 3, between days 7 and 14, and at about 6 weeks. These can be at a facility or a home visit. Go even if you feel well; some problems, such as high blood pressure or anaemia, have no early signs.\n\n## The 6-week check\n\nAround six weeks after birth the health worker usually checks:\n\n- your blood pressure, bleeding, and how stitches or a caesarean wound have healed;\n- signs of anaemia or infection;\n- how breastfeeding is going;\n- your mood and sleep;\n- family planning, if you want to discuss it.\n\nIf you had high blood pressure or diabetes in pregnancy, ask whether you need a follow-up test. Your baby is usually due their first EPI vaccines at the same time, so you can plan one trip for both.\n\nWrite your questions down beforehand. This visit is about you, too.","bn":"## ভালো করে খাওয়া\n\nপ্রসবের পর আপনার শরীর সেরে উঠছে, আর বুকের দুধ খাওয়ালে দুধও তৈরি করছে। আপনার দরকার স্বাভাবিকের চেয়ে একটু বেশি খাবার, বিশেষ বা বাছাই-করা খাবার নয়।\n\n- প্রতিদিন মিলিয়ে খান: ভাত বা রুটি, ডাল, মাছ, ডিম, মাংস বা শিমের বিচি, সবুজ শাক, অন্য সবজি ও ফল।\n- বাড়তি একবেলা হালকা খাবার যোগ করুন, যেমন এক মুঠো বাদাম, একটা ডিম বা দুধ।\n- তেষ্টা মিটিয়ে পানি খান; প্রতিবার খাওয়ানোর সময় এক গ্লাস পানি খাওয়া একটা সহজ অভ্যাস।\n- আয়োডিনযুক্ত লবণ খান।\n- স্বাস্থ্যকর্মী যতদিন বলেন, আয়রন-ফলিক অ্যাসিড ট্যাবলেট খেয়ে যান।\n\nপ্রসবের পর মাছ, ডিম বা শাকসবজির মতো সাধারণ স্বাস্থ্যকর খাবার বাদ দেওয়ার কোনো দরকার নেই। নানা রকম খাবার আপনাকে সেরে উঠতে সাহায্য করে আর শক্তি জোগায়।\n\n## বিশ্রাম\n\nনবজাতক থাকলে রাতের ঘুম ভাঙবেই। বিশ্রামও সেরে ওঠার অংশ।\n\n- শিশু ঘুমালে আপনিও ঘুমান বা শুয়ে থাকুন, দিনে অন্তত একবার।\n- রান্না, ঘর পরিষ্কার আর অতিথি সামলানোর কাজ অন্যদের করতে দিন।\n- দুই খাওয়ানোর মাঝে বাবা বা বাড়ির অন্য কাউকে শিশুকে নিতে বলুন, যাতে আপনি একটু লম্বা সময় ঘুমাতে পারেন।\n- প্রথম দিন থেকেই আস্তে আস্তে হাঁটা ভালো; ভারী কাজ ও ব্যায়াম তখনই, যখন আপনি প্রস্তুত বোধ করবেন আর স্বাস্থ্যকর্মী সম্মতি দেবেন।\n\n## প্রসব-পরবর্তী চেকআপ\n\nবিশ্ব স্বাস্থ্য সংস্থা মা ও শিশুর জন্য অন্তত চারবার প্রসব-পরবর্তী সেবার পরামর্শ দেয়: প্রথম ২৪ ঘণ্টার মধ্যে, তৃতীয় দিনের কাছাকাছি, ৭ থেকে ১৪ দিনের মধ্যে, আর প্রায় ৬ সপ্তাহে। এগুলো হাসপাতাল-ক্লিনিকে বা বাড়িতে এসে দেখা, দুভাবেই হতে পারে। ভালো বোধ করলেও যান; উচ্চ রক্তচাপ বা রক্তস্বল্পতার মতো কিছু সমস্যা শুরুতে কোনো লক্ষণ দেখায় না।\n\n## ছয় সপ্তাহের চেকআপ\n\nপ্রসবের প্রায় ছয় সপ্তাহ পর স্বাস্থ্যকর্মী সাধারণত দেখেন:\n\n- আপনার রক্তচাপ, রক্তস্রাব, আর সেলাই বা সিজারের ক্ষত কেমন শুকিয়েছে;\n- রক্তস্বল্পতা বা সংক্রমণের লক্ষণ;\n- বুকের দুধ খাওয়ানো কেমন চলছে;\n- আপনার মন ও ঘুম কেমন;\n- চাইলে পরিবার পরিকল্পনা নিয়ে আলোচনা।\n\nগর্ভাবস্থায় উচ্চ রক্তচাপ বা ডায়াবেটিস থাকলে পরে আবার পরীক্ষা লাগবে কিনা জিজ্ঞেস করুন। সাধারণত এই সময়েই শিশুর প্রথম ইপিআই টিকারও সময় হয়, তাই দুজনের জন্য একবারেই যাওয়ার পরিকল্পনা করতে পারেন।\n\nআগে থেকে প্রশ্নগুলো লিখে নিন। এই চেকআপ আপনার জন্যও।"}'::jsonb, '{}'::jsonb, 4, 0, 56, '{}'::text[], 'any', ARRAY['postpartum nutrition', 'rest', 'iron folic acid', 'postnatal check', 'six week check']::text[], false, 'in_review'::lp_review_status, 3022),
  ('nb-blues-or-depression', 'article', 'scientific', 'family', 'important', 'guideline', '💜', '{"en":"Baby blues or postpartum depression? How to tell, and how the family can help","bn":"বেবি ব্লুজ নাকি প্রসব-পরবর্তী বিষণ্নতা? কীভাবে বুঝবেন, পরিবার কীভাবে পাশে থাকবে"}'::jsonb, '{"en":"Feeling tearful in the first days is common and passes. Low mood that lasts more than two weeks is an illness that can be treated, and the family''s support is a big part of recovery.","bn":"প্রথম কয়েক দিন কান্না পাওয়া খুব সাধারণ, আর তা কেটে যায়। কিন্তু দুই সপ্তাহের বেশি মন খারাপ থাকলে তা একটা অসুখ, যার চিকিৎসা আছে; আর সেরে ওঠায় পরিবারের সমর্থন বড় ভূমিকা রাখে।"}'::jsonb, '{"en":"## Baby blues\n\nIn the first days after birth, many mothers feel tearful, irritable, anxious or up and down for no clear reason. Hormone changes, pain and lack of sleep all play a part. These baby blues usually begin in the first few days and pass on their own within about two weeks. Rest, kindness and practical help are usually all that is needed.\n\n## Postpartum depression\n\nDepression after birth is different. It lasts longer than two weeks, can start any time in the first year, and makes everyday life hard. A mother may:\n\n- feel sad, empty or hopeless most of the day, most days;\n- lose interest or joy in things, including the baby;\n- feel guilty, worthless, or that she is a bad mother;\n- feel constantly anxious, panicky or irritable;\n- be unable to sleep even when the baby sleeps, or sleep all the time;\n- lose her appetite, or find it hard to concentrate;\n- feel distant from the baby, or have frightening thoughts.\n\nPostpartum depression is a common health condition, not a weakness or a failing, and not something the mother caused. It can be treated with support, talking therapy and, when needed, medicine; many medicines can be used while breastfeeding. The sooner help comes, the faster recovery tends to be.\n\n## An emergency: get help now\n\nRarely, in the first weeks, a mother becomes very confused, sees or hears things that are not there, has strange beliefs, cannot sleep at all, or behaves very differently. This is postpartum psychosis and needs a hospital the same day. Any thoughts of suicide or of harming the baby also need help immediately. Call 999 or go to the nearest hospital, and do not leave her alone.\n\n## How the family can help\n\n- **Listen** without judging or giving quick advice. Saying “I''m here, and you are a good mother” helps more than “Be strong”.\n- **Share the night**: bring the baby to her for feeds and settle the baby afterwards, so she gets one longer stretch of sleep.\n- **Take over the housework** and limit visitors.\n- **Make sure she eats** and gets some daylight and gentle movement.\n- **Go with her** to a health worker if her low mood lasts beyond two weeks.\n- **Do not blame** her, compare her with others, or tell her to hide how she feels.\n\n## Where to get help\n\nTalk to the health worker at a postnatal visit, your community clinic, Upazila Health Complex or district hospital. Mental health services are also available at larger hospitals, including the National Institute of Mental Health in Dhaka.\n\nFathers can also become depressed after a birth. The same signs and the same help apply.","bn":"## বেবি ব্লুজ\n\nপ্রসবের পর প্রথম কয়েক দিন অনেক মায়েরই কোনো স্পষ্ট কারণ ছাড়াই কান্না পায়, মেজাজ খিটখিটে হয়, দুশ্চিন্তা হয়, মন এই ভালো এই খারাপ থাকে। হরমোনের পরিবর্তন, ব্যথা আর ঘুমের অভাব সবই এর পেছনে কাজ করে। একে বলে বেবি ব্লুজ (baby blues); সাধারণত প্রথম কয়েক দিনে শুরু হয়, আর মোটামুটি দুই সপ্তাহের মধ্যে নিজে নিজেই কেটে যায়। বিশ্রাম, ভালো ব্যবহার আর হাতে-কলমে সাহায্যই সাধারণত যথেষ্ট।\n\n## প্রসব-পরবর্তী বিষণ্নতা\n\nপ্রসবের পর বিষণ্নতা (postpartum depression) আলাদা জিনিস। এটা দুই সপ্তাহের বেশি থাকে, প্রথম বছরের যেকোনো সময় শুরু হতে পারে, আর প্রতিদিনের জীবন কঠিন করে তোলে। মায়ের হয়তো:\n\n- বেশিরভাগ দিন, দিনের বেশিরভাগ সময় দুঃখী, ফাঁকা বা আশাহীন লাগে;\n- কোনো কিছুতে, এমনকি শিশুর প্রতিও, আগ্রহ বা আনন্দ থাকে না;\n- নিজেকে দোষী, মূল্যহীন বা খারাপ মা মনে হয়;\n- সবসময় দুশ্চিন্তা, আতঙ্ক বা খিটখিটে ভাব থাকে;\n- শিশু ঘুমালেও ঘুম আসে না, বা সারাক্ষণ ঘুমাতে ইচ্ছা করে;\n- খিদে চলে যায়, বা কোনো কিছুতে মন বসে না;\n- শিশুর থেকে দূরের মনে হয়, বা ভয়ংকর চিন্তা আসে।\n\nপ্রসব-পরবর্তী বিষণ্নতা একটা সাধারণ স্বাস্থ্য সমস্যা; এটা দুর্বলতা বা ব্যর্থতা নয়, আর মা নিজে এর জন্য দায়ী নন। সহায়তা, কথা বলে চিকিৎসা (কাউন্সেলিং) আর দরকার হলে ওষুধে এটা সারে; অনেক ওষুধ বুকের দুধ খাওয়ানোর সময়ও খাওয়া যায়। যত তাড়াতাড়ি সাহায্য মেলে, তত দ্রুত সেরে ওঠা যায়।\n\n## জরুরি অবস্থা: এখনই সাহায্য নিন\n\nখুব কম ক্ষেত্রে, প্রথম কয়েক সপ্তাহে কোনো মা খুব বিভ্রান্ত হয়ে পড়েন, এমন কিছু দেখেন বা শোনেন যা আসলে নেই, অদ্ভুত বিশ্বাস করতে থাকেন, একদমই ঘুমাতে পারেন না, বা একেবারে অন্যরকম আচরণ করেন। একে বলে প্রসব-পরবর্তী সাইকোসিস (postpartum psychosis); সেদিনই হাসপাতালে নিতে হবে। আত্মহত্যার চিন্তা বা শিশুর ক্ষতি করার চিন্তা এলেও সাথে সাথে সাহায্য দরকার। ৯৯৯-এ ফোন করুন বা নিকটস্থ হাসপাতালে যান, আর তাঁকে একা রাখবেন না।\n\n## পরিবার যেভাবে পাশে থাকতে পারে\n\n- **মন দিয়ে শুনুন**, বিচার না করে, চট করে উপদেশ না দিয়ে। “শক্ত হও” বলার চেয়ে “আমি আছি, তুমি একজন ভালো মা” বলা অনেক বেশি কাজে দেয়।\n- **রাতের দায়িত্ব ভাগ করুন**: খাওয়ানোর সময় শিশুকে তাঁর কাছে এনে দিন, পরে আপনি ঘুম পাড়ান, যাতে তিনি একটানা একটু বেশি ঘুমাতে পারেন।\n- **ঘরের কাজ নিজেরা করুন**, অতিথি সীমিত রাখুন।\n- **খেয়াল রাখুন তিনি খাচ্ছেন কিনা**, একটু দিনের আলো আর হালকা হাঁটাচলা পাচ্ছেন কিনা।\n- দুই সপ্তাহের বেশি মন খারাপ থাকলে **সাথে করে** স্বাস্থ্যকর্মীর কাছে নিয়ে যান।\n- **দোষ দেবেন না**, অন্যের সাথে তুলনা করবেন না, অনুভূতি লুকিয়ে রাখতে বলবেন না।\n\n## কোথায় সাহায্য পাবেন\n\nপ্রসব-পরবর্তী চেকআপে স্বাস্থ্যকর্মীকে, কমিউনিটি ক্লিনিক, উপজেলা স্বাস্থ্য কমপ্লেক্স বা জেলা হাসপাতালে বলুন। বড় হাসপাতালগুলোতে মানসিক স্বাস্থ্যসেবা আছে, ঢাকার জাতীয় মানসিক স্বাস্থ্য ইনস্টিটিউটেও।\n\nসন্তান জন্মের পর বাবারাও বিষণ্নতায় ভুগতে পারেন। তাঁদের ক্ষেত্রেও একই লক্ষণ, একই সাহায্য।"}'::jsonb, '{"warning_signs":{"en":["Low mood, hopelessness or no joy for more than two weeks","Not able to sleep even when the baby sleeps, or not eating","Feeling unable to care for herself or the baby","Seeing or hearing things, strange beliefs or very confused behaviour","Thoughts of suicide or of harming the baby"],"bn":["দুই সপ্তাহের বেশি মন খারাপ, আশাহীনতা বা কোনো কিছুতে আনন্দ না পাওয়া","শিশু ঘুমালেও ঘুম না আসা, বা না খাওয়া","নিজের বা শিশুর যত্ন নিতে না পারার অনুভূতি","অদৃশ্য কিছু দেখা বা শোনা, অদ্ভুত বিশ্বাস, বা খুব বিভ্রান্ত আচরণ","আত্মহত্যা বা শিশুর ক্ষতি করার চিন্তা"]},"seek_help":{"en":["Talk to a health worker if low mood lasts more than two weeks","Call 999 or go to hospital now for psychosis, or thoughts of suicide or harming the baby"],"bn":["দুই সপ্তাহের বেশি মন খারাপ থাকলে স্বাস্থ্যকর্মীর সাথে কথা বলুন","সাইকোসিস, বা আত্মহত্যা কিংবা শিশুর ক্ষতির চিন্তা এলে এখনই ৯৯৯-এ ফোন করুন বা হাসপাতালে যান"]}}'::jsonb, 5, 0, 183, '{}'::text[], 'any', ARRAY['baby blues', 'postpartum depression', 'anxiety', 'postpartum psychosis', 'mental health', 'family support']::text[], false, 'in_review'::lp_review_status, 3023),
  ('nb-family-planning-after-birth', 'article', 'scientific', 'shared', 'routine', 'guideline', '🗓️', '{"en":"Family planning after birth: talk to your health worker","bn":"প্রসবের পর পরিবার পরিকল্পনা: স্বাস্থ্যকর্মীর সাথে কথা বলুন"}'::jsonb, '{"en":"You can become pregnant again sooner than many people think. Talking with a health worker early helps you choose what suits your family and your health.","bn":"অনেকে যতটা ভাবেন, তার চেয়ে আগেই আবার গর্ভধারণ হতে পারে। শুরুতেই একজন স্বাস্থ্যকর্মীর সাথে কথা বললে আপনার পরিবার ও স্বাস্থ্যের জন্য কী উপযুক্ত তা বেছে নিতে সুবিধা হয়।"}'::jsonb, '{"en":"## Why think about it now\n\nA woman can become pregnant again before her periods return. If she is not breastfeeding, this can happen within a few weeks of the birth. WHO advises waiting at least two years after a birth before trying for the next pregnancy, because a short gap carries more risk for both mother and baby. Planning helps the mother recover fully and gives the baby her full attention.\n\n## Breastfeeding and pregnancy\n\nBreastfeeding can delay the return of fertility, but it only works as protection when all three of these are true:\n\n- the baby is under six months old;\n- the baby is fed only breast milk, often, day and night;\n- the mother''s periods have not returned.\n\nIf any one of these changes, the protection is gone.\n\n## Talk to a health worker\n\nMany methods are suitable after birth, including while breastfeeding, and some can be started very soon after delivery. Others are better started a little later. Tell the health worker that you are breastfeeding and whether you had any health problems in pregnancy, so they can suggest what suits you.\n\nIn Bangladesh, you can get advice and free or low-cost services from family welfare assistants who visit homes, your Union health and family welfare centre, community clinics, Upazila Health Complexes and hospitals. The 6-week postnatal check is a good time to ask.\n\n## A shared decision\n\nThe timing of the next child is something for the couple to discuss together, with respect for the mother''s health and wishes. The father shares this responsibility, and can go with her to the health worker to ask questions together. Questions about religious views can be taken to a trusted scholar; questions about methods and safety, to a health worker.","bn":"## এখনই কেন ভাববেন\n\nমাসিক ফিরে আসার আগেই একজন নারী আবার গর্ভবতী হতে পারেন। বুকের দুধ না খাওয়ালে প্রসবের কয়েক সপ্তাহের মধ্যেই তা হতে পারে। বিশ্ব স্বাস্থ্য সংস্থা একটা সন্তান জন্মের পর পরের গর্ভধারণের আগে অন্তত দুই বছর অপেক্ষা করার পরামর্শ দেয়, কারণ ব্যবধান কম হলে মা ও শিশু দুজনেরই ঝুঁকি বাড়ে। পরিকল্পনা থাকলে মা পুরোপুরি সেরে উঠতে পারেন, আর শিশুও মায়ের পূর্ণ মনোযোগ পায়।\n\n## বুকের দুধ খাওয়ানো ও গর্ভধারণ\n\nবুকের দুধ খাওয়ালে উর্বরতা ফিরতে দেরি হতে পারে, কিন্তু সুরক্ষা হিসেবে তা কাজ করে কেবল তখনই, যখন এই তিনটি একসাথে সত্যি:\n\n- শিশুর বয়স ছয় মাসের কম;\n- শিশু শুধুই বুকের দুধ খায়, ঘন ঘন, দিনে-রাতে;\n- মায়ের মাসিক এখনো ফিরে আসেনি।\n\nএর যেকোনো একটা বদলালেই সুরক্ষা আর থাকে না।\n\n## স্বাস্থ্যকর্মীর সাথে কথা বলুন\n\nপ্রসবের পর, বুকের দুধ খাওয়ানোর সময়ও, অনেক পদ্ধতি ব্যবহার করা যায়; কিছু প্রসবের পরপরই শুরু করা যায়, কিছু একটু পরে শুরু করা ভালো। আপনি বুকের দুধ খাওয়াচ্ছেন কিনা, আর গর্ভাবস্থায় কোনো স্বাস্থ্য সমস্যা ছিল কিনা, স্বাস্থ্যকর্মীকে জানান, যাতে তিনি আপনার উপযোগী পদ্ধতির কথা বলতে পারেন।\n\nবাংলাদেশে বাড়ি বাড়ি আসা পরিবার কল্যাণ সহকারী, ইউনিয়ন স্বাস্থ্য ও পরিবার কল্যাণ কেন্দ্র, কমিউনিটি ক্লিনিক, উপজেলা স্বাস্থ্য কমপ্লেক্স ও হাসপাতাল থেকে পরামর্শ আর বিনামূল্যে বা কম খরচে সেবা পাওয়া যায়। ছয় সপ্তাহের চেকআপ জিজ্ঞেস করার ভালো সময়।\n\n## একসাথে সিদ্ধান্ত\n\nপরের সন্তান কবে, তা স্বামী-স্ত্রী দুজনে মিলে আলোচনা করার বিষয়, মায়ের স্বাস্থ্য ও ইচ্ছাকে সম্মান করে। এই দায়িত্ব বাবারও; তিনি মায়ের সাথে স্বাস্থ্যকর্মীর কাছে গিয়ে একসাথে প্রশ্ন করতে পারেন। ধর্মীয় দৃষ্টিভঙ্গি নিয়ে প্রশ্ন থাকলে একজন বিশ্বস্ত আলেমকে, আর পদ্ধতি ও নিরাপত্তা নিয়ে প্রশ্ন থাকলে স্বাস্থ্যকর্মীকে জিজ্ঞেস করুন।"}'::jsonb, '{}'::jsonb, 3, 0, 183, '{}'::text[], 'any', ARRAY['family planning', 'contraception', 'birth spacing', 'breastfeeding', 'lam']::text[], false, 'in_review'::lp_review_status, 3024),
  ('nb-bangladeshi-newborn-customs', 'article', 'cultural', 'family', 'important', 'tradition', '🏡', '{"en":"Bangladeshi newborn customs: what helps, what is harmless, what to avoid","bn":"নবজাতককে ঘিরে আমাদের রীতিনীতি: কোনটা উপকারী, কোনটা নিরীহ, কোনটা এড়াবেন"}'::jsonb, '{"en":"Many family customs around a new baby come from love and long experience. Some are wise, some are harmless, and a few can hurt a baby. Here is a gentle guide.","bn":"নতুন শিশুকে ঘিরে পরিবারের অনেক রীতি আসে ভালোবাসা আর দীর্ঘ অভিজ্ঞতা থেকে। কিছু রীতি সত্যিই উপকারী, কিছু নিরীহ, আর অল্প কয়েকটি শিশুর ক্ষতি করতে পারে। এখানে সহজ করে বলা হলো।"}'::jsonb, '{"en":"## The 40 days at home\n\nMany families keep mother and baby mostly at home for about forty days, with relatives helping.\n\n- **What helps**: rest, good food, help with housework, and keeping the baby away from crowds and sick visitors.\n- **What to watch**: staying home should not mean missing the postnatal check-ups or the baby''s 6-week vaccines. The mother also needs a varied diet; avoiding fish, eggs, vegetables or water is not needed and can slow her recovery. A fire, coal or smoke in a closed room is harmful to both; use warm clothing and skin-to-skin instead.\n\n## Oil massage\n\nGentle massage is a lovely way to bond. Some research suggests mustard oil may be harsh on a newborn''s thin skin, and some doctors suggest a mild plant oil or no oil at all; ask your health worker. Keep oil away from the cord, eyes, nose and ears. A little morning sun with the baby warm is fine, but do not leave a baby lying in the sun for long; it can burn or overheat them, and it does not treat jaundice.\n\n## Kajal or surma\n\nKajal and surma are often put on babies'' eyes or as a dot to ward off the evil eye. Kajal in or near the eyes can cause eye infections, and many kajal and surma products have been found to contain lead, which is harmful to a baby''s brain. It is safest to avoid them on babies.\n\n## Oil in the nose or ears\n\nDropping oil into a baby''s nose or ears is meant to protect them, but oil in the nose can be breathed into the lungs, and oil in the ears can lead to infection. Put nothing in a baby''s nose or ears unless a doctor advises it.\n\n## Honey, sugar water and first feeds\n\nGiving honey, misri water, ghutti or animal milk before breast milk, and throwing away the first yellow milk, are still common. Colostrum is the best first food. Honey can cause a serious illness (infant botulism) in babies under one year. Anything else in the first six months raises the risk of infection.\n\n## Black thread or amulet\n\nA thread, bracelet or amulet is a family''s way of wishing a baby protection. For safety: nothing around the neck, as it can strangle; anything on the wrist, ankle or waist should be loose enough to slip a finger under; check the skin under it daily; and make sure nothing small can come off and be swallowed.\n\n## Timing of the first bath\n\nBathing a baby straight after birth makes them cold. Wait at least 24 hours; until then, simply wipe away blood. After that, a short, warm bath in a warm room is fine, and there is no need to wait for many days.\n\n## Talking with elders\n\nGrandparents want the best for the baby. Thank them, explain the health worker''s advice, and keep the customs that are safe together.","bn":"## ঘরে থাকার চল্লিশ দিন\n\nঅনেক পরিবারে প্রসবের পর মোটামুটি চল্লিশ দিন মা ও শিশু বেশিরভাগ সময় ঘরেই থাকেন, আর আত্মীয়রা রান্না, ঘরের কাজ ও যত্নের ভার নেন।\n\n- **যা উপকারী**: বিশ্রাম, ভালো খাবার, ঘরের কাজে সাহায্য, আর শিশুকে ভিড় ও অসুস্থ অতিথি থেকে দূরে রাখা, এসবই মায়ের সেরে ওঠা ও শিশুর জন্য ভালো।\n- **যা খেয়াল রাখবেন**: ঘরে থাকা মানে যেন প্রসব-পরবর্তী চেকআপ বা শিশুর ছয় সপ্তাহের টিকা বাদ না পড়ে। মায়ের নানা রকম খাবারও দরকার; মাছ, ডিম, শাকসবজি বা পানি বাদ দেওয়ার কোনো প্রয়োজন নেই, বরং এতে সেরে উঠতে দেরি হতে পারে। ঘর গরম রাখতে বন্ধ ঘরে আগুন, কয়লা বা ধোঁয়া রাখা মা ও শিশু দুজনের জন্যই ক্ষতিকর; বরং গরম কাপড় আর শিশুকে বুকে জড়িয়ে রেখে উষ্ণ রাখুন।\n\n## তেল মালিশ\n\nআলতো মালিশ শিশুর সাথে বন্ধন গড়ার সুন্দর একটা উপায়, আর অনেক শিশু এটা উপভোগ করে। কিছু গবেষণা বলছে, নবজাতকের পাতলা ত্বকের জন্য সরিষার তেল কড়া হতে পারে; কোনো কোনো ডাক্তার হালকা উদ্ভিজ্জ তেল বা একদম তেল ছাড়াই মালিশের কথা বলেন; আপনার স্বাস্থ্যকর্মীকে জিজ্ঞেস করুন। নাভি, চোখ, নাক ও কান থেকে তেল দূরে রাখুন। শিশুকে গরম রেখে সকালের হালকা রোদে একটু রাখা চলে, কিন্তু অনেকক্ষণ রোদে শুইয়ে রাখবেন না; ত্বক পুড়তে বা শরীর বেশি গরম হতে পারে, আর এতে জন্ডিসও সারে না।\n\n## কাজল বা সুরমা\n\nনজর না লাগার জন্য প্রায়ই শিশুর চোখে কাজল বা সুরমা, বা কপালে কালো টিপ দেওয়া হয়। চোখে বা চোখের কাছে কাজল দিলে চোখে সংক্রমণ হতে পারে, আর অনেক কাজল ও সুরমায় সিসা পাওয়া গেছে, যা শিশুর মস্তিষ্কের ক্ষতি করে। শিশুর ক্ষেত্রে এগুলো এড়িয়ে চলাই সবচেয়ে নিরাপদ।\n\n## নাকে বা কানে তেল\n\nসুরক্ষার জন্য শিশুর নাকে বা কানে তেল দেওয়া হয়, কিন্তু নাকের তেল শ্বাসের সাথে ফুসফুসে চলে যেতে পারে, আর কানের তেলে সংক্রমণ হতে পারে। ডাক্তার না বললে শিশুর নাকে বা কানে কিছুই দেবেন না।\n\n## মধু, চিনির পানি ও প্রথম খাবার\n\nবুকের দুধের আগে বা বদলে মধু, চিনি বা মিছরির পানি, ঘুট্টি, সরিষার তেল বা পশুর দুধ দেওয়া, আর প্রথম হলুদ দুধ ফেলে দেওয়া, এখনো অনেক জায়গায় চলে। অথচ শালদুধই শিশুর সেরা প্রথম খাবার। এক বছরের কম বয়সী শিশুর মধু খেলে বটুলিজম নামে মারাত্মক অসুখ হতে পারে। প্রথম ছয় মাসে বুকের দুধ ছাড়া যেকোনো কিছু দিলে সংক্রমণের ঝুঁকি বাড়ে, আর শিশু দুধও কম পায়।\n\n## কালো সুতা বা তাবিজ\n\nসুতা, বালা বা তাবিজ পরানো শিশুর সুরক্ষার জন্য পরিবারের শুভকামনা। নিরাপত্তার জন্য: গলায় কিছু নয়, এতে ফাঁস লাগতে পারে; হাতে, পায়ে বা কোমরে যা পরাবেন তা এতটা ঢিলা রাখুন যেন নিচে একটা আঙুল ঢোকে; প্রতিদিন নিচের ত্বক দেখুন; আর খেয়াল রাখুন ছোট কিছু খুলে গিয়ে শিশু যেন গিলে না ফেলে।\n\n## প্রথম গোসলের সময়\n\nজন্মের পরপরই গোসল করালে শিশুর ঠান্ডা লেগে যায়। অন্তত ২৪ ঘণ্টা অপেক্ষা করুন; ততক্ষণ শুধু রক্ত মুছে দিন। এরপর গরম ঘরে কুসুম গরম পানিতে অল্প সময়ের গোসল চলবে, অনেক দিন অপেক্ষা করার দরকার নেই।\n\n## মুরুব্বিদের সাথে কথা\n\nনানি-দাদিরা সাধারণত শিশুর ভালোটাই চান। তাঁদের যত্নের জন্য ধন্যবাদ দিন, স্বাস্থ্যকর্মী কী বলেছেন বুঝিয়ে বলুন, আর একসাথে মিলে কোন রীতিগুলো নিরাপদে রাখা যায় খুঁজে নিন।"}'::jsonb, '{"avoid":{"en":["Honey, sugar water, ghutti or other feeds before or instead of breast milk","Throwing away colostrum","Kajal or surma on or near the baby''s eyes","Oil in the nose or ears","Anything tied around the neck","Fire, coal or smoke in a closed room","Bathing the baby straight after birth"],"bn":["বুকের দুধের আগে বা বদলে মধু, চিনির পানি, ঘুট্টি বা অন্য কিছু","শালদুধ ফেলে দেওয়া","শিশুর চোখে বা চোখের কাছে কাজল বা সুরমা","নাকে বা কানে তেল","গলায় কিছু বাঁধা","বন্ধ ঘরে আগুন, কয়লা বা ধোঁয়া","জন্মের পরপরই গোসল করানো"]}}'::jsonb, 5, 0, 91, '{}'::text[], 'any', ARRAY['culture', 'tradition', 'forty days', 'mustard oil', 'kajal', 'surma', 'honey', 'amulet', 'prelacteal']::text[], false, 'in_review'::lp_review_status, 3025),
  ('nb-activity-tummy-play', 'activity', 'scientific', 'shared', 'routine', 'guideline', '🐢', '{"en":"Tummy-time play: face to face","bn":"উপুড় হয়ে খেলা: মুখোমুখি"}'::jsonb, '{"en":"A few minutes of playful tummy time, several times a day, with your face as the best toy.","bn":"দিনে কয়েকবার, কয়েক মিনিট করে মজার ছলে উপুড় হয়ে খেলা; আর সেরা খেলনা আপনার মুখ।"}'::jsonb, '{}'::jsonb, '{"why":{"en":"Babies need time on their tummies while awake to build neck, shoulder and back strength and to prevent a flat head. Making it a game, with you close by, helps your baby enjoy it. WHO advises at least 30 minutes a day in total for babies who are not yet crawling, built up slowly.","bn":"জেগে থাকার সময় উপুড় হয়ে থাকলে শিশুর ঘাড়, কাঁধ ও পিঠে জোর আসে, মাথার পেছন চ্যাপ্টা হয় না। আপনি কাছে থেকে খেলার মতো করে করলে শিশু এটা উপভোগ করে। যে শিশু এখনো হামাগুড়ি দেয় না, তার জন্য বিশ্ব স্বাস্থ্য সংস্থা দিনে মোট অন্তত ৩০ মিনিট উপুড় হয়ে থাকার পরামর্শ দেয়, ধীরে ধীরে বাড়িয়ে।"},"items":{"en":["A clean mat or sheet on the floor","A small rolled towel (optional)","A colourful cloth, rattle or unbreakable mirror","Your face and voice"],"bn":["মেঝেতে পরিষ্কার মাদুর বা চাদর","ছোট করে পাকানো একটা তোয়ালে (চাইলে)","রঙিন কাপড়, ঝুনঝুনি বা না-ভাঙা আয়না","আপনার মুখ আর কণ্ঠ"]},"steps":{"en":["Pick a time when the baby is awake and content, not right after a feed","In the first weeks, lie back and place the baby tummy-down on your chest, face to face","Later, place the baby on the mat and lie down in front at eye level","Talk, smile, sing, or slowly move a colourful cloth so the baby lifts the head to look","Try a rolled towel under the chest if the baby struggles to lift up","Stop when the baby fusses, and try again later; build from 1–2 minutes towards longer sessions","If the baby falls asleep, turn them onto their back"],"bn":["শিশু যখন জেগে আর খুশি আছে, খাওয়ার ঠিক পরে নয়, এমন সময় বেছে নিন","প্রথম সপ্তাহগুলোতে হেলান দিয়ে শুয়ে শিশুকে আপনার বুকের ওপর উপুড় করে মুখোমুখি রাখুন","পরে শিশুকে মাদুরে রেখে তার সামনে চোখের সমান হয়ে শুয়ে পড়ুন","কথা বলুন, হাসুন, গান করুন, বা রঙিন কাপড় ধীরে নাড়ান, যাতে শিশু মাথা তুলে দেখে","শিশু মাথা তুলতে কষ্ট পেলে বুকের নিচে পাকানো তোয়ালে দিয়ে দেখুন","শিশু বিরক্ত হলে থামুন, পরে আবার চেষ্টা করুন; ১–২ মিনিট থেকে শুরু করে ধীরে ধীরে সময় বাড়ান","শিশু ঘুমিয়ে পড়লে চিত করে দিন"]},"avoid":{"en":["Leaving the baby alone on the tummy, even for a moment","Tummy time on a high bed or soft surface"],"bn":["উপুড় অবস্থায় শিশুকে এক মুহূর্তের জন্যও একা রাখা","উঁচু খাট বা নরম বিছানায় উপুড় করে রাখা"]}}'::jsonb, 2, 0, 183, '{}'::text[], 'any', ARRAY['tummy time', 'play', 'neck strength', 'activity', 'mirror']::text[], false, 'in_review'::lp_review_status, 3026),
  ('nb-activity-baby-massage', 'activity', 'general', 'shared', 'routine', 'consensus', '👐', '{"en":"Gentle baby massage","bn":"শিশুর আলতো মালিশ"}'::jsonb, '{"en":"Slow, gentle strokes in a warm room: a calm time for touch, eye contact and talking, for mothers and fathers alike.","bn":"গরম ঘরে ধীরে, আলতো হাতে মালিশ: ছোঁয়া, চোখে চোখ রাখা আর কথা বলার শান্ত একটা সময়, মা ও বাবা দুজনের জন্যই।"}'::jsonb, '{}'::jsonb, '{"why":{"en":"Gentle touch helps babies relax and gives parents a calm, close time with them. Massage is a much-loved tradition in Bangladeshi families. The goal is comfort and connection, not rubbing hard; how gently you touch matters more than the oil you use.","bn":"আলতো ছোঁয়ায় শিশু আরাম পায়, আর মা-বাবাও তার সাথে শান্ত, কাছের একটা সময় কাটাতে পারেন। মালিশ বাংলাদেশের পরিবারগুলোর খুব প্রিয় একটা রীতি। উদ্দেশ্য আরাম আর বন্ধন, জোরে ঘষা নয়; কোন তেল ব্যবহার করছেন তার চেয়ে কতটা আলতো করে ছুঁচ্ছেন সেটাই বেশি গুরুত্বপূর্ণ।"},"items":{"en":["A warm room with no draughts","A soft towel or sheet","A little mild plant oil if you wish (ask your health worker which), or no oil","Clean hands, short nails, rings removed"],"bn":["বাতাস ঢোকে না এমন গরম ঘর","নরম তোয়ালে বা চাদর","চাইলে সামান্য হালকা উদ্ভিজ্জ তেল (কোনটা, স্বাস্থ্যকর্মীকে জিজ্ঞেস করুন), বা তেল ছাড়াই","পরিষ্কার হাত, ছোট নখ, আংটি খুলে রাখা"]},"steps":{"en":["Choose a time when the baby is awake and calm, not hungry and not just fed","Lay the baby on the towel, look into their eyes and talk softly","Warm a few drops of oil between your palms if you use it","Stroke the legs from thigh to foot, then gently rub the soles","Stroke the arms from shoulder to hand, and open the little fingers","Stroke the chest outwards from the middle; touch the tummy only gently, and avoid the cord until it has healed","Turn the baby onto the tummy and stroke the back from neck to bottom","Stroke the face with fingertips only, without oil","Stop if the baby cries or turns away; 5 to 15 minutes is plenty","Dress the baby warmly afterwards"],"bn":["শিশু যখন জেগে ও শান্ত, ক্ষুধার্ত নয় আর সবে খায়নি, এমন সময় বেছে নিন","শিশুকে তোয়ালের ওপর শুইয়ে চোখে চোখ রেখে নরম স্বরে কথা বলুন","তেল ব্যবহার করলে কয়েক ফোঁটা দুই হাতের তালুতে ঘষে গরম করে নিন","উরু থেকে পায়ের পাতা পর্যন্ত আলতো টানুন, তারপর পায়ের তলা আলতো ঘষুন","কাঁধ থেকে হাত পর্যন্ত টানুন, ছোট্ট আঙুলগুলো আলতো খুলে দিন","বুকের মাঝখান থেকে দুই দিকে টানুন; পেটে খুব আলতো হাত দিন, আর নাভি না শুকানো পর্যন্ত নাভি এড়িয়ে চলুন","শিশুকে উপুড় করে ঘাড় থেকে নিতম্ব পর্যন্ত পিঠে হাত বুলান","মুখে শুধু আঙুলের ডগা দিয়ে, তেল ছাড়া হাত বুলান","শিশু কাঁদলে বা মুখ ফিরিয়ে নিলে থামুন; ৫ থেকে ১৫ মিনিটই যথেষ্ট","শেষে শিশুকে গরম কাপড় পরিয়ে দিন"]},"avoid":{"en":["Oil in the eyes, nose, ears or on the cord","Pressing hard, stretching or pulling the limbs","Massaging a baby who is unwell, feverish or has a skin rash","Leaving the baby in the sun for long after massage"],"bn":["চোখে, নাকে, কানে বা নাভিতে তেল","জোরে চাপ দেওয়া, হাত-পা টেনে লম্বা করা","অসুস্থ, জ্বর বা ত্বকে র‍্যাশ থাকা শিশুকে মালিশ করা","মালিশের পর শিশুকে অনেকক্ষণ রোদে রেখে দেওয়া"]}}'::jsonb, 3, 7, 183, '{}'::text[], 'any', ARRAY['massage', 'bonding', 'oil', 'touch', 'father', 'calming']::text[], false, 'in_review'::lp_review_status, 3027),
  ('nb-checklist-newborn-supplies', 'checklist', 'general', 'family', 'routine', 'consensus', '🧺', '{"en":"Newborn care supplies","bn":"নবজাতকের যত্নের জিনিসপত্র"}'::jsonb, '{"en":"A simple list of what you really need for a newborn, and a few things you can skip.","bn":"নবজাতকের জন্য সত্যিই যা দরকার তার সহজ তালিকা, আর কয়েকটা জিনিস যা না হলেও চলে।"}'::jsonb, '{"en":"Babies need very little: warmth, breast milk, a safe place to sleep and loving care. Use this list to get ready, ideally before the birth. You do not need feeding bottles, formula, talcum powder, pillows or kajal; it is better not to keep them.","bn":"শিশুর খুব বেশি কিছু লাগে না: উষ্ণতা, বুকের দুধ, ঘুমানোর নিরাপদ জায়গা আর ভালোবাসার যত্ন। পারলে প্রসবের আগেই এই তালিকা ধরে গুছিয়ে নিন। ফিডার, ফর্মুলা, ট্যালকম পাউডার, বালিশ বা কাজলের দরকার নেই; এগুলো না রাখাই ভালো।"}'::jsonb, '{"items":{"en":["Soft cotton clothes, washed before use, enough to change several times a day","Caps and socks for the first days and cool weather","Cloth nappies or kanthas, or disposable nappies","Soft cotton cloths for cleaning and burping","Two soft towels","A light blanket or wrap for warmth and kangaroo care","A firm, flat sleep space with a fitted sheet, and no pillows","A mosquito net","A small basin and mild, unscented baby soap","A digital thermometer","Baby nail clippers or a soft file","Clean pads or cloths and comfortable front-opening clothes for the mother","A clean cup and spoon with a lid, in case you need to give expressed milk","Soap at the handwashing place","A folder for the vaccine card, health card and birth papers","Phone numbers of your health worker and nearest hospital, and a plan for transport day and night"],"bn":["নরম সুতির জামা, পরানোর আগে ধুয়ে নেওয়া, দিনে কয়েকবার বদলানোর মতো যথেষ্ট","প্রথম কয়েক দিন ও ঠান্ডার জন্য টুপি ও মোজা","কাপড়ের ন্যাপি বা কাঁথা, অথবা ডিসপোজেবল ন্যাপি","পরিষ্কার করা ও ঢেকুর তোলানোর জন্য নরম সুতির কাপড়","দুটো নরম তোয়ালে","উষ্ণতা ও ক্যাঙ্গারু পদ্ধতির জন্য হালকা চাদর বা ওড়না","ঘুমের জন্য শক্ত, সমান জায়গা, টানটান চাদরসহ, বালিশ ছাড়া","মশারি","ছোট গামলা আর হালকা, সুগন্ধিহীন বেবি সাবান","ডিজিটাল থার্মোমিটার","শিশুর নখ কাটার বা নরম নেইল ফাইল","মায়ের জন্য পরিষ্কার প্যাড বা কাপড়, আর সামনে খোলা আরামদায়ক জামা","বের করা দুধ খাওয়ানোর দরকার হলে ঢাকনাসহ পরিষ্কার কাপ ও চামচ","হাত ধোয়ার জায়গায় সাবান","টিকা কার্ড, স্বাস্থ্য কার্ড ও জন্মের কাগজ রাখার ফোল্ডার","স্বাস্থ্যকর্মী ও নিকটস্থ হাসপাতালের ফোন নম্বর, আর দিন-রাত যাতায়াতের পরিকল্পনা"]}}'::jsonb, 2, -84, 42, '{}'::text[], 'any', ARRAY['checklist', 'supplies', 'newborn', 'nappies', 'clothes', 'preparation']::text[], false, 'in_review'::lp_review_status, 3028),
  ('nb-checklist-first-6-weeks', 'checklist', 'scientific', 'shared', 'important', 'guideline', '✅', '{"en":"The first 6 weeks: check-ups and vaccines","bn":"প্রথম ৬ সপ্তাহ: চেকআপ ও টিকা"}'::jsonb, '{"en":"Tick these off one by one to make sure mother and baby get every check and vaccine on time.","bn":"একটা একটা করে টিক দিন, যাতে মা ও শিশু সব চেকআপ আর টিকা সময়মতো পায়।"}'::jsonb, '{"en":"WHO advises at least four postnatal contacts for mother and baby in the first six weeks, and Bangladesh''s EPI gives the first vaccines at birth and at 6 weeks. Exact dates may differ a little; follow your health worker and the dates on your cards.","bn":"বিশ্ব স্বাস্থ্য সংস্থা প্রথম ছয় সপ্তাহে মা ও শিশুর জন্য অন্তত চারবার প্রসব-পরবর্তী সেবার পরামর্শ দেয়, আর বাংলাদেশের ইপিআই জন্মের পর ও ৬ সপ্তাহে প্রথম টিকাগুলো দেয়। তারিখ একটু এদিক-ওদিক হতে পারে; স্বাস্থ্যকর্মীর পরামর্শ আর কার্ডের তারিখ মেনে চলুন।"}'::jsonb, '{"items":{"en":["Birth: skin-to-skin and breastfeeding in the first hour","Birth: vitamin K and cord care given; ask and note it","Birth or first visit: BCG vaccine","Within 24 hours: first check for mother and baby","Around day 3: second check (feeding, jaundice, cord, mother''s bleeding and blood pressure)","Days 7 to 14: third check","By about 2 weeks: baby back to birth weight","Birth registration started","Everyone at home knows the newborn danger signs and the mother''s danger signs","About 6 weeks: check-up for the mother (blood pressure, healing, mood, family planning)","6 weeks: baby''s Penta 1, OPV 1, PCV 1 and fIPV 1, plus weight check","Dates for the 10-week and 14-week vaccines written down"],"bn":["জন্মের সময়: প্রথম ঘণ্টায় ত্বকের ছোঁয়া ও বুকের দুধ","জন্মের সময়: ভিটামিন কে ও নাভির যত্ন দেওয়া হয়েছে কিনা জিজ্ঞেস করে লিখে রাখুন","জন্মের পর বা প্রথম দেখাতে: বিসিজি টিকা","২৪ ঘণ্টার মধ্যে: মা ও শিশুর প্রথম চেকআপ","তৃতীয় দিনের কাছাকাছি: দ্বিতীয় চেকআপ (খাওয়ানো, জন্ডিস, নাভি, মায়ের রক্তস্রাব ও রক্তচাপ)","৭ থেকে ১৪ দিনে: তৃতীয় চেকআপ","প্রায় ২ সপ্তাহের মধ্যে: শিশু জন্মের ওজনে ফিরেছে","জন্ম নিবন্ধন শুরু হয়েছে","বাড়ির সবাই নবজাতকের ও মায়ের বিপদচিহ্নগুলো জানেন","প্রায় ৬ সপ্তাহে: মায়ের চেকআপ (রক্তচাপ, সেরে ওঠা, মন, পরিবার পরিকল্পনা)","৬ সপ্তাহে: শিশুর পেন্টা-১, ওপিভি-১, পিসিভি-১ ও এফআইপিভি-১, সাথে ওজন মাপা","১০ ও ১৪ সপ্তাহের টিকার তারিখ লিখে রাখা হয়েছে"]}}'::jsonb, 2, 0, 56, '{}'::text[], 'any', ARRAY['checklist', 'postnatal check', 'vaccines', 'six weeks', 'birth registration']::text[], false, 'in_review'::lp_review_status, 3029),
  ('nb-baby-cries-a-lot', 'scenario', 'scientific', 'shared', 'important', 'consensus', '😢', '{"en":"My baby cries a lot. Is it colic?","bn":"শিশু অনেক কাঁদে। এটা কি কলিক?"}'::jsonb, '{"en":"All babies cry, and some cry for hours, often in the evening. Check the simple causes, soothe, and know the signs that mean illness.","bn":"সব শিশুই কাঁদে, কেউ কেউ ঘণ্টার পর ঘণ্টা, প্রায়ই সন্ধ্যায়। সহজ কারণগুলো দেখুন, শান্ত করুন, আর অসুখের লক্ষণগুলো জেনে রাখুন।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"Crying is how a baby tells you something: hunger, tiredness, a wet nappy, being too hot or cold, wind, or simply wanting to be held. Some healthy babies cry for long periods, often in the late afternoon or evening, and cannot be easily calmed. When this happens for more than three hours a day, several days a week, in a baby who is otherwise well, it is often called colic.","bn":"কান্নাই শিশুর কথা বলার উপায়: খিদে, ক্লান্তি, ভেজা ন্যাপি, বেশি গরম বা ঠান্ডা, পেটে বাতাস, কিংবা শুধু কোলে ওঠার ইচ্ছা। কিছু সুস্থ শিশু অনেকক্ষণ ধরে কাঁদে, প্রায়ই বিকেল বা সন্ধ্যায়, আর সহজে শান্ত হয় না। অন্যভাবে সুস্থ শিশু যদি সপ্তাহে কয়েক দিন, দিনে তিন ঘণ্টার বেশি এভাবে কাঁদে, তাকে সাধারণত কলিক (colic) বলা হয়।"},"why":{"en":"The exact cause of colic is not known. It is not caused by anything the parents did, and it is not a sign of not enough breast milk. It usually starts in the first few weeks, is worst around six weeks, and gets better by three to four months.","bn":"কলিকের সঠিক কারণ জানা নেই। মা-বাবার কোনো ভুলে এটা হয় না, আর এটা বুকের দুধ কম হওয়ার লক্ষণও নয়। সাধারণত প্রথম কয়েক সপ্তাহে শুরু হয়, ছয় সপ্তাহের দিকে সবচেয়ে বেশি থাকে, আর তিন-চার মাসের মধ্যে কমে আসে।"},"normal":{"en":"It is normal for a young baby to cry for a total of one to three hours a day, more in the evening, as long as they feed well, have wet nappies, and are calm and alert at other times.","bn":"শিশু ঠিকমতো খেলে, ন্যাপি ভিজলে, আর অন্য সময় শান্ত ও সজাগ থাকলে দিনে মোট এক থেকে তিন ঘণ্টা কাঁদা, বিশেষ করে সন্ধ্যায়, ছোট শিশুর জন্য স্বাভাবিক।"},"do_now":{"en":["Offer the breast; hunger is the most common cause","Check the nappy, and whether the baby is too hot or too cold","Hold the baby upright to bring up wind","Hold the baby skin-to-skin, walk, rock gently and make a steady shushing sound"],"bn":["স্তন দিন; খিদেই সবচেয়ে সাধারণ কারণ","ন্যাপি দেখুন, আর শিশুর বেশি গরম বা ঠান্ডা লাগছে কিনা","শিশুকে সোজা করে ধরে ঢেকুর তোলান","খালি বুকে জড়িয়ে হাঁটুন, আলতো দোলান, আর একটানা শ-শ-শ শব্দ করুন"]},"steps":{"en":["Keep the room calm and dim in the evening","Try a warm bath or a gentle tummy rub, or carry the baby close in a cloth wrap","Take turns: the father or another adult can hold the baby while the mother rests","If you feel angry or overwhelmed, put the baby down safely on their back and step away for a few minutes","Keep a note of crying times, feeds and stools to show the health worker"],"bn":["সন্ধ্যায় ঘর শান্ত ও আলো কম রাখুন","কুসুম গরম পানিতে গোসল, পেটে আলতো হাত বুলানো, বা কাপড়ে জড়িয়ে বুকের কাছে নিয়ে হাঁটা চেষ্টা করুন","পালা করে নিন: মা বিশ্রাম নেওয়ার সময় বাবা বা বাড়ির অন্য কেউ শিশুকে কোলে নিন","রাগ বা অসহায় লাগলে শিশুকে নিরাপদে চিত করে শুইয়ে কয়েক মিনিটের জন্য সরে যান","কখন কাঁদে, কখন খায়, কখন পায়খানা করে লিখে রাখুন, স্বাস্থ্যকর্মীকে দেখানোর জন্য"]},"avoid":{"en":["Never shake a baby; it can cause serious brain injury or death","Gripe water, ghutti, herbal mixtures or medicines that a doctor did not prescribe","Water, honey or formula to stop crying","Blaming the mother or her milk"],"bn":["কখনো শিশুকে ঝাঁকাবেন না; এতে মস্তিষ্কে মারাত্মক আঘাত বা মৃত্যু হতে পারে","ডাক্তারের দেওয়া নয় এমন গ্রাইপ ওয়াটার, ঘুট্টি, ভেষজ মিশ্রণ বা ওষুধ","কান্না থামাতে পানি, মধু বা ফর্মুলা","মাকে বা তাঁর দুধকে দোষ দেওয়া"]},"example":{"en":"Every evening at seven, five-week-old Ayaan cried for hours. His grandmother wanted to give gripe water. His father, Tanvir, said, “The doctor checked him and he is gaining well. Let me walk with him so you can both rest.” He carried Ayaan skin-to-skin around the room, humming, and by ten weeks the evening crying had eased.","bn":"প্রতিদিন সন্ধ্যা সাতটায় পাঁচ সপ্তাহের আয়ান ঘণ্টার পর ঘণ্টা কাঁদত। দাদি গ্রাইপ ওয়াটার দিতে চাইলেন। বাবা তানভীর বললেন, “ডাক্তার দেখেছেন, ওজনও ঠিক বাড়ছে। আমি ওকে নিয়ে একটু হাঁটি, তোমরা দুজন বিশ্রাম নাও।” তিনি আয়ানকে খালি বুকে জড়িয়ে গুনগুন করতে করতে ঘরে হাঁটতেন। দশ সপ্তাহের মধ্যে সন্ধ্যার কান্না অনেকটা কমে এলো।"},"warning_signs":{"en":["A high-pitched, weak or very different cry","Fever, or the baby feels cold","Not feeding, or vomiting green or vomiting everything","Blood in the stool, or a swollen, hard belly","Fast or difficult breathing, fits, or a floppy, very sleepy baby"],"bn":["তীক্ষ্ণ, দুর্বল বা একদম অন্যরকম কান্না","জ্বর, বা শিশুর গা ঠান্ডা","খাচ্ছে না, বা সবুজ বমি, বা যা খায় সব বমি","পায়খানায় রক্ত, বা পেট ফুলে শক্ত","দ্রুত বা কষ্ট করে শ্বাস, খিঁচুনি, বা শিশু নেতিয়ে পড়া, খুব ঘুমঘুম"]},"seek_help":{"en":["Go to hospital now for any warning sign","See a health worker if crying is new, getting worse, or you are worried the baby is in pain","Talk to a health worker if you feel you cannot cope"],"bn":["যেকোনো সতর্ক লক্ষণ দেখলে এখনই হাসপাতালে যান","কান্না নতুন হলে, বাড়তে থাকলে, বা শিশু ব্যথায় আছে মনে হলে স্বাস্থ্যকর্মী দেখান","সামলাতে পারছেন না মনে হলে স্বাস্থ্যকর্মীর সাথে কথা বলুন"]}}'::jsonb, 3, 0, 183, '{}'::text[], 'any', ARRAY['crying', 'colic', 'fussy baby', 'soothing', 'shaken baby']::text[], false, 'in_review'::lp_review_status, 3030),
  ('nb-baby-wont-latch', 'scenario', 'scientific', 'mother', 'important', 'guideline', '🤱', '{"en":"My baby won''t latch","bn":"শিশু স্তন মুখে নিচ্ছে না"}'::jsonb, '{"en":"Keep the baby close, keep the milk flowing, and get skilled help early. Most latch problems can be solved.","bn":"শিশুকে কাছে রাখুন, দুধ বের হওয়া চালু রাখুন, আর তাড়াতাড়ি দক্ষ কারও সাহায্য নিন। মুখে নেওয়ার বেশিরভাগ সমস্যারই সমাধান আছে।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"A baby may not latch because they are sleepy after birth, the breast is very full and hard, the nipple is flat, they are small or born early, they have had a bottle, or they have a tight tongue. Sometimes the baby is too upset to latch.","bn":"জন্মের পর ঘুমকাতুরে থাকা, স্তন খুব ভরা ও শক্ত হওয়া, বোঁটা চ্যাপ্টা হওয়া, শিশু ছোট বা সময়ের আগে জন্মানো, ফিডারে খাওয়ার অভ্যাস, বা জিভ নিচে আটকানো, এসব কারণে শিশু মুখে নিতে না পারে। কখনো আবার শিশু এত কাঁদে যে মুখে নিতে পারে না।"},"why":{"en":"A newborn needs regular milk, and the breasts need regular emptying to keep making milk. Acting early protects both the baby and the milk supply.","bn":"নবজাতকের নিয়মিত দুধ দরকার, আর দুধ তৈরি চালু রাখতে স্তনও নিয়মিত খালি হওয়া দরকার। তাড়াতাড়ি ব্যবস্থা নিলে শিশু ও দুধের জোগান দুটোই সুরক্ষিত থাকে।"},"normal":{"en":"In the first day or two many babies are sleepy and latch only briefly. It is also common for latching to take several tries while mother and baby learn.","bn":"প্রথম এক-দুই দিন অনেক শিশু ঘুমকাতুরে থাকে, অল্প সময়ের জন্য মুখে নেয়। মা ও শিশু শিখতে শিখতে কয়েকবার চেষ্টা লাগাও খুব সাধারণ।"},"do_now":{"en":["Hold the baby skin-to-skin and let them search for the breast","Try when the baby shows early hunger cues, not when crying hard","Hand-express a few drops onto the nipple so the baby can smell and taste milk","If the breast is hard, express a little first to soften it"],"bn":["শিশুকে খালি বুকে রাখুন, নিজে স্তন খুঁজতে দিন","জোরে কাঁদার সময় নয়, খিদের শুরুর লক্ষণ দেখলেই চেষ্টা করুন","হাতে কয়েক ফোঁটা দুধ বের করে বোঁটায় লাগান, যাতে শিশু গন্ধ ও স্বাদ পায়","স্তন শক্ত হলে আগে একটু দুধ বের করে নরম করে নিন"]},"steps":{"en":["Try different positions, such as lying back or holding the baby under your arm","Wait for a wide-open mouth, then bring the baby to the breast chin first","If the baby still does not feed, express your milk and give it by cup or spoon, about every 2 to 3 hours","Keep offering the breast at every feed, calmly, without forcing","Ask a health worker to watch a feed and check the baby''s mouth and tongue"],"bn":["বিভিন্ন অবস্থানে চেষ্টা করুন, যেমন হেলান দিয়ে শুয়ে বা শিশুকে বগলের নিচে ধরে","মুখ বড় করে খোলার অপেক্ষা করুন, তারপর থুতনি আগে রেখে শিশুকে স্তনে আনুন","তবু না খেলে দুধ বের করে কাপ বা চামচে খাওয়ান, মোটামুটি প্রতি ২-৩ ঘণ্টায়","প্রতিবার খাওয়ানোর সময় শান্তভাবে স্তন দিন, জোর করবেন না","একজন স্বাস্থ্যকর্মীকে খাওয়ানো দেখতে আর শিশুর মুখ ও জিভ পরীক্ষা করতে বলুন"]},"avoid":{"en":["Pushing the baby''s head onto the breast","Switching to a bottle or formula without a health worker''s advice","Giving water, honey or sugar water while waiting"],"bn":["শিশুর মাথা জোর করে স্তনে চেপে ধরা","স্বাস্থ্যকর্মীর পরামর্শ ছাড়া ফিডার বা ফর্মুলায় চলে যাওয়া","অপেক্ষার সময় পানি, মধু বা চিনির পানি দেওয়া"]},"example":{"en":"On day two, Rumana''s breasts felt hard and her baby kept slipping off. The nurse showed her how to hand-express a little milk to soften the breast and how to hold the baby under her arm. Rumana said, “I thought I had no milk. It was just too full for her to hold.” The next feed went much better.","bn":"দ্বিতীয় দিনে রুমানার স্তন শক্ত হয়ে গেল, আর শিশু বারবার ছুটে যাচ্ছিল। নার্স দেখিয়ে দিলেন কীভাবে হাতে একটু দুধ বের করে স্তন নরম করতে হয়, আর কীভাবে শিশুকে বগলের নিচে ধরতে হয়। রুমানা বললেন, “ভেবেছিলাম আমার দুধই নেই। আসলে স্তন এত ভরা ছিল যে ও ধরতে পারছিল না।” পরের বার খাওয়ানো অনেক ভালো হলো।"},"warning_signs":{"en":["The baby has not fed for many hours or is too sleepy to wake for feeds","Fewer wet nappies than expected, or dark urine","Yellow skin in the first day, or spreading yellow","Fever, feeling cold, fast breathing or fits"],"bn":["শিশু অনেক ঘণ্টা খায়নি, বা খাওয়ার জন্য জাগানো যাচ্ছে না","যতটা হওয়ার কথা তার চেয়ে কম ভেজা ন্যাপি, বা প্রস্রাব গাঢ়","প্রথম দিনেই ত্বক হলুদ, বা হলুদ ভাব ছড়াচ্ছে","জ্বর, গা ঠান্ডা, দ্রুত শ্বাস বা খিঁচুনি"]},"seek_help":{"en":["See a health worker within a day if the baby is not latching","Go to hospital now for any warning sign"],"bn":["শিশু মুখে না নিলে এক দিনের মধ্যে স্বাস্থ্যকর্মী দেখান","যেকোনো সতর্ক লক্ষণে এখনই হাসপাতালে যান"]}}'::jsonb, 3, 0, 91, '{}'::text[], 'any', ARRAY['latch', 'refuses breast', 'sleepy baby', 'engorgement', 'expressing']::text[], false, 'in_review'::lp_review_status, 3031),
  ('nb-not-enough-milk', 'scenario', 'scientific', 'family', 'important', 'guideline', '🍼', '{"en":"“I don''t have enough milk”","bn":"“আমার দুধ যথেষ্ট হচ্ছে না”"}'::jsonb, '{"en":"This is one of the most common worries. Often the milk is enough; check the reliable signs, and if supply is low, more frequent good feeds usually bring it up.","bn":"এটা সবচেয়ে সাধারণ দুশ্চিন্তাগুলোর একটা। প্রায়ই দুধ আসলে যথেষ্টই থাকে; নির্ভরযোগ্য লক্ষণগুলো দেখুন, আর দুধ কম হলে ঘন ঘন ঠিকমতো খাওয়ালে সাধারণত বেড়ে যায়।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"Many mothers feel their milk is not enough because the baby feeds often, cries, or the breasts feel soft. These are usually normal. True low supply is less common and usually has a cause, such as infrequent feeds, a poor latch, or giving other drinks or formula.","bn":"শিশু ঘন ঘন খেতে চায়, কাঁদে, বা স্তন নরম লাগে বলে অনেক মা ভাবেন দুধ কম হচ্ছে। এগুলো সাধারণত স্বাভাবিক। সত্যিকারের দুধ কম হওয়া তুলনায় কম ঘটে, আর সাধারণত এর কোনো কারণ থাকে, যেমন কম কম খাওয়ানো, ঠিকমতো মুখে না নেওয়া, বা অন্য পানীয় বা ফর্মুলা দেওয়া।"},"why":{"en":"The breasts make milk in response to milk being removed. The more often and the better the baby feeds, the more milk is made. Anything that replaces breastfeeds lowers the supply.","bn":"স্তন থেকে দুধ বের হলেই নতুন দুধ তৈরি হয়। শিশু যত ঘন ঘন আর যত ভালোভাবে খায়, তত বেশি দুধ হয়। বুকের দুধের জায়গায় অন্য কিছু দিলে দুধ কমে যায়।"},"normal":{"en":"Frequent feeds, cluster feeding in the evening, soft breasts after the first weeks, and short feeds are all normal. The reliable signs are six or more wet nappies a day after day 5, regular stools, and steady weight gain.","bn":"ঘন ঘন খাওয়া, সন্ধ্যায় একটু পরপর খেতে চাওয়া, প্রথম কয়েক সপ্তাহ পর স্তন নরম লাগা, আর অল্প সময় ধরে খাওয়া, সবই স্বাভাবিক। নির্ভরযোগ্য লক্ষণ হলো পঞ্চম দিনের পর দিনে ৬ বা তার বেশি ভেজা ন্যাপি, নিয়মিত পায়খানা আর ঠিকমতো ওজন বাড়া।"},"do_now":{"en":["Count today''s wet nappies and stools","Feed whenever the baby shows hunger, at least 8 times in 24 hours, including at night","Check the latch at each feed","Offer both breasts at each feed"],"bn":["আজ কয়টা ভেজা ন্যাপি ও পায়খানা হলো গুনে দেখুন","শিশু খিদে দেখালেই খাওয়ান, ২৪ ঘণ্টায় অন্তত ৮ বার, রাতেও","প্রতিবার মুখে নেওয়া ঠিক আছে কিনা দেখুন","প্রতিবার দুই স্তনই দিন"]},"steps":{"en":["Spend more time skin-to-skin with the baby","If the baby is sleepy at the breast, switch sides when sucking slows","Hand-express after some feeds to signal the body to make more","Stop water, sugar water, dummies and other feeds unless a health worker advised them","Eat, drink and rest; ask the family to take over housework","Get the baby weighed and ask a health worker to watch a feed"],"bn":["শিশুকে আরও বেশি সময় খালি বুকে রাখুন","স্তনে শিশু ঘুমিয়ে পড়লে চোষা কমে এলেই অন্য স্তনে বদলান","কিছু খাওয়ানোর পর হাতে দুধ বের করুন, যাতে শরীর আরও দুধ তৈরির সংকেত পায়","স্বাস্থ্যকর্মী না বললে পানি, চিনির পানি, চুষনি ও অন্য খাবার বন্ধ করুন","খান, পানি পান করুন, বিশ্রাম নিন; ঘরের কাজ পরিবারকে নিতে বলুন","শিশুর ওজন মাপান, আর একজন স্বাস্থ্যকর্মীকে খাওয়ানো দেখতে বলুন"]},"avoid":{"en":["Starting formula because of a feeling, without checking the signs","Feeding by the clock and making the baby wait","Blaming the mother; worry and pressure can slow the milk flow"],"bn":["লক্ষণ না দেখে শুধু মনে হওয়ার কারণে ফর্মুলা শুরু করা","ঘড়ি ধরে খাওয়ানো, শিশুকে অপেক্ষা করানো","মাকে দোষ দেওয়া; দুশ্চিন্তা ও চাপে দুধের প্রবাহ কমে যেতে পারে"]},"example":{"en":"Shila''s mother-in-law said the baby cried because the milk was thin. Shila counted: eight wet nappies and three yellow stools that day. At the clinic, the baby had gained well. The health worker said, “Your milk is enough. She cries in the evening because babies do.” The family stopped talking about formula.","bn":"শিলার শাশুড়ি বললেন, দুধ পাতলা, তাই শিশু কাঁদে। শিলা গুনে দেখলেন: সেদিন আটটা ভেজা ন্যাপি আর তিনবার হলুদ পায়খানা। ক্লিনিকে দেখা গেল শিশুর ওজনও ভালো বেড়েছে। স্বাস্থ্যকর্মী বললেন, “আপনার দুধ যথেষ্ট। সন্ধ্যায় শিশুরা এমনিতেই কাঁদে।” এরপর বাড়িতে আর ফর্মুলার কথা ওঠেনি।"},"warning_signs":{"en":["Fewer than six wet nappies a day after day 5, or dark urine","Not back to birth weight by about two weeks, or losing weight","A very sleepy baby who does not wake for feeds","Sunken eyes, a dry mouth or a sunken soft spot on the head"],"bn":["পঞ্চম দিনের পর দিনে ৬টির কম ভেজা ন্যাপি, বা প্রস্রাব গাঢ়","প্রায় দুই সপ্তাহেও জন্মের ওজনে না ফেরা, বা ওজন কমা","শিশু খুব ঘুমকাতুরে, খাওয়ার জন্য জাগে না","চোখ বসে যাওয়া, মুখ শুকনো, বা মাথার তালুর নরম জায়গা বসে যাওয়া"]},"seek_help":{"en":["See a health worker within a day or two if you are worried, before adding anything","See a health worker today for any warning sign; go to hospital if the baby is very sleepy or not feeding"],"bn":["চিন্তা হলে কিছু যোগ করার আগে এক-দুই দিনের মধ্যে স্বাস্থ্যকর্মী দেখান","যেকোনো সতর্ক লক্ষণে আজই স্বাস্থ্যকর্মী দেখান; শিশু খুব ঘুমকাতুরে হলে বা না খেলে হাসপাতালে যান"]}}'::jsonb, 3, 0, 183, '{}'::text[], 'any', ARRAY['not enough milk', 'milk supply', 'formula', 'wet nappies', 'weight gain']::text[], false, 'in_review'::lp_review_status, 3032),
  ('nb-sore-cracked-nipples', 'scenario', 'scientific', 'mother', 'routine', 'guideline', '🩹', '{"en":"My nipples are sore or cracked","bn":"বোঁটায় ব্যথা, বা বোঁটা ফেটে গেছে"}'::jsonb, '{"en":"Ongoing pain usually means the latch needs fixing. Correct it, keep feeding, and the nipples can heal within days.","bn":"টানা ব্যথা সাধারণত বোঝায় মুখে নেওয়ার ধরন ঠিক করতে হবে। সেটা ঠিক করে খাওয়ানো চালিয়ে গেলে কয়েক দিনেই বোঁটা সেরে উঠতে পারে।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"Some tenderness in the first days is common. Pain that lasts through the whole feed, or cracks and bleeding, usually happen because the baby is sucking on the nipple instead of taking a big mouthful of breast.","bn":"প্রথম কয়েক দিন একটু ব্যথা সাধারণ। কিন্তু খাওয়ানোর পুরো সময় ব্যথা, বা বোঁটা ফেটে রক্ত পড়া সাধারণত হয় যখন শিশু স্তনের বড় অংশ মুখে না নিয়ে শুধু বোঁটা চোষে।"},"why":{"en":"In a shallow latch the nipple is squeezed against the hard roof of the baby''s mouth. In a deep latch it sits far back where it is not pressed.","bn":"অগভীরভাবে মুখে নিলে বোঁটা শিশুর মুখের শক্ত তালুতে চাপা খায়। গভীরভাবে মুখে নিলে বোঁটা অনেক ভেতরে থাকে, সেখানে চাপ পড়ে না।"},"normal":{"en":"A strong pull for the first few sucks, easing as the milk flows, is normal in the first week.","bn":"প্রথম সপ্তাহে প্রথম কয়েকটা টানে জোর লাগা, আর দুধ আসতে শুরু করলে কমে যাওয়া, স্বাভাবিক।"},"do_now":{"en":["Break the suction with a clean finger if it hurts, and latch again","Check for a wide mouth, lower lip turned out and chin on the breast","Start on the less sore side","After feeds, rub a few drops of breast milk on the nipple and let it air-dry"],"bn":["ব্যথা লাগলে পরিষ্কার আঙুল দিয়ে টান ছাড়িয়ে আবার মুখে দিন","দেখুন মুখ বড় করে খোলা, নিচের ঠোঁট উল্টানো, থুতনি স্তনে কিনা","যে পাশে ব্যথা কম সেদিক থেকে শুরু করুন","খাওয়ানোর পর কয়েক ফোঁটা বুকের দুধ বোঁটায় লাগিয়ে বাতাসে শুকাতে দিন"]},"steps":{"en":["Change feeding positions so pressure falls on different parts of the nipple","Wear loose, clean cotton clothing","If one side is too painful, hand-express it for a short time and give the milk by cup, then return to the breast","Ask a health worker to watch a feed and check the baby''s tongue"],"bn":["অবস্থান বদলে বদলে খাওয়ান, যাতে বোঁটার একই জায়গায় চাপ না পড়ে","ঢিলেঢালা, পরিষ্কার সুতির কাপড় পরুন","এক পাশে খুব ব্যথা হলে অল্প কিছু সময় সেদিকের দুধ হাতে বের করে কাপে খাওয়ান, তারপর আবার স্তনে ফিরুন","একজন স্বাস্থ্যকর্মীকে খাওয়ানো দেখতে আর শিশুর জিভ পরীক্ষা করতে বলুন"]},"avoid":{"en":["Soap, alcohol or perfumed creams on the nipples","Stopping breastfeeding suddenly, which can lead to engorgement and mastitis","Pulling the baby off without breaking the suction"],"bn":["বোঁটায় সাবান, অ্যালকোহল বা সুগন্ধি ক্রিম","হঠাৎ বুকের দুধ বন্ধ করা, এতে স্তন ফুলে স্তনপ্রদাহ হতে পারে","টান না ছাড়িয়ে শিশুকে টেনে সরানো"]},"example":{"en":"Nasrin cried before every feed because of a cracked nipple. Her sister, a nurse, watched and saw the baby''s lower lip tucked in. She helped Nasrin wait for a wide mouth and bring the baby in chin first. “That feels different,” Nasrin said. In four days the crack had healed.","bn":"বোঁটা ফেটে যাওয়ায় প্রতিবার খাওয়ানোর আগে নাসরিনের কান্না পেত। তাঁর বোন, যিনি নার্স, খাওয়ানো দেখে বুঝলেন শিশুর নিচের ঠোঁট ভেতরে ঢুকে থাকছে। তিনি নাসরিনকে শেখালেন বড় করে মুখ খোলার অপেক্ষা করতে আর থুতনি আগে রেখে শিশুকে আনতে। নাসরিন বললেন, “এবার তো অন্যরকম লাগছে!” চার দিনে ফাটাটা সেরে গেল।"},"warning_signs":{"en":["Fever, or a red, hot, painful area on the breast","Pus from a crack","White patches in the baby''s mouth with burning nipple pain"],"bn":["জ্বর, বা স্তনের কোনো অংশ লাল, গরম ও ব্যথা","ফাটা জায়গা থেকে পুঁজ","শিশুর মুখে সাদা দাগ, সাথে বোঁটায় জ্বালাপোড়া ব্যথা"]},"seek_help":{"en":["See a health worker if pain continues after you have corrected the latch, or cracks do not heal in a few days","See a health worker the same day for any warning sign"],"bn":["মুখে নেওয়া ঠিক করার পরও ব্যথা থাকলে, বা কয়েক দিনে ফাটা না সারলে স্বাস্থ্যকর্মী দেখান","যেকোনো সতর্ক লক্ষণে সেদিনই স্বাস্থ্যকর্মী দেখান"]}}'::jsonb, 3, 0, 183, '{}'::text[], 'any', ARRAY['sore nipples', 'cracked nipples', 'bleeding nipples', 'latch', 'pain']::text[], false, 'in_review'::lp_review_status, 3033),
  ('nb-spitting-up-vomiting', 'scenario', 'scientific', 'shared', 'important', 'consensus', '🤮', '{"en":"Spitting up or vomiting: what''s the difference?","bn":"দুধ তোলা নাকি বমি: পার্থক্য কী?"}'::jsonb, '{"en":"Bringing up small amounts of milk after feeds is very common and harmless. Green vomit, forceful vomiting after every feed, or a baby who is unwell needs a doctor.","bn":"খাওয়ার পর অল্প দুধ তুলে ফেলা খুব সাধারণ আর ক্ষতিকর নয়। কিন্তু সবুজ বমি, প্রতিবার খাওয়ার পর জোরে বমি, বা শিশু অসুস্থ মনে হলে ডাক্তার দেখাতে হবে।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"Spitting up is when milk flows back gently out of the mouth, often with a burp, soon after a feed. Vomiting is more forceful, brings up more, and may happen with the baby looking unwell.","bn":"দুধ তোলা হলো খাওয়ার কিছুক্ষণ পর, প্রায়ই ঢেকুরের সাথে, আস্তে করে মুখ দিয়ে দুধ বেরিয়ে আসা। বমি হয় জোরে, বেশি পরিমাণে, আর অনেক সময় শিশুকে অসুস্থ দেখায়।"},"why":{"en":"The valve at the top of a baby''s stomach is still weak, so milk easily comes back up. This improves as the baby grows, usually during the first year.","bn":"শিশুর পাকস্থলীর মুখের ভাল্ব এখনো দুর্বল, তাই দুধ সহজেই উঠে আসে। শিশু বড় হতে হতে, সাধারণত প্রথম বছরের মধ্যে, এটা ঠিক হয়ে যায়।"},"normal":{"en":"Spitting up small amounts once or several times a day is normal if the baby is feeding well, gaining weight, has wet nappies and seems content.","bn":"শিশু ঠিকমতো খেলে, ওজন বাড়লে, ন্যাপি ভিজলে আর তৃপ্ত থাকলে দিনে এক বা কয়েকবার অল্প দুধ তোলা স্বাভাবিক।"},"do_now":{"en":["Hold the baby upright during and for a while after feeds","Burp the baby during and after feeds","Keep breastfeeding as usual","Lay the baby on the back to sleep, as always"],"bn":["খাওয়ানোর সময় ও পরে কিছুক্ষণ শিশুকে সোজা করে ধরে রাখুন","খাওয়ানোর মাঝে ও পরে ঢেকুর তোলান","স্বাভাবিকভাবে বুকের দুধ চালিয়ে যান","ঘুমের সময় সবসময়ের মতো চিত করেই শোয়ান"]},"steps":{"en":["Avoid tight clothes or nappies around the tummy","Handle the baby gently after a feed; save play and tummy time for later","Watch the baby''s wet nappies and weight at check-ups","If vomiting is new or frequent, see a health worker"],"bn":["পেটের কাছে টাইট কাপড় বা ন্যাপি পরাবেন না","খাওয়ার পর শিশুকে আলতো করে নাড়াচাড়া করুন; খেলা ও উপুড় হয়ে থাকা পরে করুন","ভেজা ন্যাপি আর চেকআপে ওজন খেয়াল রাখুন","বমি নতুন শুরু হলে বা ঘন ঘন হলে স্বাস্থ্যকর্মী দেখান"]},"avoid":{"en":["Laying the baby on the tummy or propping them up to sleep","Giving water, gripe water or medicines that a doctor did not prescribe","Stopping breastfeeding"],"bn":["উপুড় করে বা উঁচু করে হেলান দিয়ে ঘুম পাড়ানো","ডাক্তার দেননি এমন পানি, গ্রাইপ ওয়াটার বা ওষুধ","বুকের দুধ বন্ধ করা"]},"example":{"en":"Sumon worried because his son brought up milk on his shoulder after most feeds. At the 6-week visit the baby had gained well. The doctor said, “He is a happy spitter. Keep him upright a little after feeds.” Sumon started keeping a cloth on his shoulder and stopped worrying.","bn":"বেশিরভাগ খাওয়ার পর ছেলে তাঁর কাঁধে দুধ তুলে দিত বলে সুমন চিন্তায় ছিলেন। ছয় সপ্তাহের চেকআপে দেখা গেল ওজন ভালো বেড়েছে। ডাক্তার বললেন, “ও হাসিখুশি থেকে দুধ তোলে, এতে সমস্যা নেই। খাওয়ার পর একটু সোজা করে রাখবেন।” সুমন কাঁধে একটা কাপড় রাখতে শুরু করলেন, আর দুশ্চিন্তাও কমল।"},"warning_signs":{"en":["Green or yellow-green vomit","Forceful vomiting after every feed, or vomiting everything","Blood in the vomit or stool","A swollen, hard belly","Fewer wet nappies, a dry mouth, or a very sleepy, floppy baby","Fever, or poor weight gain"],"bn":["সবুজ বা হলদে-সবুজ বমি","প্রতিবার খাওয়ার পর জোরে ছিটকে বমি, বা যা খায় সব বমি","বমি বা পায়খানায় রক্ত","পেট ফুলে শক্ত হয়ে যাওয়া","ভেজা ন্যাপি কম, মুখ শুকনো, বা শিশু খুব ঘুমঘুম ও নেতানো","জ্বর, বা ওজন ঠিকমতো না বাড়া"]},"seek_help":{"en":["Go to hospital now for green vomit, vomiting everything, a swollen belly, blood, or a very sleepy baby","See a health worker within a day for repeated forceful vomiting or poor weight gain"],"bn":["সবুজ বমি, সব বমি করে ফেলা, পেট ফোলা, রক্ত, বা শিশু খুব ঘুমঘুম হলে এখনই হাসপাতালে যান","বারবার জোরে বমি বা ওজন না বাড়লে এক দিনের মধ্যে স্বাস্থ্যকর্মী দেখান"]}}'::jsonb, 3, 0, 183, '{}'::text[], 'any', ARRAY['spitting up', 'posseting', 'vomiting', 'reflux', 'green vomit']::text[], false, 'in_review'::lp_review_status, 3034),
  ('nb-yellow-skin', 'scenario', 'scientific', 'shared', 'important', 'guideline', '🟡', '{"en":"My baby''s skin looks yellow","bn":"শিশুর ত্বক হলুদ দেখাচ্ছে"}'::jsonb, '{"en":"Mild yellowing on days 2 to 5 is common. Yellow on the first day, yellow palms and soles, or a sleepy baby means hospital today.","bn":"দ্বিতীয় থেকে পঞ্চম দিনে হালকা হলুদ ভাব সাধারণ। কিন্তু প্রথম দিনেই হলুদ, হাতের তালু ও পায়ের তলা হলুদ, বা শিশু ঘুমকাতুরে হলে আজই হাসপাতালে।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"Yellow skin and eyes in a newborn is jaundice, caused by a substance called bilirubin. Mild jaundice is very common in the first week and fades on its own. High levels can harm the brain, so the dangerous kind must be found quickly.","bn":"নবজাতকের ত্বক ও চোখ হলুদ হওয়াকে জন্ডিস বলে; বিলিরুবিন নামে একটা পদার্থ এর কারণ। প্রথম সপ্তাহে হালকা জন্ডিস খুবই সাধারণ, নিজে নিজেই সেরে যায়। কিন্তু মাত্রা বেশি হলে মস্তিষ্কের ক্ষতি হতে পারে, তাই বিপজ্জনক ধরনটা দ্রুত ধরা জরুরি।"},"why":{"en":"A newborn''s liver is still learning to clear bilirubin, and babies have extra red blood cells breaking down in the first days. Babies born early, or who are not feeding well, are more likely to be affected.","bn":"নবজাতকের যকৃৎ এখনো বিলিরুবিন সরাতে শিখছে, আর প্রথম কয়েক দিনে শিশুর বাড়তি লোহিত কণিকা ভাঙে। সময়ের আগে জন্মানো বা ঠিকমতো না খাওয়া শিশুদের এটা বেশি হয়।"},"normal":{"en":"Mild yellow on the face and chest that appears on day 2 or 3 and fades within about two weeks, in a baby who feeds well and is alert, is usually normal.","bn":"দ্বিতীয় বা তৃতীয় দিনে মুখ ও বুকে হালকা হলুদ ভাব, যা মোটামুটি দুই সপ্তাহে মিলিয়ে যায়, আর শিশু ভালো খায় ও সজাগ থাকে, তা সাধারণত স্বাভাবিক।"},"do_now":{"en":["Check in daylight: press the skin on the nose or chest and look at the colour","Check the palms, soles and the whites of the eyes","Breastfeed often, at least 8 times in 24 hours","Look at the colour of the stools and urine"],"bn":["দিনের আলোয় দেখুন: নাক বা বুকের ত্বকে চাপ দিয়ে রং দেখুন","হাতের তালু, পায়ের তলা আর চোখের সাদা অংশ দেখুন","ঘন ঘন বুকের দুধ দিন, ২৪ ঘণ্টায় অন্তত ৮ বার","পায়খানা ও প্রস্রাবের রং খেয়াল করুন"]},"steps":{"en":["Check every day for the first two weeks","Wake a sleepy baby gently for feeds","Show the baby to a health worker at the day 3 and week 1–2 check-ups","If the baby is treated with light therapy, keep breastfeeding during treatment"],"bn":["প্রথম দুই সপ্তাহ প্রতিদিন দেখুন","ঘুমকাতুরে শিশুকে খাওয়ানোর জন্য আলতো করে জাগান","তৃতীয় দিন আর প্রথম-দ্বিতীয় সপ্তাহের চেকআপে স্বাস্থ্যকর্মীকে দেখান","আলো দিয়ে চিকিৎসা চললেও বুকের দুধ চালিয়ে যান"]},"avoid":{"en":["Putting the baby in the sun as treatment","Giving water, glucose water or herbal remedies","Waiting when the warning signs are present"],"bn":["চিকিৎসা হিসেবে শিশুকে রোদে রাখা","পানি, গ্লুকোজের পানি বা ভেষজ কিছু দেওয়া","সতর্ক লক্ষণ থাকলেও অপেক্ষা করা"]},"example":{"en":"On day four, Mitu noticed her daughter''s face and chest looked yellow, and in the afternoon her palms looked yellow too. Her husband said, “Let''s not wait for the morning.” At the hospital a blood test showed a high level, and the baby had light therapy for two days while Mitu kept breastfeeding.","bn":"চতুর্থ দিনে মিতু দেখলেন মেয়ের মুখ আর বুক হলুদ লাগছে, বিকেলে হাতের তালুও হলুদ দেখাল। স্বামী বললেন, “সকাল পর্যন্ত অপেক্ষা না করি।” হাসপাতালে রক্ত পরীক্ষায় মাত্রা বেশি পাওয়া গেল। দুই দিন আলো দিয়ে চিকিৎসা চলল, আর মিতু বুকের দুধ খাওয়ানো চালিয়ে গেলেন।"},"warning_signs":{"en":["Yellow skin in the first 24 hours","Yellow palms and soles, or yellow down to the legs","A very sleepy baby, poor feeding, or a high-pitched cry","Pale, white or clay-coloured stools, or dark urine","Jaundice lasting more than 2 weeks (3 weeks if born early)"],"bn":["প্রথম ২৪ ঘণ্টার মধ্যেই ত্বক হলুদ","হাতের তালু ও পায়ের তলা হলুদ, বা পা পর্যন্ত হলুদ","শিশু খুব ঘুমকাতুরে, ঠিকমতো খাচ্ছে না, বা তীক্ষ্ণ গলায় কাঁদছে","ফ্যাকাশে, সাদা বা মাটির রঙের পায়খানা, বা গাঢ় প্রস্রাব","২ সপ্তাহের বেশি জন্ডিস (সময়ের আগে জন্মালে ৩ সপ্তাহ)"]},"seek_help":{"en":["Go to hospital today for any warning sign","See a health worker if you are unsure how yellow the baby is"],"bn":["যেকোনো সতর্ক লক্ষণে আজই হাসপাতালে যান","শিশু কতটা হলুদ বুঝতে না পারলে স্বাস্থ্যকর্মী দেখান"]}}'::jsonb, 3, 0, 28, '{}'::text[], 'any', ARRAY['jaundice', 'yellow skin', 'yellow eyes', 'phototherapy', 'pale stool']::text[], false, 'in_review'::lp_review_status, 3035),
  ('nb-fever-under-3-months', 'scenario', 'scientific', 'shared', 'important', 'guideline', '🌡️', '{"en":"Fever in a baby under 3 months: always go to hospital","bn":"৩ মাসের কম বয়সী শিশুর জ্বর: সবসময় হাসপাতালে"}'::jsonb, '{"en":"In a young baby, a fever can be the only sign of a serious infection. Do not wait or treat at home: get the baby seen today.","bn":"ছোট শিশুর ক্ষেত্রে জ্বরই হতে পারে মারাত্মক সংক্রমণের একমাত্র লক্ষণ। অপেক্ষা করবেন না, বাড়িতে চিকিৎসাও নয়: আজই শিশুকে দেখান।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"A baby under 2 months with a temperature of 37.5 °C or more, or a baby under 3 months with 38 °C or more, needs to be seen at a hospital the same day. A temperature below 35.5 °C is just as worrying.","bn":"২ মাসের কম বয়সী শিশুর তাপমাত্রা ৩৭.৫ °সে বা তার বেশি হলে, বা ৩ মাসের কম বয়সী শিশুর ৩৮ °সে বা তার বেশি হলে, সেদিনই হাসপাতালে দেখাতে হবে। তাপমাত্রা ৩৫.৫ °সে-এর নিচে নামাও সমান চিন্তার।"},"why":{"en":"Young babies cannot fight infection well, and infections of the blood, lungs, urine or brain can look mild at first and get worse within hours. Only an examination, and often tests, can tell what is going on.","bn":"ছোট শিশু সংক্রমণের সাথে ভালোভাবে লড়তে পারে না। রক্ত, ফুসফুস, প্রস্রাবের পথ বা মস্তিষ্কের সংক্রমণ শুরুতে হালকা মনে হলেও কয়েক ঘণ্টায় গুরুতর হতে পারে। শুধু পরীক্ষা, আর প্রায়ই কিছু টেস্ট করেই বোঝা যায় আসলে কী হচ্ছে।"},"normal":{"en":"A baby who feels warm after being wrapped up or held for a long time may simply be overdressed. Remove a layer and check again after 15 to 30 minutes. If the temperature is still high, go.","bn":"অনেকক্ষণ মুড়িয়ে রাখলে বা কোলে থাকলে শিশুর গা গরম লাগতে পারে, তা হয়তো শুধু বেশি কাপড়ের কারণে। এক পরত খুলে ১৫-৩০ মিনিট পর আবার মাপুন। তখনো বেশি থাকলে হাসপাতালে যান।"},"do_now":{"en":["Measure the temperature with a thermometer under the arm","Go to the nearest hospital today; at night, do not wait for the morning","Keep breastfeeding, including on the way","Dress the baby normally, not wrapped up heavily"],"bn":["বগলের নিচে থার্মোমিটার দিয়ে তাপমাত্রা মাপুন","আজই নিকটস্থ হাসপাতালে যান; রাতে হলে সকালের অপেক্ষা করবেন না","বুকের দুধ চালিয়ে যান, যাওয়ার পথেও","স্বাভাবিক কাপড় পরান, ভারী করে মুড়িয়ে নয়"]},"steps":{"en":["Take the vaccine card and note when the fever started and what the baby has had","Tell the staff the baby''s age in weeks","If a vaccine was given in the last day or two, mention it, but still go"],"bn":["টিকা কার্ড সাথে নিন, আর কখন জ্বর শুরু হলো, শিশুকে কী দেওয়া হয়েছে লিখে নিন","কর্মীদের শিশুর বয়স সপ্তাহে বলুন","গত এক-দুই দিনে টিকা দেওয়া হলে তা জানান, তবু অবশ্যই যান"]},"avoid":{"en":["Giving fever medicine before a doctor has seen the baby, unless a doctor told you to","Cold-water sponging or wrapping the baby in many layers","Herbal remedies, oil rubs or waiting to see if it passes"],"bn":["ডাক্তার না বললে, শিশুকে দেখানোর আগেই জ্বরের ওষুধ দেওয়া","ঠান্ডা পানি দিয়ে গা মোছা, বা অনেক পরত কাপড়ে মুড়িয়ে রাখা","ভেষজ কিছু, তেল মালিশ, বা নিজে নিজে সারে কিনা দেখার অপেক্ষা"]},"example":{"en":"At midnight, seven-week-old Rafi felt hot. His mother measured 38.2 °C. His grandmother said to wait until morning, but his father said, “The health worker told us: under three months, fever means hospital.” They went that night, and Rafi was treated for a urine infection.","bn":"মাঝরাতে সাত সপ্তাহের রাফির গা গরম লাগল। মা মেপে দেখলেন ৩৮.২ °সে। দাদি সকাল পর্যন্ত অপেক্ষা করতে বললেন, কিন্তু বাবা বললেন, “স্বাস্থ্যকর্মী বলেছিলেন, তিন মাসের কম বয়সে জ্বর মানেই হাসপাতাল।” তাঁরা সেই রাতেই গেলেন, আর রাফির প্রস্রাবের সংক্রমণের চিকিৎসা হলো।"},"warning_signs":{"en":["Not feeding, or vomiting everything","Fits","Fast breathing or chest pulling in","Very sleepy, floppy, or moves only when touched","A rash that does not fade when pressed","A bulging soft spot on the head"],"bn":["খাচ্ছে না, বা সব বমি করে ফেলছে","খিঁচুনি","দ্রুত শ্বাস বা বুক ভেতরে ঢুকে যাওয়া","খুব ঘুমঘুম, নেতানো, বা ছুঁলে তবেই নড়ে","চাপ দিলেও মিলিয়ে যায় না এমন র‍্যাশ","মাথার তালুর নরম জায়গা ফুলে ওঠা"]},"seek_help":{"en":["Go to hospital today for any fever in a baby under 3 months","Call 999 or go now if any warning sign is present"],"bn":["৩ মাসের কম বয়সী শিশুর যেকোনো জ্বরে আজই হাসপাতালে যান","কোনো সতর্ক লক্ষণ থাকলে ৯৯৯-এ ফোন করুন বা এখনই যান"]}}'::jsonb, 2, 0, 92, '{}'::text[], 'any', ARRAY['fever', 'temperature', 'young infant', 'hospital', 'thermometer']::text[], false, 'in_review'::lp_review_status, 3036),
  ('nb-blocked-nose-cold', 'scenario', 'scientific', 'shared', 'routine', 'guideline', '🤧', '{"en":"Blocked nose or a cold","bn":"নাক বন্ধ বা সর্দি"}'::jsonb, '{"en":"Young babies breathe mainly through the nose, so a blocked nose can make feeding hard. Simple care helps; watch the breathing closely.","bn":"ছোট শিশু মূলত নাক দিয়ে শ্বাস নেয়, তাই নাক বন্ধ থাকলে খেতে কষ্ট হয়। সহজ যত্নেই উপকার হয়; তবে শ্বাস-প্রশ্বাস ভালো করে খেয়াল রাখুন।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"Many newborns sound snuffly even without a cold, because their nasal passages are small. A cold adds a runny or blocked nose, sneezing and sometimes a mild cough. Most colds get better in a week or so.","bn":"নাকের পথ সরু হওয়ায় সর্দি ছাড়াও অনেক নবজাতকের নাক দিয়ে ঘড়ঘড় শব্দ হয়। সর্দি হলে নাক দিয়ে পানি পড়ে বা বন্ধ থাকে, হাঁচি হয়, কখনো হালকা কাশিও। বেশিরভাগ সর্দি মোটামুটি এক সপ্তাহে সেরে যায়।"},"why":{"en":"Colds are caused by viruses, which antibiotics do not treat. The main risks in a young baby are trouble feeding and the cold turning into a chest infection such as pneumonia.","bn":"সর্দি হয় ভাইরাসের কারণে, অ্যান্টিবায়োটিকে তা সারে না। ছোট শিশুর ক্ষেত্রে মূল ঝুঁকি হলো খেতে কষ্ট হওয়া, আর সর্দি থেকে নিউমোনিয়ার মতো বুকের সংক্রমণ হয়ে যাওয়া।"},"normal":{"en":"Snuffly breathing, sneezing and a little clear or white mucus in a baby who feeds well, breathes calmly and has no fever.","bn":"শিশু ঠিকমতো খেলে, শান্তভাবে শ্বাস নিলে আর জ্বর না থাকলে নাক ঘড়ঘড় করা, হাঁচি আর অল্প স্বচ্ছ বা সাদা সর্দি।"},"do_now":{"en":["Keep breastfeeding; offer shorter, more frequent feeds if the baby tires","Put a few drops of saline nose drops in each nostril before feeds, if a health worker or pharmacist has advised them","Gently wipe the nose with a soft, clean cloth","Count the baby''s breaths for one full minute while they are calm"],"bn":["বুকের দুধ চালিয়ে যান; শিশু ক্লান্ত হলে অল্প অল্প করে ঘন ঘন দিন","স্বাস্থ্যকর্মী বা ফার্মেসি থেকে পরামর্শ পেলে খাওয়ানোর আগে প্রতিটি নাকে কয়েক ফোঁটা স্যালাইন নাকের ড্রপ দিন","নরম, পরিষ্কার কাপড় দিয়ে আলতো করে নাক মুছে দিন","শিশু শান্ত থাকার সময় পুরো এক মিনিট ধরে শ্বাস গুনুন"]},"steps":{"en":["Keep the room free of smoke, including cooking smoke and mosquito coils","Wash hands before handling the baby, and keep people with colds at a distance","Keep the baby warm but not overdressed","Lay the baby on the back to sleep as usual"],"bn":["ঘর ধোঁয়ামুক্ত রাখুন, রান্নার ধোঁয়া ও মশার কয়েলসহ","শিশুকে ধরার আগে হাত ধুয়ে নিন, সর্দি-কাশি আছে এমন মানুষকে দূরে রাখুন","শিশুকে উষ্ণ রাখুন, তবে বেশি কাপড় নয়","সবসময়ের মতো চিত করে ঘুম পাড়ান"]},"avoid":{"en":["Oil, mustard oil or anything else in the nose","Cough and cold medicines, vapour rubs or antibiotics without a doctor","Sucking the nose hard with the mouth or poking inside with cotton buds"],"bn":["নাকে তেল, সরিষার তেল বা অন্য কিছু","ডাক্তারের পরামর্শ ছাড়া কাশি-সর্দির ওষুধ, মলম বা অ্যান্টিবায়োটিক","মুখ দিয়ে জোরে নাক টেনে নেওয়া, বা কটন বাড দিয়ে নাকের ভেতরে খোঁচানো"]},"example":{"en":"When her elder son brought a cold home, Farzana''s five-week-old started sneezing and snuffling. She gave saline drops before feeds and fed more often. That evening she counted his breaths: 48 in a minute, calm, no chest pulling in. She kept watching, and the cold cleared in a week.","bn":"বড় ছেলে বাড়িতে সর্দি নিয়ে আসার পর ফারজানার পাঁচ সপ্তাহের শিশুর হাঁচি আর নাক ঘড়ঘড় শুরু হলো। তিনি খাওয়ানোর আগে স্যালাইন ড্রপ দিলেন, আর ঘন ঘন খাওয়ালেন। সন্ধ্যায় শ্বাস গুনে দেখলেন: মিনিটে ৪৮, শান্ত, বুক ভেতরে ঢুকছে না। তিনি নজর রাখলেন, আর এক সপ্তাহে সর্দি সেরে গেল।"},"warning_signs":{"en":["Fast breathing: 60 or more breaths a minute under 2 months, 50 or more from 2 months","The lower chest pulling in with each breath, grunting, or noisy breathing when calm","Blue lips, or pauses in breathing","Not able to feed","Fever, or a temperature below 35.5 °C","Very sleepy or floppy"],"bn":["দ্রুত শ্বাস: ২ মাসের কম বয়সে মিনিটে ৬০ বা তার বেশি, ২ মাস থেকে ৫০ বা তার বেশি","প্রতি শ্বাসে বুকের নিচের অংশ ভেতরে ঢুকে যাওয়া, কোঁকানো, বা শান্ত অবস্থাতেও শব্দ করে শ্বাস","ঠোঁট নীল, বা শ্বাস থেমে থেমে যাওয়া","খেতে না পারা","জ্বর, বা তাপমাত্রা ৩৫.৫ °সে-এর নিচে","খুব ঘুমঘুম বা নেতানো"]},"seek_help":{"en":["Go to hospital now for any warning sign","See a health worker if the cold lasts more than a week, the cough gets worse, or feeding is hard"],"bn":["যেকোনো সতর্ক লক্ষণে এখনই হাসপাতালে যান","সর্দি এক সপ্তাহের বেশি থাকলে, কাশি বাড়লে, বা খেতে কষ্ট হলে স্বাস্থ্যকর্মী দেখান"]}}'::jsonb, 3, 0, 183, '{}'::text[], 'any', ARRAY['blocked nose', 'cold', 'cough', 'saline drops', 'fast breathing', 'pneumonia']::text[], false, 'in_review'::lp_review_status, 3037),
  ('nb-loose-stools-diarrhoea', 'scenario', 'scientific', 'shared', 'important', 'guideline', '💩', '{"en":"Loose stools in a breastfed baby, or diarrhoea?","bn":"বুকের দুধ খাওয়া শিশুর পাতলা পায়খানা, নাকি ডায়রিয়া?"}'::jsonb, '{"en":"A breastfed baby''s stools are normally soft, yellow and frequent. Diarrhoea is a sudden change to more, and more watery, stools, and needs care.","bn":"বুকের দুধ খাওয়া শিশুর পায়খানা সাধারণত নরম, হলুদ আর ঘন ঘন হয়। ডায়রিয়া মানে হঠাৎ করে আগের চেয়ে বেশিবার আর বেশি পানির মতো পায়খানা, যার যত্ন দরকার।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"Breastfed babies often pass yellow, seedy, loose stools, sometimes after every feed. This is normal. Diarrhoea is when the stools suddenly become more frequent and watery than your baby''s usual pattern, sometimes with mucus or blood.","bn":"বুকের দুধ খাওয়া শিশু প্রায়ই হলুদ, দানাদার, নরম-পাতলা পায়খানা করে, কখনো প্রতিবার খাওয়ার পর। এটা স্বাভাবিক। ডায়রিয়া হলো যখন হঠাৎ শিশুর স্বাভাবিকের চেয়ে বেশিবার আর পানির মতো পায়খানা হয়, কখনো সাথে আম বা রক্ত।"},"why":{"en":"Diarrhoea is usually caused by germs from unclean water, hands, bottles or food. Young babies lose water quickly and can become dehydrated within hours. Breast milk protects against diarrhoea and helps recovery.","bn":"ডায়রিয়া সাধারণত হয় অপরিষ্কার পানি, হাত, ফিডার বা খাবারের জীবাণু থেকে। ছোট শিশুর শরীর থেকে দ্রুত পানি বেরিয়ে যায়, কয়েক ঘণ্টায় পানিশূন্যতা হতে পারে। বুকের দুধ ডায়রিয়া থেকে বাঁচায়, সেরে উঠতেও সাহায্য করে।"},"normal":{"en":"Soft, yellow or mustard-coloured, seedy stools, several times a day, in a baby who feeds well, has wet nappies and seems well.","bn":"শিশু ভালো খেলে, ন্যাপি ভিজলে আর সুস্থ থাকলে দিনে কয়েকবার নরম, হলুদ বা সরিষা রঙের দানাদার পায়খানা।"},"do_now":{"en":["Breastfeed more often and for longer","Check for signs of dehydration: fewer wet nappies, dry mouth, sunken eyes, unusual sleepiness","See a health worker today; for a baby under 2 months, always","Give ORS and zinc only as your health worker advises"],"bn":["আরও ঘন ঘন আর বেশি সময় ধরে বুকের দুধ দিন","পানিশূন্যতার লক্ষণ দেখুন: ভেজা ন্যাপি কম, মুখ শুকনো, চোখ বসে যাওয়া, অস্বাভাবিক ঘুমঘুম ভাব","আজই স্বাস্থ্যকর্মী দেখান; ২ মাসের কম বয়সী শিশু হলে অবশ্যই","খাবার স্যালাইন ও জিংক শুধু স্বাস্থ্যকর্মী যেভাবে বলেন সেভাবে দিন"]},"steps":{"en":["If ORS is advised, mix a full packet with the exact amount of clean water written on it and give by spoon or cup between breastfeeds","Wash your hands with soap after changing nappies and before feeding","Wash and dry cloth nappies well, and dispose of stools safely","Keep breastfeeding even if the baby vomits; give small amounts often"],"bn":["খাবার স্যালাইন দিতে বলা হলে প্যাকেটে লেখা সঠিক পরিমাণ পরিষ্কার পানিতে পুরো প্যাকেট গুলে বুকের দুধের মাঝে চামচ বা কাপে খাওয়ান","ন্যাপি বদলানোর পর আর খাওয়ানোর আগে সাবান দিয়ে হাত ধুয়ে নিন","কাপড়ের ন্যাপি ভালো করে ধুয়ে শুকান, পায়খানা নিরাপদে ফেলুন","শিশু বমি করলেও বুকের দুধ চালিয়ে যান; অল্প অল্প করে ঘন ঘন দিন"]},"avoid":{"en":["Stopping or reducing breastfeeding","Medicines to stop diarrhoea, or antibiotics, unless a doctor prescribes them","Sugary drinks, plain water instead of milk, or homemade mixtures with wrong amounts","Feeding bottles"],"bn":["বুকের দুধ বন্ধ করা বা কমিয়ে দেওয়া","ডাক্তার না দিলে ডায়রিয়া বন্ধের ওষুধ বা অ্যান্টিবায়োটিক","চিনিযুক্ত পানীয়, দুধের বদলে শুধু পানি, বা ভুল মাপে বানানো ঘরোয়া মিশ্রণ","ফিডার"]},"example":{"en":"Four-month-old Riya suddenly had eight watery stools in a morning, more than her usual soft three. Her mother kept breastfeeding and took her to the community clinic. The health worker found no dehydration, showed how to mix ORS and explained the zinc tablets. Riya was back to normal in a few days.","bn":"চার মাসের রিয়ার স্বাভাবিকভাবে দিনে তিনবার নরম পায়খানা হতো, হঠাৎ এক সকালেই আটবার পানির মতো হলো। মা বুকের দুধ চালিয়ে গেলেন আর তাকে কমিউনিটি ক্লিনিকে নিয়ে গেলেন। স্বাস্থ্যকর্মী দেখলেন পানিশূন্যতা নেই, খাবার স্যালাইন বানানো দেখিয়ে দিলেন আর জিংক ট্যাবলেট বুঝিয়ে দিলেন। কয়েক দিনেই রিয়া আগের মতো হয়ে গেল।"},"warning_signs":{"en":["Blood in the stool","Not able to breastfeed, or vomiting everything","Very sleepy, floppy or hard to wake","Sunken eyes, or skin that goes back slowly when pinched","Very few or no wet nappies","Fever in a baby under 3 months, or diarrhoea in a baby under 2 months who seems unwell"],"bn":["পায়খানায় রক্ত","বুকের দুধ খেতে পারছে না, বা সব বমি করছে","খুব ঘুমঘুম, নেতানো, বা জাগানো কঠিন","চোখ বসে যাওয়া, বা চামড়া চিমটি দিলে ধীরে ধীরে আগের জায়গায় ফেরা","খুব কম বা একদম ভেজা ন্যাপি না হওয়া","৩ মাসের কম বয়সী শিশুর জ্বর, বা ২ মাসের কম বয়সী শিশুর ডায়রিয়ার সাথে অসুস্থ ভাব"]},"seek_help":{"en":["Go to hospital now for any warning sign","See a health worker today for any diarrhoea in a baby under 6 months"],"bn":["যেকোনো সতর্ক লক্ষণে এখনই হাসপাতালে যান","৬ মাসের কম বয়সী শিশুর যেকোনো ডায়রিয়ায় আজই স্বাস্থ্যকর্মী দেখান"]}}'::jsonb, 3, 0, 183, '{}'::text[], 'any', ARRAY['loose stools', 'diarrhoea', 'breastfed stool', 'dehydration', 'ors', 'zinc']::text[], false, 'in_review'::lp_review_status, 3038),
  ('nb-no-poo-for-days', 'scenario', 'scientific', 'shared', 'routine', 'consensus', '🧷', '{"en":"My baby hasn''t pooed for days","bn":"শিশু কয়েক দিন ধরে পায়খানা করেনি"}'::jsonb, '{"en":"In the first weeks, few stools can mean the baby needs more milk. Later, a breastfed baby may go several days without a stool and be perfectly well.","bn":"প্রথম কয়েক সপ্তাহে কম পায়খানা মানে শিশুর হয়তো আরও দুধ দরকার। পরে বুকের দুধ খাওয়া শিশু কয়েক দিন পায়খানা না করেও পুরোপুরি সুস্থ থাকতে পারে।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"The first stool (meconium) is usually passed in the first day. In the first weeks, breastfed babies usually pass several soft stools a day. After about six weeks, some breastfed babies pass stools much less often, even once in several days, because their body uses almost all of the milk.","bn":"প্রথম পায়খানা (meconium) সাধারণত প্রথম দিনেই হয়। প্রথম কয়েক সপ্তাহে বুকের দুধ খাওয়া শিশু সাধারণত দিনে কয়েকবার নরম পায়খানা করে। মোটামুটি ছয় সপ্তাহ পর কিছু শিশু অনেক কম পায়খানা করে, কয়েক দিনে একবারও, কারণ শরীর দুধের প্রায় সবটুকুই কাজে লাগিয়ে ফেলে।"},"why":{"en":"In a young baby, few stools in the first weeks can be a sign of not getting enough milk. In an older breastfed baby with soft stools, a long gap is usually normal. Hard, pebble-like stools are true constipation.","bn":"ছোট শিশুর প্রথম কয়েক সপ্তাহে কম পায়খানা যথেষ্ট দুধ না পাওয়ার লক্ষণ হতে পারে। একটু বড় বুকের দুধ খাওয়া শিশুর পায়খানা নরম থাকলে লম্বা বিরতি সাধারণত স্বাভাবিক। শক্ত, ছোট ছোট গুটির মতো পায়খানাই আসল কোষ্ঠকাঠিন্য।"},"normal":{"en":"Going red in the face, grunting and straining before passing a soft stool is common in young babies. After six weeks, a breastfed baby who feeds well, has six or more wet nappies, a soft belly and soft stools when they come is fine even after several days.","bn":"নরম পায়খানা করার আগে মুখ লাল করে কোঁৎ দেওয়া, শব্দ করা ছোট শিশুদের মধ্যে খুব সাধারণ। ছয় সপ্তাহ পর যে শিশু ভালো খায়, দিনে ৬ বা তার বেশি ভেজা ন্যাপি হয়, পেট নরম থাকে আর পায়খানা হলে নরম হয়, সে কয়েক দিন না করলেও ঠিক আছে।"},"do_now":{"en":["Count the wet nappies today","Feel the baby''s belly: is it soft, or swollen and hard?","Under six weeks: feed more often and check the latch","Gently move the baby''s legs in a cycling motion and stroke the tummy"],"bn":["আজ কয়টা ভেজা ন্যাপি হলো গুনে দেখুন","শিশুর পেটে হাত দিয়ে দেখুন: নরম, নাকি ফোলা ও শক্ত?","ছয় সপ্তাহের কম বয়সে: আরও ঘন ঘন খাওয়ান, মুখে নেওয়া ঠিক আছে কিনা দেখুন","শিশুর পা আলতো করে সাইকেল চালানোর মতো নাড়ান, পেটে হাত বুলান"]},"steps":{"en":["Keep breastfeeding on demand","Give a warm bath to help the baby relax","Note the colour and texture of the next stool","See a health worker if the stools are hard or the baby seems uncomfortable"],"bn":["চাহিদামতো বুকের দুধ চালিয়ে যান","শিশুকে আরাম দিতে কুসুম গরম পানিতে গোসল করান","পরের পায়খানার রং ও ধরন খেয়াল করুন","পায়খানা শক্ত হলে বা শিশু অস্বস্তিতে থাকলে স্বাস্থ্যকর্মী দেখান"]},"avoid":{"en":["Putting a soap stick, oil, a twig or anything else into the baby''s bottom","Laxatives, herbal remedies or enemas without a doctor","Giving water, sugar water or honey"],"bn":["শিশুর মলদ্বারে সাবানের কাঠি, তেল, কাঠি বা অন্য কিছু ঢোকানো","ডাক্তার ছাড়া জোলাপ, ভেষজ ওষুধ বা ডুশ","পানি, চিনির পানি বা মধু খাওয়ানো"]},"example":{"en":"Two-month-old Nabil had not pooed for four days, and an aunt suggested a soap stick. His mother noticed he was feeding well, had plenty of wet nappies and a soft tummy. She waited, cycling his legs gently, and on day five he passed a large, soft, yellow stool.","bn":"দুই মাসের নাবিল চার দিন পায়খানা করেনি, এক খালা সাবানের কাঠি দিতে বললেন। মা খেয়াল করলেন সে ভালো খাচ্ছে, ভেজা ন্যাপিও যথেষ্ট, পেট নরম। তিনি অপেক্ষা করলেন, আলতো করে পা সাইকেলের মতো নাড়ালেন, আর পঞ্চম দিনে নাবিল অনেকটা নরম হলুদ পায়খানা করল।"},"warning_signs":{"en":["No stool at all in the first 24 to 48 hours of life","A swollen, hard belly","Green vomit, or vomiting with no stool","Not feeding, or very sleepy","Hard stools with blood","Few stools and few wet nappies in the first weeks"],"bn":["জন্মের প্রথম ২৪ থেকে ৪৮ ঘণ্টায় একবারও পায়খানা না হওয়া","পেট ফুলে শক্ত","সবুজ বমি, বা পায়খানা না হয়ে বমি","খাচ্ছে না, বা খুব ঘুমঘুম","শক্ত পায়খানার সাথে রক্ত","প্রথম কয়েক সপ্তাহে কম পায়খানা আর কম ভেজা ন্যাপি"]},"seek_help":{"en":["Go to hospital now for a swollen belly with vomiting, green vomit, or a baby who is not feeding","See a health worker for no stool in the first two days, hard stools, or few stools with few wet nappies in the first weeks"],"bn":["পেট ফোলার সাথে বমি, সবুজ বমি, বা শিশু না খেলে এখনই হাসপাতালে যান","প্রথম দুই দিনে পায়খানা না হলে, পায়খানা শক্ত হলে, বা প্রথম সপ্তাহগুলোতে কম পায়খানা ও কম ভেজা ন্যাপি হলে স্বাস্থ্যকর্মী দেখান"]}}'::jsonb, 3, 0, 183, '{}'::text[], 'any', ARRAY['constipation', 'no stool', 'straining', 'breastfed baby', 'meconium']::text[], false, 'in_review'::lp_review_status, 3039),
  ('nb-nappy-rash', 'scenario', 'scientific', 'shared', 'routine', 'consensus', '🩲', '{"en":"Nappy rash","bn":"ন্যাপির জায়গায় র‍্যাশ"}'::jsonb, '{"en":"Red, sore skin in the nappy area is common. Frequent changes, gentle cleaning and time without a nappy usually clear it in a few days.","bn":"ন্যাপির জায়গায় লাল, ব্যথাযুক্ত ত্বক খুব সাধারণ। ঘন ঘন বদলানো, আলতো পরিষ্কার আর কিছুক্ষণ ন্যাপি ছাড়া রাখলে সাধারণত কয়েক দিনে সেরে যায়।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"Nappy rash is redness and soreness on the bottom, genitals or thighs. The skin may look shiny, spotty or raw.","bn":"ন্যাপি র‍্যাশ হলো নিতম্ব, যৌনাঙ্গ বা উরুর ত্বক লাল হয়ে জ্বালা করা। ত্বক চকচকে, দানাদার বা ছিলে যাওয়ার মতো দেখাতে পারে।"},"why":{"en":"Urine and stool left on the skin, rubbing, tight nappies, soaps or wipes with perfume, and diarrhoea all irritate a baby''s skin. Sometimes a yeast infection (thrush) causes or worsens it.","bn":"ত্বকে প্রস্রাব-পায়খানা লেগে থাকা, ঘষা লাগা, টাইট ন্যাপি, সুগন্ধি সাবান বা ওয়াইপস, আর ডায়রিয়া, সবই শিশুর ত্বকে জ্বালা তৈরি করে। কখনো ছত্রাকের সংক্রমণ থেকেও হয় বা বেড়ে যায়।"},"normal":{"en":"Mild redness that improves within a few days of better nappy care, in a baby who is otherwise well.","bn":"অন্যভাবে সুস্থ শিশুর হালকা লালচে ভাব, যা ন্যাপির যত্ন ঠিক করলে কয়েক দিনে কমে আসে।"},"do_now":{"en":["Change wet or dirty nappies as soon as possible","Clean with plain warm water and a soft cloth, then pat dry","Leave the nappy off for a while each day on a clean cloth","Apply a thin layer of a barrier cream, such as a zinc-based cream, if you have one"],"bn":["ভেজা বা নোংরা ন্যাপি যত তাড়াতাড়ি সম্ভব বদলে দিন","শুধু কুসুম গরম পানি আর নরম কাপড়ে পরিষ্কার করে চেপে শুকিয়ে নিন","প্রতিদিন কিছুক্ষণ পরিষ্কার কাপড়ের ওপর ন্যাপি ছাড়া রাখুন","থাকলে জিংকযুক্ত ব্যারিয়ার ক্রিমের মতো ক্রিম পাতলা করে লাগান"]},"steps":{"en":["Use loose nappies, and avoid tight plastic covers","Wash cloth nappies with mild soap, rinse very well and dry them in the sun","Change after every stool, and check often","Look for spots at the edges or in skin folds, which can mean thrush"],"bn":["ঢিলা ন্যাপি পরান, টাইট প্লাস্টিকের কভার এড়িয়ে চলুন","কাপড়ের ন্যাপি হালকা সাবানে ধুয়ে খুব ভালো করে পানি দিয়ে ধুয়ে রোদে শুকান","প্রতিবার পায়খানার পর বদলান, আর ঘন ঘন দেখুন","কিনারায় বা ভাঁজে দানা আছে কিনা দেখুন; এটা ছত্রাকের লক্ষণ হতে পারে"]},"avoid":{"en":["Talcum powder","Perfumed soap, wipes with alcohol, or strong detergents","Steroid or antifungal creams without a health worker''s advice","Rubbing the skin hard"],"bn":["ট্যালকম পাউডার","সুগন্ধি সাবান, অ্যালকোহলযুক্ত ওয়াইপস বা কড়া ডিটারজেন্ট","স্বাস্থ্যকর্মীর পরামর্শ ছাড়া স্টেরয়েড বা ছত্রাকনাশক ক্রিম","জোরে ঘষে মোছা"]},"example":{"en":"Lima''s baby had a red bottom after a few days of loose stools. She started changing him straight after each stool, washing with warm water, and letting him kick on a cloth without a nappy after his bath. In three days the skin was calm again.","bn":"কয়েক দিন পাতলা পায়খানার পর লিমার শিশুর নিতম্ব লাল হয়ে গেল। লিমা প্রতিবার পায়খানার সাথে সাথে ন্যাপি বদলাতে শুরু করলেন, কুসুম গরম পানিতে ধুয়ে দিলেন, আর গোসলের পর কাপড়ের ওপর ন্যাপি ছাড়া হাত-পা ছুড়তে দিলেন। তিন দিনে ত্বক আবার শান্ত হলো।"},"warning_signs":{"en":["Blisters, pus-filled spots or open sores","Bright red rash with small spots at the edges or in skin folds","Rash spreading beyond the nappy area","Fever, or a baby who is unwell or not feeding"],"bn":["ফোসকা, পুঁজভরা দানা বা খোলা ঘা","উজ্জ্বল লাল র‍্যাশ, কিনারায় বা ভাঁজে ছোট ছোট দানা","ন্যাপির জায়গা ছাড়িয়ে র‍্যাশ ছড়ানো","জ্বর, বা শিশু অসুস্থ বা খাচ্ছে না"]},"seek_help":{"en":["See a health worker if the rash does not improve in 3 to 4 days or shows any warning sign","Go to hospital for a young baby with a rash and fever"],"bn":["৩-৪ দিনে র‍্যাশ না কমলে বা কোনো সতর্ক লক্ষণ থাকলে স্বাস্থ্যকর্মী দেখান","ছোট শিশুর র‍্যাশের সাথে জ্বর হলে হাসপাতালে যান"]}}'::jsonb, 2, 0, 183, '{}'::text[], 'any', ARRAY['nappy rash', 'diaper rash', 'barrier cream', 'cloth nappy', 'thrush']::text[], false, 'in_review'::lp_review_status, 3040),
  ('nb-red-smelly-cord', 'scenario', 'scientific', 'shared', 'important', 'guideline', '🔴', '{"en":"The cord looks red, has pus or smells bad","bn":"নাভি লাল, পুঁজ, বা দুর্গন্ধ"}'::jsonb, '{"en":"These can be signs of a cord infection, which can spread quickly in a newborn. See a health worker today; go to hospital at once if the baby is unwell.","bn":"এগুলো নাভির সংক্রমণের লক্ষণ হতে পারে, যা নবজাতকের শরীরে দ্রুত ছড়াতে পারে। আজই স্বাস্থ্যকর্মী দেখান; শিশু অসুস্থ মনে হলে সাথে সাথে হাসপাতালে যান।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"A healing cord stump is dry, dark and may be a little sticky where it meets the skin. Redness on the skin around it, pus, swelling or a bad smell suggest infection.","bn":"শুকাতে থাকা নাভি শুকনো ও কালচে থাকে, আর ত্বকের সাথে মেলার জায়গায় একটু আঠালো হতে পারে। চারপাশের ত্বক লাল হওয়া, পুঁজ, ফোলা বা দুর্গন্ধ সংক্রমণের ইঙ্গিত দেয়।"},"why":{"en":"The cord is an open path into the baby''s body until it heals. Germs from unclean hands or from things put on the cord can cause an infection that spreads into the blood.","bn":"নাভি না শুকানো পর্যন্ত এটা শিশুর শরীরে ঢোকার একটা খোলা পথ। অপরিষ্কার হাত বা নাভিতে লাগানো জিনিস থেকে জীবাণু ঢুকে সংক্রমণ রক্তে ছড়িয়ে পড়তে পারে।"},"normal":{"en":"A slightly moist or sticky base, a little dried blood, or a few drops of blood when the stump comes off are normal.","bn":"গোড়া একটু ভেজা বা আঠালো, সামান্য শুকনো রক্ত, বা নাভি খসার সময় কয়েক ফোঁটা রক্ত স্বাভাবিক।"},"do_now":{"en":["Wash your hands with soap before touching the area","Look closely: is the redness only at the base, or spreading onto the skin of the belly?","Check the baby''s temperature, feeding and alertness","See a health worker today"],"bn":["জায়গাটা ছোঁয়ার আগে সাবান দিয়ে হাত ধুয়ে নিন","ভালো করে দেখুন: লালচে ভাব শুধু গোড়ায়, নাকি পেটের ত্বকে ছড়াচ্ছে?","শিশুর তাপমাত্রা, খাওয়া আর সজাগ ভাব দেখুন","আজই স্বাস্থ্যকর্মী দেখান"]},"steps":{"en":["Keep the cord clean, dry and open to the air","Fold the nappy below the cord","Use only what the health worker gives, exactly as advised","Return quickly if the redness spreads or the baby becomes unwell"],"bn":["নাভি পরিষ্কার, শুকনো আর বাতাসে খোলা রাখুন","ন্যাপি নাভির নিচে ভাঁজ করে পরান","শুধু স্বাস্থ্যকর্মী যা দেন, ঠিক যেভাবে বলেন সেভাবে ব্যবহার করুন","লালচে ভাব ছড়ালে বা শিশু অসুস্থ হলে দ্রুত আবার যান"]},"avoid":{"en":["Oil, ash, turmeric, cow dung, powder or herbal pastes on the cord","Covering it with a bandage or tight cloth","Waiting several days to see if it improves"],"bn":["নাভিতে তেল, ছাই, হলুদ, গোবর, পাউডার বা লতাপাতার বাটা","ব্যান্ডেজ বা শক্ত কাপড়ে ঢেকে রাখা","সারে কিনা দেখতে কয়েক দিন অপেক্ষা করা"]},"example":{"en":"On day six, Shahana smelled something bad at her son''s navel and saw a red ring around it. Her mother-in-law wanted to put mustard oil on it. Shahana said, “The nurse told us to put nothing on it and to come if it turned red.” At the Upazila Health Complex the baby was treated the same day.","bn":"ষষ্ঠ দিনে শাহানা ছেলের নাভি থেকে দুর্গন্ধ পেলেন, আর চারপাশে লাল একটা বৃত্ত দেখলেন। শাশুড়ি সরিষার তেল লাগাতে চাইলেন। শাহানা বললেন, “নার্স বলেছিলেন কিছু লাগাবেন না, আর লাল হলে চলে আসবেন।” উপজেলা স্বাস্থ্য কমপ্লেক্সে সেদিনই শিশুর চিকিৎসা হলো।"},"warning_signs":{"en":["Redness spreading onto the skin of the belly","Swelling or hardness around the navel","Fever, or the baby feels cold","Not feeding, very sleepy or floppy","Bleeding that does not stop"],"bn":["লালচে ভাব পেটের ত্বকে ছড়িয়ে পড়া","নাভির চারপাশ ফুলে বা শক্ত হয়ে যাওয়া","জ্বর, বা শিশুর গা ঠান্ডা","খাচ্ছে না, খুব ঘুমঘুম বা নেতানো","রক্তপাত না থামা"]},"seek_help":{"en":["See a health worker today for pus, a bad smell or redness at the base","Go to hospital now for spreading redness or any warning sign"],"bn":["পুঁজ, দুর্গন্ধ বা গোড়ায় লালচে ভাব থাকলে আজই স্বাস্থ্যকর্মী দেখান","লালচে ভাব ছড়ালে বা কোনো সতর্ক লক্ষণ থাকলে এখনই হাসপাতালে যান"]}}'::jsonb, 2, 0, 28, '{}'::text[], 'any', ARRAY['cord infection', 'omphalitis', 'red navel', 'pus', 'umbilical cord']::text[], false, 'in_review'::lp_review_status, 3041),
  ('nb-day-night-mixup', 'scenario', 'scientific', 'shared', 'routine', 'consensus', '🌙', '{"en":"My baby sleeps all day and is awake all night","bn":"শিশু সারাদিন ঘুমায়, আর সারারাত জেগে থাকে"}'::jsonb, '{"en":"Newborns do not yet know day from night. Light, activity and calm nights help their body clock settle over the first weeks.","bn":"নবজাতক এখনো দিন-রাতের পার্থক্য বোঝে না। দিনে আলো ও সক্রিয়তা, আর রাতে শান্ত পরিবেশ প্রথম কয়েক সপ্তাহে তার শরীরের ঘড়ি ঠিক করতে সাহায্য করে।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"In the womb, babies are often lulled to sleep by the mother''s movement in the day and become active at night. After birth it takes several weeks for their internal clock to follow day and night.","bn":"গর্ভে থাকার সময় দিনের বেলা মায়ের চলাফেরায় শিশু দোল খেয়ে ঘুমায়, আর রাতে সক্রিয় হয়। জন্মের পর শরীরের ভেতরের ঘড়ি দিন-রাতের সাথে মিলতে কয়েক সপ্তাহ লাগে।"},"why":{"en":"Daylight, normal daytime sounds and activity, and dark, quiet nights are signals that teach the baby''s body clock. Most babies begin to sleep longer at night by around two to three months.","bn":"দিনের আলো, দিনের স্বাভাবিক শব্দ ও কাজকর্ম, আর অন্ধকার, শান্ত রাত, এগুলোই শিশুর শরীরের ঘড়িকে শেখায়। বেশিরভাগ শিশু দুই-তিন মাসের দিকে রাতে একটু বেশি সময় ঘুমাতে শুরু করে।"},"normal":{"en":"Young babies sleep many hours in total and wake every few hours, day and night, to feed. Long awake times at night in the first weeks are common and usually temporary.","bn":"ছোট শিশু মোট অনেক ঘণ্টা ঘুমায়, আর দিন-রাত প্রতি কয়েক ঘণ্টায় খাওয়ার জন্য জাগে। প্রথম কয়েক সপ্তাহে রাতে অনেকক্ষণ জেগে থাকা সাধারণ, আর সাধারণত কিছুদিনের ব্যাপার।"},"do_now":{"en":["In the day, keep the curtains open and let the baby nap in normal light and household sounds","Talk and play when the baby is awake in the day","At night, keep the lights dim and voices low","Feed and change at night quietly, without play"],"bn":["দিনে পর্দা খোলা রাখুন, শিশুকে স্বাভাবিক আলো আর ঘরের শব্দের মধ্যেই ঘুমাতে দিন","দিনে শিশু জেগে থাকলে কথা বলুন, খেলুন","রাতে আলো কম আর গলা নিচু রাখুন","রাতে চুপচাপ খাওয়ান ও ন্যাপি বদলান, খেলা নয়"]},"steps":{"en":["Start a simple evening routine, such as a wipe-down, clean clothes, a feed and a lullaby","If your newborn sleeps through feeds in the day and feeds fewer than 8 times a day, wake them gently to feed","Take turns at night so each parent gets some sleep","Be patient: this usually settles within weeks"],"bn":["সন্ধ্যায় একটা সহজ রুটিন শুরু করুন, যেমন গা মুছে দেওয়া, পরিষ্কার জামা, খাওয়ানো আর ঘুমপাড়ানি গান","নবজাতক দিনে খাওয়ার সময়েও ঘুমিয়ে থাকলে আর দিনে ৮ বারের কম খেলে আলতো করে জাগিয়ে খাওয়ান","রাতে পালা করে জাগুন, যাতে দুজনেই কিছুটা ঘুমাতে পারেন","ধৈর্য ধরুন: সাধারণত কয়েক সপ্তাহে ঠিক হয়ে যায়"]},"avoid":{"en":["Keeping the baby awake all day to tire them out","Sleep medicines, ghutti or anything to make the baby sleep","Putting the baby to sleep on the tummy or with pillows to help them sleep longer","Screens or bright lights at night"],"bn":["ক্লান্ত করার জন্য সারাদিন শিশুকে জাগিয়ে রাখা","ঘুমের ওষুধ, ঘুট্টি বা ঘুম পাড়ানোর জন্য কিছু খাওয়ানো","বেশি ঘুমানোর জন্য উপুড় করে বা বালিশ দিয়ে শোয়ানো","রাতে মোবাইল-টিভি বা উজ্জ্বল আলো"]},"example":{"en":"Three-week-old Arisha slept through the noisy afternoons and was wide awake at 2 a.m. Her parents moved her daytime naps to the bright front room and kept nights dark, using only a small lamp for feeds. Her father did the late-evening settling. By eight weeks she was sleeping longer at night.","bn":"তিন সপ্তাহের আরিশা কোলাহলের বিকেলগুলো ঘুমিয়ে কাটাত, আর রাত ২টায় পুরো সজাগ। মা-বাবা দিনের ঘুম সামনের আলো-ভরা ঘরে সরিয়ে নিলেন, আর রাতে শুধু খাওয়ানোর জন্য ছোট একটা বাতি জ্বালাতেন। রাতের শুরুর দিকে ঘুম পাড়ানোর দায়িত্ব নিলেন বাবা। আট সপ্তাহের মধ্যে আরিশা রাতে বেশিক্ষণ ঘুমাতে লাগল।"},"warning_signs":{"en":["The baby is very hard to wake, or too sleepy to feed","Fewer wet nappies than usual","Fever, feeling cold, or breathing problems"],"bn":["শিশুকে জাগানো খুব কঠিন, বা খাওয়ার মতো জেগে থাকে না","স্বাভাবিকের চেয়ে কম ভেজা ন্যাপি","জ্বর, গা ঠান্ডা, বা শ্বাসের সমস্যা"]},"seek_help":{"en":["Go to hospital today if the baby is unusually hard to wake or not feeding","Talk to a health worker if you are struggling with lack of sleep"],"bn":["শিশুকে অস্বাভাবিকভাবে জাগানো কঠিন হলে বা না খেলে আজই হাসপাতালে যান","ঘুমের অভাবে খুব কষ্ট হলে স্বাস্থ্যকর্মীর সাথে কথা বলুন"]}}'::jsonb, 2, 0, 122, '{}'::text[], 'any', ARRAY['day night confusion', 'newborn sleep', 'night waking', 'sleep routine']::text[], false, 'in_review'::lp_review_status, 3042),
  ('nb-exhausted-and-crying', 'scenario', 'scientific', 'mother', 'important', 'guideline', '💜', '{"en":"“I''m exhausted and I keep crying”","bn":"“আমি খুব ক্লান্ত, শুধু কান্না পায়”"}'::jsonb, '{"en":"You are not failing; caring for a newborn is very hard. Rest and help come first. If the low mood lasts beyond two weeks, or you have frightening thoughts, get help.","bn":"আপনি ব্যর্থ নন; নবজাতকের যত্ন নেওয়া সত্যিই খুব কঠিন। আগে বিশ্রাম আর সাহায্য। মন খারাপ দুই সপ্তাহের বেশি থাকলে, বা ভয়ংকর চিন্তা এলে, সাহায্য নিন।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"Broken sleep, healing from birth, hormone changes and the constant needs of a newborn can leave any mother drained and tearful. In the first two weeks this is often the baby blues. When it lasts longer or feels heavier, it may be postpartum depression or anxiety, which are common and treatable.","bn":"ভাঙা ঘুম, প্রসবের পর সেরে ওঠা, হরমোনের পরিবর্তন আর নবজাতকের সারাক্ষণের চাহিদা যেকোনো মাকে ক্লান্ত ও কান্নাকাতর করে দিতে পারে। প্রথম দুই সপ্তাহে এটা প্রায়ই বেবি ব্লুজ। এর বেশি দিন থাকলে বা আরও ভারী লাগলে তা প্রসব-পরবর্তী বিষণ্নতা বা উদ্বেগ হতে পারে, যা সাধারণ আর চিকিৎসায় সারে।"},"why":{"en":"A mother''s wellbeing matters for her own sake and for the baby. A rested, supported mother finds it easier to feed, bond and recover. Asking for help early is part of caring for your baby.","bn":"মায়ের সুস্থতা তাঁর নিজের জন্যই গুরুত্বপূর্ণ, শিশুর জন্যও। বিশ্রাম ও সহায়তা পেলে মায়ের পক্ষে খাওয়ানো, বন্ধন গড়া আর সেরে ওঠা সহজ হয়। শুরুতেই সাহায্য চাওয়া শিশুর যত্নেরই অংশ।"},"normal":{"en":"Feeling tired, tearful, unsure or irritable at times in the early weeks, with good moments in between, is very common.","bn":"প্রথম সপ্তাহগুলোতে মাঝে মাঝে ক্লান্ত, কান্নাকাতর, অনিশ্চিত বা খিটখিটে লাগা, আবার মাঝে ভালো মুহূর্তও আসা, খুবই সাধারণ।"},"do_now":{"en":["If you feel overwhelmed while holding a crying baby, put the baby down safely on their back and take a few minutes to breathe","Tell your husband, mother or someone you trust exactly how you feel","Ask for one longer stretch of sleep while someone else watches the baby between feeds","Eat something and drink water now"],"bn":["কাঁদতে থাকা শিশুকে কোলে নিয়ে অসহায় লাগলে তাকে নিরাপদে চিত করে শুইয়ে কয়েক মিনিট শ্বাস নিন","স্বামী, মা বা বিশ্বস্ত কাউকে ঠিক কেমন লাগছে খুলে বলুন","দুই খাওয়ানোর মাঝে কেউ শিশুকে দেখুক, আর আপনি একটানা একটু বেশি ঘুমান, এমন সাহায্য চান","এখনই কিছু খান আর পানি পান করুন"]},"steps":{"en":["Let others take over cooking, cleaning and visitors","Get a little daylight and gentle movement each day","Lower your expectations of yourself; the baby needs a fed, loved mother, not a perfect one","Notice how long the low mood lasts; if it is more than two weeks, see a health worker","Talk about how you feel at your postnatal check-up"],"bn":["রান্না, ঘর পরিষ্কার আর অতিথি সামলানোর দায়িত্ব অন্যদের দিন","প্রতিদিন একটু দিনের আলো আর হালকা হাঁটাচলা করুন","নিজের কাছে প্রত্যাশা কমান; শিশুর দরকার একজন খেয়ে-দেয়ে থাকা, ভালোবাসার মা, নিখুঁত মা নয়","মন খারাপ কতদিন থাকছে খেয়াল করুন; দুই সপ্তাহের বেশি হলে স্বাস্থ্যকর্মী দেখান","প্রসব-পরবর্তী চেকআপে আপনার অনুভূতির কথা বলুন"]},"avoid":{"en":["Shaking the baby, ever","Keeping your feelings hidden because you feel ashamed","Taking sleeping pills or other medicines without a doctor"],"bn":["কখনো শিশুকে ঝাঁকানো","লজ্জায় অনুভূতি লুকিয়ে রাখা","ডাক্তার ছাড়া ঘুমের বড়ি বা অন্য ওষুধ খাওয়া"]},"example":{"en":"Three weeks after her caesarean, Tania cried every evening and felt she was a bad mother. One night she told her husband, “I can''t do this alone.” He took the baby after the 10 p.m. feed so she could sleep until the next one, and her mother came to cook. When the heavy feeling had not lifted after two more weeks, Tania spoke to the doctor at her check-up and started counselling.","bn":"সিজারের তিন সপ্তাহ পর তানিয়ার প্রতি সন্ধ্যায় কান্না পেত, মনে হতো সে খারাপ মা। এক রাতে স্বামীকে বললেন, “আমি একা পারছি না।” স্বামী রাত ১০টার খাওয়ানোর পর শিশুকে নিলেন, যাতে তানিয়া পরের খাওয়ানো পর্যন্ত ঘুমাতে পারেন, আর তানিয়ার মা এসে রান্নার দায়িত্ব নিলেন। আরও দুই সপ্তাহেও ভারী ভাবটা না কাটায় তানিয়া চেকআপে ডাক্তারকে জানালেন, আর কাউন্সেলিং শুরু করলেন।"},"warning_signs":{"en":["Low mood, hopelessness or no joy for more than two weeks","Not able to sleep even when you have the chance, or not eating","Feeling unable to care for yourself or the baby","Thoughts of harming yourself or the baby","Seeing or hearing things that others do not, or feeling very confused"],"bn":["দুই সপ্তাহের বেশি মন খারাপ, আশাহীনতা বা কোনো কিছুতে আনন্দ না পাওয়া","সুযোগ পেলেও ঘুম না আসা, বা খেতে না পারা","নিজের বা শিশুর যত্ন নিতে না পারার অনুভূতি","নিজের বা শিশুর ক্ষতি করার চিন্তা","অন্যরা দেখে না বা শোনে না এমন কিছু দেখা বা শোনা, বা খুব বিভ্রান্ত লাগা"]},"seek_help":{"en":["See a health worker if low mood lasts more than two weeks or is getting worse","Call 999 or go to the nearest hospital now if you have thoughts of harming yourself or the baby; do not stay alone"],"bn":["মন খারাপ দুই সপ্তাহের বেশি থাকলে বা বাড়তে থাকলে স্বাস্থ্যকর্মী দেখান","নিজের বা শিশুর ক্ষতির চিন্তা এলে এখনই ৯৯৯-এ ফোন করুন বা নিকটস্থ হাসপাতালে যান; একা থাকবেন না"]}}'::jsonb, 3, 0, 183, '{}'::text[], 'any', ARRAY['exhausted', 'crying', 'baby blues', 'postpartum depression', 'overwhelmed', 'support']::text[], false, 'in_review'::lp_review_status, 3043)
