INSERT INTO lp_task_templates (key, title, description, why, benefit, steps, safety_note, task_type, frequency, assignee, subject, min_day, max_day, estimated_minutes, xp, emoji, category_key, resource_slug, source_key, sex, review_status, sort_order) VALUES
  ('nb_nappy_check', '{"en":"Check today''s nappies: 6 or more wet","bn":"আজকের ন্যাপি দেখুন: ৬ বা তার বেশি ভেজা"}'::jsonb, '{"en":"At the end of the day, look back: how many wet nappies, and were there yellow stools?","bn":"দিনের শেষে মিলিয়ে দেখুন: কয়টা ভেজা ন্যাপি হলো, আর হলুদ পায়খানা হয়েছে কিনা।"}'::jsonb, '{"en":"After day 5, six or more wet nappies a day with pale urine, and regular yellow stools, show the baby is getting enough breast milk.","bn":"পঞ্চম দিনের পর দিনে ৬ বা তার বেশি ভেজা ন্যাপি, হালকা রঙের প্রস্রাব আর নিয়মিত হলুদ পায়খানা বোঝায় শিশু যথেষ্ট বুকের দুধ পাচ্ছে।"}'::jsonb, '{"en":"You can feel confident about feeding, or spot a problem early.","bn":"খাওয়ানো নিয়ে নিশ্চিন্ত থাকতে পারবেন, বা সমস্যা থাকলে আগেই ধরা পড়বে।"}'::jsonb, '[]'::jsonb, '{"en":"Fewer than six wet nappies, dark urine, a dry mouth or a very sleepy baby: see a health worker today.","bn":"৬টির কম ভেজা ন্যাপি, গাঢ় প্রস্রাব, মুখ শুকনো বা শিশু খুব ঘুমকাতুরে হলে আজই স্বাস্থ্যকর্মী দেখান।"}'::jsonb, 'observe', 'daily', 'any', 'child', 5, 42, 2, 5, '🧷', 'newborn_care', 'nb-bf-colostrum-supply', 'who_iycf', 'any', 'in_review'::lp_review_status, 3101),
  ('nb_jaundice_daylight_check', '{"en":"Check for yellow skin in daylight","bn":"দিনের আলোয় ত্বক হলুদ কিনা দেখুন"}'::jsonb, '{}'::jsonb, '{"en":"Mild jaundice is common in the first week, but yellow skin on day one, or yellow palms and soles, needs a hospital the same day.","bn":"প্রথম সপ্তাহে হালকা জন্ডিস সাধারণ, কিন্তু প্রথম দিনেই ত্বক হলুদ, বা হাতের তালু ও পায়ের তলা হলুদ হলে সেদিনই হাসপাতালে নিতে হয়।"}'::jsonb, '{"en":"Serious jaundice is caught early, when treatment is simple.","bn":"মারাত্মক জন্ডিস শুরুতেই ধরা পড়ে, যখন চিকিৎসা সহজ।"}'::jsonb, '[{"en":"Take the baby near a window in daylight","bn":"দিনের বেলা শিশুকে জানালার কাছে আলোয় নিন"},{"en":"Press a finger on the nose, forehead or chest for a second, then lift it","bn":"নাক, কপাল বা বুকে এক সেকেন্ড আঙুল চেপে ছেড়ে দিন"},{"en":"Look at the pressed skin, the whites of the eyes and the palms and soles","bn":"চাপ দেওয়া জায়গা, চোখের সাদা অংশ আর হাতের তালু ও পায়ের তলা দেখুন"}]'::jsonb, '{"en":"Yellow skin in the first 24 hours, yellow palms or soles, a very sleepy baby, or pale stools: go to hospital today. Do not treat jaundice with sunlight.","bn":"প্রথম ২৪ ঘণ্টায় ত্বক হলুদ, হাতের তালু বা পায়ের তলা হলুদ, শিশু খুব ঘুমকাতুরে, বা ফ্যাকাশে পায়খানা হলে আজই হাসপাতালে যান। রোদে রেখে জন্ডিসের চিকিৎসা করবেন না।"}'::jsonb, 'observe', 'daily', 'any', 'child', 0, 14, 2, 5, '🟡', 'newborn_care', 'nb-jaundice-explained', 'who_imci', 'any', 'in_review'::lp_review_status, 3102),
  ('nb_birth_registration', '{"en":"Register your baby''s birth","bn":"শিশুর জন্ম নিবন্ধন করুন"}'::jsonb, '{"en":"In Bangladesh, birth registration is done through the government''s online birth registration system, with help from your Union Parishad, Pourashava or City Corporation office.","bn":"বাংলাদেশে সরকারি অনলাইন জন্ম নিবন্ধন ব্যবস্থার মাধ্যমে জন্ম নিবন্ধন করা হয়; ইউনিয়ন পরিষদ, পৌরসভা বা সিটি কর্পোরেশন অফিস এতে সাহায্য করে।"}'::jsonb, '{"en":"A birth certificate is your child''s first legal identity, needed later for school admission, a passport and many services.","bn":"জন্ম সনদ শিশুর প্রথম আইনি পরিচয়; পরে স্কুলে ভর্তি, পাসপোর্টসহ নানা সেবায় এটা লাগে।"}'::jsonb, '{"en":"Doing it early is easier and saves trouble later.","bn":"আগেভাগে করলে সহজ হয়, পরে ঝামেলা বাঁচে।"}'::jsonb, '[{"en":"Keep the hospital discharge paper or birth record, and the parents'' national ID or birth certificates","bn":"হাসপাতালের ছাড়পত্র বা জন্মের কাগজ, আর মা-বাবার জাতীয় পরিচয়পত্র বা জন্ম সনদ গুছিয়ে রাখুন"},{"en":"Ask at your Union Parishad, Pourashava or City Corporation office which documents and steps apply","bn":"কোন কাগজ ও কী ধাপ লাগবে, ইউনিয়ন পরিষদ, পৌরসভা বা সিটি কর্পোরেশন অফিসে জিজ্ঞেস করুন"},{"en":"Check every spelling and date before the certificate is issued","bn":"সনদ দেওয়ার আগে প্রতিটি নামের বানান ও তারিখ মিলিয়ে নিন"}]'::jsonb, '{}'::jsonb, 'must_do', 'once', 'shared', 'child', 0, 183, 60, 20, '📄', 'newborn_care', NULL, NULL, 'any', 'in_review'::lp_review_status, 3103),
  ('nb_father_bath_time', '{"en":"Father''s bath time","bn":"বাবার গোসল করানোর সময়"}'::jsonb, '{}'::jsonb, '{"en":"Bathing is a close, hands-on time for a father and baby, and gives the mother a break.","bn":"গোসল করানো বাবা ও শিশুর কাছাকাছি, নিজের হাতে যত্নের একটা সময়, আর মাও একটু বিশ্রাম পান।"}'::jsonb, '{"en":"A stronger bond with your baby and more confidence in caring for them.","bn":"শিশুর সাথে বন্ধন গাঢ় হয়, আর যত্ন নেওয়ায় আত্মবিশ্বাস বাড়ে।"}'::jsonb, '[{"en":"Warm the room and get the towel, clothes and nappy ready first","bn":"আগে ঘর গরম করুন, তোয়ালে, জামা ও ন্যাপি গুছিয়ে রাখুন"},{"en":"Test the water with your elbow; it should feel warm, not hot","bn":"কনুই দিয়ে পানি দেখুন; কুসুম গরম হবে, গরম নয়"},{"en":"Support the head and neck, keep it short, talk and sing","bn":"মাথা ও ঘাড় ধরে রাখুন, অল্প সময়ে সারুন, কথা বলুন, গান করুন"},{"en":"Dry the skin folds well and dress the baby quickly","bn":"ত্বকের ভাঁজগুলো ভালো করে মুছে তাড়াতাড়ি জামা পরান"}]'::jsonb, '{"en":"Never leave the baby in or near water, even for a moment. Keep the cord dry until it has fallen off.","bn":"এক মুহূর্তের জন্যও শিশুকে পানিতে বা পানির কাছে একা রাখবেন না। নাভি না পড়া পর্যন্ত শুকনো রাখুন।"}'::jsonb, 'family', 'weekly', 'father', 'child', 7, 183, 20, 15, '🛁', 'fatherhood', 'nb-bathing-skin', NULL, 'any', 'in_review'::lp_review_status, 3104),
  ('nb_pelvic_floor_exercise', '{"en":"Pelvic floor exercises","bn":"তলপেটের মাংসপেশির ব্যায়াম"}'::jsonb, '{}'::jsonb, '{"en":"Pregnancy and birth stretch the muscles that hold urine and stool. Exercising them helps prevent and reduce leaking after birth.","bn":"গর্ভাবস্থা ও প্রসবে প্রস্রাব-পায়খানা আটকে রাখার মাংসপেশি ঢিলা হয়ে যায়। এগুলোর ব্যায়াম করলে প্রসবের পর প্রস্রাব চুইয়ে পড়া কমে ও প্রতিরোধ হয়।"}'::jsonb, '{"en":"Better bladder control and a stronger core as you recover.","bn":"প্রস্রাবের ওপর নিয়ন্ত্রণ ফেরে, শরীরের মাঝের অংশ শক্ত হয়।"}'::jsonb, '[{"en":"Sit or lie comfortably and breathe normally","bn":"আরাম করে বসুন বা শুয়ে স্বাভাবিকভাবে শ্বাস নিন"},{"en":"Squeeze the muscles you would use to stop passing urine and wind, and lift them up","bn":"প্রস্রাব ও বায়ু আটকাতে যে মাংসপেশি ব্যবহার করেন, সেগুলো চেপে ওপরের দিকে টেনে ধরুন"},{"en":"Hold for a few seconds, then relax fully; repeat about 10 times","bn":"কয়েক সেকেন্ড ধরে রাখুন, তারপর পুরো ঢিলা দিন; প্রায় ১০ বার করুন"},{"en":"Then do 10 quick squeezes; aim for three sets a day","bn":"তারপর ১০ বার দ্রুত চাপ দিন; দিনে তিনবার করার চেষ্টা করুন"}]'::jsonb, '{"en":"Start gently when you feel comfortable; after a caesarean or a bad tear, ask your health worker when to begin. Do not practise by stopping urine midstream. Leaking that does not improve needs a check.","bn":"যখন আরাম বোধ করবেন তখন আস্তে শুরু করুন; সিজার বা বেশি ছেঁড়া থাকলে কখন শুরু করবেন স্বাস্থ্যকর্মীকে জিজ্ঞেস করুন। প্রস্রাবের মাঝখানে থামিয়ে অনুশীলন করবেন না। চুইয়ে পড়া না কমলে দেখিয়ে নিন।"}'::jsonb, 'recommended', 'daily', 'mother', 'child', 0, 90, 5, 5, '🌷', 'mother_recovery', 'nb-mother-body-recovery', 'who_postnatal_2022', 'any', 'in_review'::lp_review_status, 3105),
  ('nb_family_mother_sleep', '{"en":"Give the mother one longer stretch of sleep","bn":"মাকে একটানা একটু বেশি ঘুমের সুযোগ দিন"}'::jsonb, '{"en":"A family member takes the baby between feeds for a few hours, day or night, so the mother can sleep without interruption.","bn":"দুই খাওয়ানোর মাঝে কয়েক ঘণ্টা পরিবারের কেউ শিশুকে দেখবেন, দিনে বা রাতে, যাতে মা না ভেঙে ঘুমাতে পারেন।"}'::jsonb, '{"en":"Broken sleep is hard on recovery and mood. One longer sleep each day helps protect the mother''s wellbeing.","bn":"ভাঙা ঘুম সেরে ওঠা আর মনের ওপর চাপ ফেলে। প্রতিদিন একবার একটু লম্বা ঘুম মায়ের সুস্থতা রক্ষায় সাহায্য করে।"}'::jsonb, '{"en":"A more rested mother, and a family that shares the care.","bn":"মা বেশি বিশ্রাম পান, আর পরিবার মিলে যত্নের ভার ভাগ করে নেয়।"}'::jsonb, '[]'::jsonb, '{"en":"Bring the baby to the mother whenever they show hunger, so breastfeeding continues. Do not give other drinks or feeds instead.","bn":"শিশু খিদে দেখালেই মায়ের কাছে এনে দিন, যাতে বুকের দুধ খাওয়ানো চালু থাকে। বদলে অন্য পানীয় বা খাবার দেবেন না।"}'::jsonb, 'family', 'daily', 'shared', 'family', 0, 90, 120, 10, '🛌', 'mental_wellbeing', 'nb-blues-or-depression', 'who_perinatal_mental_health', 'any', 'in_review'::lp_review_status, 3106),
  ('nb_six_week_visit', '{"en":"6-week visit: mother''s check and baby''s first vaccines","bn":"ছয় সপ্তাহের দেখা: মায়ের চেকআপ ও শিশুর প্রথম টিকা"}'::jsonb, '{"en":"Plan one trip around 6 weeks for the mother''s postnatal check and the baby''s 6-week EPI vaccines.","bn":"প্রায় ৬ সপ্তাহে একবারের যাওয়াতেই মায়ের প্রসব-পরবর্তী চেকআপ আর শিশুর ৬ সপ্তাহের ইপিআই টিকার পরিকল্পনা করুন।"}'::jsonb, '{"en":"At about 6 weeks the mother''s healing, blood pressure, mood and family planning are reviewed, and the baby is due Penta 1, OPV 1, PCV 1 and fIPV 1.","bn":"প্রায় ৬ সপ্তাহে মায়ের সেরে ওঠা, রক্তচাপ, মন ও পরিবার পরিকল্পনা দেখা হয়, আর শিশুর পেন্টা-১, ওপিভি-১, পিসিভি-১ ও এফআইপিভি-১ দেওয়ার সময় হয়।"}'::jsonb, '{"en":"Both of you are checked and protected in one visit.","bn":"এক যাত্রাতেই দুজনের চেকআপ ও সুরক্ষা হয়ে যায়।"}'::jsonb, '[{"en":"Find out the EPI session day at your nearest centre","bn":"নিকটস্থ কেন্দ্রে ইপিআই টিকাদানের দিন জেনে নিন"},{"en":"Bring the baby''s vaccine card and the mother''s health card","bn":"শিশুর টিকা কার্ড আর মায়ের স্বাস্থ্য কার্ড সাথে নিন"},{"en":"Write down your questions about feeding, recovery, mood and family planning","bn":"খাওয়ানো, সেরে ওঠা, মন আর পরিবার পরিকল্পনা নিয়ে প্রশ্নগুলো লিখে নিন"}]'::jsonb, '{}'::jsonb, 'must_do', 'once', 'shared', 'child', 35, 70, 90, 25, '🗓️', 'mother_recovery', 'nb-checklist-first-6-weeks', 'who_postnatal_2022', 'any', 'in_review'::lp_review_status, 3107),
  ('nb_temperature_touch', '{"en":"Feel the baby''s tummy: warm, not hot or cold","bn":"শিশুর পেটে হাত দিয়ে দেখুন: উষ্ণ, গরম বা ঠান্ডা নয়"}'::jsonb, '{}'::jsonb, '{"en":"Young babies easily get too cold or too hot, and both a fever and a low temperature can be signs of serious illness.","bn":"ছোট শিশুর সহজেই ঠান্ডা লেগে যায় বা বেশি গরম হয়ে যায়, আর জ্বর ও শরীর ঠান্ডা হওয়া দুটোই মারাত্মক অসুখের লক্ষণ হতে পারে।"}'::jsonb, '{"en":"You keep the baby comfortable and notice illness early.","bn":"শিশু আরামে থাকে, আর অসুখ শুরুতেই চোখে পড়ে।"}'::jsonb, '[{"en":"Feel the tummy or back, not the hands and feet","bn":"হাত-পা নয়, পেট বা পিঠে হাত দিয়ে দেখুন"},{"en":"Cold: hold the baby skin-to-skin and add a layer; hot and sweaty: remove a layer","bn":"ঠান্ডা হলে: খালি বুকে জড়িয়ে ধরুন, এক পরত কাপড় বাড়ান; গরম ও ঘামলে: এক পরত খুলে দিন"},{"en":"If unsure, measure with a thermometer","bn":"নিশ্চিত না হলে থার্মোমিটারে মেপে নিন"}]'::jsonb, '{"en":"37.5 °C or above, below 35.5 °C, or a baby who stays cold after warming: go to hospital today.","bn":"৩৭.৫ °সে বা তার বেশি, ৩৫.৫ °সে-এর কম, বা গরম করার পরও শিশুর গা ঠান্ডা থাকলে আজই হাসপাতালে যান।"}'::jsonb, 'observe', 'daily', 'any', 'child', 0, 61, 1, 5, '🌡️', 'newborn_care', 'nb-keeping-warm-kangaroo', 'who_imci', 'any', 'in_review'::lp_review_status, 3108)
